window.__D("text/maamarim-melukatim/c018",{"p":[[1500390012,"<h3>בס\"ד. יום ב' פ' פינחס, י\"ט תמוז ה'תשכ\"ח<sup data-n=\"849\">*</sup></h3>\n<b>וחזקת</b> והיית לאיש<sup data-n=\"850\">1</sup>, הנה ידוע<sup data-n=\"851\">2</sup> שהמאמר שאמר אדמו\"ר (מהורש\"ב) נ\"ע ביום השביעי<sup data-n=\"852\">3</sup> דחגיגת הבר מצוה של בנו יחידו כ\"ק מו\"ח אדמו\"ר, י\"ט תמוז<sup data-n=\"853\">4</sup> תרנ\"ג [שמאמר זה הוא סיום וחותם ההמשך תפילין דמארי עלמא<sup data-n=\"854\">5</sup> שהתחיל לומר בי\"ב תמוז, יום הבר מצוה] היתה התחלתו בפסוק זה. – השייכות דפסוק זה (וחזקת והיית לאיש) לבר מצוה בפשטות היא, ע\"פ הידוע<sup data-n=\"855\">6</sup> דזה שבן שלש עשרה (דוקא) מחוייב במצוות הוא כי אז דוקא נק' בשם איש. וצריך להבין, דמכיון שבן י\"ג שנה נעשה איש (ע\"פ טבע), מהי ההדגשה לומר (בחגיגת בר מצוה) וחזקת והיית לאיש. וגם צריך להבין, הרי המעלה דבן י\"ג שנה היא שאז נעשה בר דעת<sup data-n=\"856\">7</sup>, דדעת הוא במוחין, ובפרט לפי המבואר בהמאמר ד\"ה איתא במדרש תילים תרנ\"ג [שהוא אחד המאמרים שחזר אותם כ\"ק מו\"ח אדמו\"ר בחגיגת הבר מצוה שלו]<sup data-n=\"857\">8</sup> שהמעלה דבן י\"ג שנה היא שאז יש לו עצם המוחין<sup data-n=\"858\">9</sup>, ומהו הדיוק בבן י\"ג שנה בהתואר איש שמורה<sup data-n=\"859\">10</sup> על המדות.ב) <b>והנה</b> בחלק ההמשך שנאמר אז<sup data-n=\"860\">11</sup> מבואר מעלת יוסף על יעקב, דההמשכה שע\"י יעקב היא באצילות וע\"י יוסף נמשך הגילוי (גם) בבי\"ע. [ויש לומר, דזה שבהמאמר ד\"ה וחזקת והיית לאיש מדבר בשבחו של יוסף, שמו הראשון של הבר מצוה, הוא גם בכדי לעורר אותו על העבודה המיוחדת דיוסף להמשיך הגילוי עד למטה מטה]. ובכדי לבאר גודל העילוי של יוסף, מבאר תחלה מעלתו של יעקב, שעי\"ז יובן גודל העילוי דיוסף שהוא נעלה עוד יותר. ומבאר זה בהקדים מ\"ש<sup data-n=\"861\">12</sup> אתה הוא הוי' לבדך את עשית את השמים גו' ואתה מחי' את כולם, שהם ג' מדריגות<sup data-n=\"862\">13</sup>. אתה הוא הוי' לבדך קאי על אוא\"ס שלפני הצמצום [ומפרט בזה ג' ענינים, אתה הוא והוי'. אתה הוא עצמות המאור, ואומר על זה אתה לשון נוכח, כי העצמות הוא בכל מקום בהתגלות<sup data-n=\"863\">14</sup>, דשם שמים שגור בפי כל. הוא והוי' הם ב' מדריגות בהאור, עצם האור (הוא), והתפשטות האור (הוי'), כמבואר בהמאמר. ואומר על זה לבדך, שאין כאן דבר זולת העצמות, כי כללות האור שלפני הצמצום, גם האור השייך לעולמות (הוי'), הוא כלול בעצמותו ואינו בבחי' מציאות<sup data-n=\"864\">15</sup>]. את עשית את השמים גו' הוא האור כמו שנעשה מקור להתהוות העולמות. ולכן כתיב את עשית, את חסר ה', כי האור, גם האור השייך לעולמות (הוי'), כמו שהוא לפני הצמצום, אינו בערך להיות מקור לעולמות, ובכדי שיהי' מקור לעולמות הוא ע\"י הצמצום, שנתעלם כל האור ונמשך רק קו קצר ומצומצם. וזהו את עשית את השמים גו' את חסר ה', דזה שהאור נעשה מקור לעולמות (עשית את השמים גו') הוא ע\"י שנחסר ונתמעט (את חסר ה'). ואתה מחי' את כולם הוא הקו שעל ידו נמשך חיות לעולמות, לאחרי שנתהוו. והיינו, שבהקו שני ענינים, שהוא קו קצר ומצומצם, ומצד זה הוא מהוה את העולמות (<i>מציאות</i> העולמות), ושהמשכתו היא מהאור שלפני הצמצום, ומצד זה הוא ממשיך חיות בעולמות (גילוי אלקות)<sup data-n=\"865\">16</sup>. וזהו שאתה זה (ואתה מחי' את כולם) הוא מלא ה' כמו אתה הראשון (אתה הוא הוי' לבדך), כי ענין זה שבהקו שהוא מחי' את כולם, הוא מצד זה שנמשך בו גילוי האור שלפני הצמצום.\n<b>ויש</b> לומר, דזהו שמביא בהמאמר (בהמשך לזה שואתה מחי' את כולם קאי על המשכת הקו) הלשון דהתקו\"ז<sup data-n=\"866\">17</sup> וההוא נביעו איהו כנשמתא לגופא דאיהי חיים לגופא, בכדי להדגיש, שהכוונה בואתה מחי' את כולם כאן היא לא לענין ההתהוות(אל תקרי מחי' אלא מהוה<sup data-n=\"867\">18</sup>), אלא לענין החיות, כמו שהנשמה מחי' את הגוף<sup data-n=\"868\">19</sup>. וזהו שהקו הוא בריח התיכון, שהוא מבריח ומחבר בחינת אתה הוא הוי' לבדך עם בחי' את עשית את השמים גו', שגם בהעולמות שנתהוו ע\"י הצמצום (את חסר ה'), יומשך בהם גילוי אוא\"ס הבל\"ג שלפני הצמצום (אתה הוא הוי' לבדך).\nג) <b>והנה</b> זה שע\"י הקו נמשך הגילוי דאוא\"ס שלפני הצמצום בעולמות, מורה שיש בו יתרון גם לגבי האור שלפני הצמצום. דהאור שלפני הצמצום <i>נתעלם</i> ע\"י הצמצום, וההתעלמות שע\"י הצמצום היא גם באור הבל\"ג (שלמעלה מהאור השייך לעולמות), אלא שההתעלמות שבאור זה הוא שנתעלם ונכלל במקורו ואינו מאיר בגילוי בעולמות<sup data-n=\"869\">20</sup>. [דזה שמבואר בכ\"מ<sup data-n=\"870\">21</sup> שלגבי אור הבל\"ג אין הצמצום מסתיר, הוא בנוגע להאור (שבידיעתו ית' הוא מאיר בגילוי גם במקום החלל), אבל בנוגע להעולמות (שנתהוו מהצמצום), פעל הצמצום שהאור (הבל\"ג) לא יורגש בעולמות<sup data-n=\"871\">22</sup>]. וזה שע\"י הקו נמשך הגילוי בעולמות (שגם בעולמות יורגש הגילוי) מורה שיש בו יתרון על האור שלפני הצמצום, גם על אור הבל\"ג. וכמו שמבאר בהמאמר<sup data-n=\"872\">23</sup> דזה שהקו בוקע את חושך הצמצום, שכל בקיעה היא מצד תגבורת<sup data-n=\"873\">24</sup>, הוא מפני ששרש המשכתו הוא למעלה גם מהאור שלפני הצמצום. ויש לומר הביאור בזה, דזה שהאור שלפני הצמצום א\"א שיבוא בגילוי בהעולמות שנתהוו מהצמצום, הוא מפני שהאור (שהוא גילוי) והצמצום (שהוא העלם) הם הפכים. וזה שע\"י הקו נמשך הגילוי דאוא\"ס שלפני הצמצום, הוא מפני ששרש הקו הוא מת\"ת הנעלם<sup data-n=\"874\">25</sup>, שכולל ומחבר ההפכים, הגילוי והצמצום.\n<b>ועפ\"ז</b> יש לבאר שג' הענינים שבהפסוק (אתה הוא הוי' לבדך, אתה עשית את השמים, ואתה מחי' את כולם) שמתחילים בתיבת אתה, שאתה מורה על העצמות (כנ\"ל סעיף ב), הם ג' אופנים בגילוי העצמות. אתה הוא הוי' לבדך, הוא גילוי הא\"ס והבל\"ג דהעצמות, שהוא נמצא בכל מקום ושאין מציאות חוץ ממנו – אתה הוא הוי' <i>לבדך</i><sup data-n=\"875\">26</sup>. אתה עשית את השמים גו', הוא גילוי כח הגבול שבעצמות (היכולת שלא להאיר<sup data-n=\"876\">27</sup>), ולמעלה יותר – הענין דמציאותו מעצמותו, כידועשהתהוות היש (עשית את השמים גו') הוא רק בכח העצמות שמציאותו מעצמותו<sup data-n=\"877\">28</sup>. ואתה מחי' את כולם הוא גילוי הפשיטות דהעצמות שאינו מוגדר בהגדרים דגילוי והעלם ולכן הוא מחבר שניהם כאחד.\n<b>וזהו</b> מ\"ש ואתה מחי' את כולם, ואתה בתוס' וא\"ו, שמורה על הגילוי דעצמות אוא\"ס שבקו האמצעי (ת\"ת) שמחבר שני ההפכים דחסד וגבורה. וכידוע<sup data-n=\"878\">29</sup> בענין הגדול הגבור והנורא<sup data-n=\"879\">30</sup> שהם בג' הקוין חג\"ת, דמ\"ש והנורא בתוס' וא\"ו הוא כי בת\"ת ישנו הגילוי דעצמות אוא\"ס שלמעלה מהתחלקות קוין (א-ל עליון<sup data-n=\"880\">31</sup>), ועי\"ז הוא מחבר שני ההפכים דחו\"ג. וזהו גם מהביאורים בזה שיעקב (ת\"ת) הוא אותיות יבקע<sup data-n=\"881\">32</sup>, אז יבקע כשחר אורך<sup data-n=\"882\">33</sup>, כי זה שהאור (אור הקו) בוקע את חושך הצמצום (ונמשך גם בעולמות שנתהוו מהצמצום) הוא מפני ששרש המשכתו הוא מת\"ת (הנעלם), מדתו של יעקב.\nד) <b>והנה</b> ידוע שהמשכת הקו מסתיימת באצילות<sup data-n=\"883\">34</sup>, וכמבואר בהמאמר<sup data-n=\"884\">35</sup>, דזה שיעקב (אותיות יבקע, בקיעת הקו) הוא בריח התיכון המבריח מן הקצה אל הקצה<sup data-n=\"885\">36</sup>, הוא מקצה השמים דלעילא עד קצה השמים דלתתא. דקצה השמים דלתתא הוא סוף האצילות. ובכדי שיהי' הגילוי גם בבי\"ע, הוא ע\"י יוסף, כמ\"ש<sup data-n=\"886\">37</sup> ויוסף הוא השליט על הארץ, שע\"י יוסף נמשך הגילוי בארץ, בי\"ע. וזהו אלה תולדות יעקב יוסף<sup data-n=\"887\">38</sup>, דיוסף ממשיך הגילויים דיעקב שיאירו בבי\"ע. וע\"ד ההפרש בין האבות ומתן תורה (דיוסף שייך למתן תורה, כי מתן תורה הי' ע\"י משה שמשה ויקח משה את עצמות יוסף עמו<sup data-n=\"888\">39</sup>), דההמשכה שע\"י קיום המצוות דהאבות היתה באצילות, ובמ\"ת נתחדש שיומשך הגילוי גם בבי\"ע<sup data-n=\"889\">40</sup>.<b>והנה</b> מזה שאומר בהמאמר שיוסף ממשיך הגילויים <i>דיעקב</i> שיאירו בבי\"ע, משמע, דזה שיוסף ממשיך הגילוי בבי\"ע הוא לפי שיוסף הוא תולדות יעקב, היינו שעל ידו מתגלה הפנימיות דיעקב אותיות יבקע. כי מצד ענין הבקיעה (דאמיתית ענין הבקיעה הוא שאין בה מדידות והגבלות) אפשר להיות ההמשכה גם בבי\"ע, אלא שענין זה דיעקב (יבקע) נתגלה ע\"י יוסף.\n<b>ויובן</b> זה ע\"פ הידוע<sup data-n=\"890\">41</sup> דהטעם על זה שהמשכת הקו מסתיימת באצילות הוא כי הכוונה בהמשכת הקו היא שהאור יהי' בהתלבשות, והתלבשות האור יכולה להיות רק בהענינים (כלים ועולמות) שהם אלקות. ובכדי שתהי' המשכת וגילוי הקו בבי\"ע הוא ע\"י המשכת אור הסובב, שבכללות הוא האור שלפני הצמצום, ובהאור שלפני הצמצום גופא – אור הבל\"ג (שלמעלה מהאור שלהאיר העולמות). וי\"ל הביאור בזה, כי אור הבל\"ג, מכיון שלגבי' אין הצמצום מסתיר, הוא מאיר בגילוי (גם לאחרי הצמצום) בכל מקום, גם בבי\"ע, אלא שזהו רק בידיעתו ית' ובהעולמות אין זה נרגש (כנ\"ל סעיף ג), וע\"י שמאיר בהקו מהאור שלפני הצמצום, נעשה גם הקו באופן כזה, שהוא נמשך ומתגלה גם בבי\"ע.\n<b>ועפ\"ז</b> יש לבאר ההפרש בין הבקיעה דיעקב אותיות יבקע (כמו שהוא מצד עצמו) להבקיעה דיעקב אותיות יבקע כמו שנתגלה ע\"י יוסף, שהבקיעה דיעקב (מצד עצמו) היא פריצת<sup data-n=\"891\">42</sup> וביטול הגדרים דגילוי וצמצום [ע\"י גילוי הפשיטות (ת\"ת הנעלם) שאינו מוגדר בגדרים אלה], ועי\"ז נמשך הגילוי (גם) בעולמות שנתהוו מהצמצום. אבל עדיין נשארו הגדרים שבענין הגילוי עצמו, החילוק בין הגילוי שבבחינת סובב והגילוי שבבחינת התלבשות, שהגילוי שבבחינת סובב הוא בכל מקום והגילוי שבבחינת התלבשות יש בו מדידה והגבלה<sup data-n=\"892\">43</sup> שהוא יכול להיות רק בענינים שהם כלים לגילוי. והבקיעה דיעקב אותיות יבקע כמו שנתגלתה ע\"י יוסף היא פריצת וביטול גם דהגדרים שבענין הגילוי גופא, שגם הגילוי שבבחינת התלבשות יכול להיות בכל מקום.\nה) <b>ועפ\"ז</b> יש לבאר גם מ\"ש בהמאמר<sup data-n=\"893\">44</sup> דהטעם על זה שהגילוי בבי\"ע הוא דוקא ע\"י יוסף הוא כי יוסף הוא בחי' יסוד (גמר ההשפעה) ועיקר התענוג והשמחה הוא בגמר ההשפעה, כמבואר שם בארוכה. ולכן דוקא ע\"י יוסף נמשך הגילוי בבי\"ע. וצריך להבין מהי השייכות דענין הגילוי בבי\"ע להתענוג והשמחה שבגמר ההשפעה, ולמה אינו מספיק (בשביל גילוי זה) התענוג והשמחה שבתחלת ואמצע דההשפעה. וי\"ל הביאור בזה, דמעלת התענוג והשמחה שבגמר ההשפעה [שהכוונה כאן בגמר ההשפעה היא לזה שהשפע נתקבל בכי טוב אצל המקבל<sup data-n=\"894\">45</sup>] הואשהתענוג מגיע בהעצם שלמעלה משרש ההשפעה, וכידוע<sup data-n=\"895\">46</sup> בענין סוף מעשה במחשבה תחלה<sup data-n=\"896\">47</sup>, דסוף מעשה הוא קבלת ההשפעה, וזה מגיע במחשבה תחלה, היינו בהתחילה שלפני (ולמעלה מ)תחלת המחשבה, שרש ההשפעה. ולכן דוקא ע\"י התענוג והשמחה שבגמר ההשפעה נעשה פריצת וביטול גדרי הגילוי (השפעה), ועי\"ז, גם הגילוי שבבחינת התלבשות (גילוי הקו) מתגלה גם בבי\"ע.\nו) <b>וממשיך</b> בהמאמר, דזהו מ\"ש בשל\"ה<sup data-n=\"897\">48</sup> דיעקב הוא תפילין של ראש ויוסף הוא תפילין של יד, כי ע\"י תפילין של ראש נעשה החיבור (תפילין מלשון התחברות) דאוא\"ס המאציל עם הנאצלים, שממשיך תוספות אור באו\"א ובז\"א דאצילות, וע\"י תפילין של יד שהוא במלכות [כמ\"ש<sup data-n=\"898\">49</sup> וקשרתם לאות על ידכה, יד כהה<sup data-n=\"899\">50</sup>, דיד כהה היא המלכות] נעשה החיבור דאוא\"ס (גם) עם הנבראים. [דזהו מה שתש\"ר נק' בשם פאר<sup data-n=\"900\">51</sup>, כמו תכשיט שהאדם מתקשט בו<sup data-n=\"901\">52</sup>, ותפילין של יד<sup data-n=\"902\">53</sup> הם רק לבוש, כי בי\"ע הם לבושים וע\"ס דאצילות נק' בשם תיקונין<sup data-n=\"903\">54</sup>, דתיקונין הוא כמו תכשיטים<sup data-n=\"904\">55</sup>]. וזהו שיעקב הוא תש\"ר ויוסף תש\"י, כי יעקב הוא בריח התיכון שמבריח ומחבר אוא\"ס עם הנאצלים, ויוסף הוא מחבר [בן פורת יוסף<sup data-n=\"905\">56</sup>, פורת אותיות תופר<sup data-n=\"906\">57</sup>, תופר ומחבר] אוא\"ס עם הנבראים.\n<b>וצריך</b> להבין, דכיון שבכדי שתהי' המשכה בבי\"ע צ\"ל תחלה ההמשכה באצילות, למה מקדימין הנחת תש\"י לתש\"ר. ויש לומר הביאור בזה ע\"פ הידוע<sup data-n=\"907\">58</sup> שהמצוות דהקב\"ה שנעשים ע\"י שישראל מקיימים את המצוות הם נעלים יותר מהמצוות דהקב\"ה כמו שהם מצד עצמם. ויש להוסיף, דבמצות תפילין, ענין זה הואביותר. דמכיון שתפילין דמארי<sup data-n=\"908\">59</sup> עלמא מה כתיב בהו כו' ומי<sup data-n=\"909\">60</sup> כעמך ישראל גוי אחד בארץ<sup data-n=\"910\">61</sup>, דקוב\"ה משתבח בשבחייהו דישראל<sup data-n=\"910\">61</sup> – הרי בזה נוגע עוד יותר העבודה דישראל, הנחת תפילין דישראל. ולכן מקדימין הנחת תש\"י לתש\"ר, כי המעלה דעבודה היא בעיקר בהעבודה דיחודא תתאה (בי\"ע)<sup data-n=\"911\">62</sup>, ולכן העבודה דיחו\"ת מגעת למעלה יותר מהעבודה דיחו\"ע (אצילות), וההוספה שנעשית בתפילין דמארי עלמא [המשכת אוא\"ס באצילות (תש\"ר) ובי\"ע (תש\"י)] ע\"י הנחת תפילין דישראל, היא בעיקר ע\"י הנחת תש\"י<sup data-n=\"912\">63</sup>.\n<b>והנה</b> זה שע\"י קיום המצוות דישראל מיתוסף עילוי בהמצוות דהקב\"ה הוא<sup data-n=\"913\">64</sup>, כי ישראל עלו במחשבה<sup data-n=\"914\">65</sup>, מחשבה עצמית שלמעלה מכל הגילויים (גם מהגילוי דחפץ חסד<sup data-n=\"915\">66</sup> שהוא השרש והסיבה לכל הגילויים), ולכן ע\"י העבודה (קיום המצוות) דישראל מיתוסף עילוי בהמצוות דהקב\"ה. ועפ\"ז יש לומר עוד טעם על זה שההוספה בתפילין דמארי עלמא היא בעיקר ע\"י הנחת תש\"י, כי ההמשכה בבי\"ע (תש\"י) מגעת בהעצם שלמעלה משרש ההשפעה והגילוי (כנ\"ל סעיף ה), שבכללות הוא בחינת מחשבה עצמית הנ\"ל.\nז) <b>וזהו</b> וחזקת והיית לאיש, דזה שבן י\"ג שנה נעשה איש ע\"פ טבע, הוא ענין שמצד למעלה, מצד שהקב\"ה הטביע הטבע בהבריאה, ומכיון שעיקר המעלה דכל ענין הוא כשהוא בא ע\"י עבודת האדם (כנ\"ל בארוכה), לכן צ\"ל וחזקת והיית לאיש, שיהי' לאיש (גם) ע\"י עבודתו. ועפ\"ז יש לבאר גם הדיוק דוחזקת והיית <i>לאיש</i>, דאיש מורה על המדות, אף שהמעלה דבן י\"ג שנה היא בהמוחין, שיש לו עצם המוחין שלמעלה מענין המדות, כי המעלה דעבודת האדם שמגעת במחשבה העצמית היא בעיקר בהעבודה דהמשכת עצם המוחין (שלמעלה מענין המדות) בהמדות, ע\"ד המבואר לעיל בענין יוסף שממשיך גילוי האצילות (שלמעלה משרש הנבראים) בבי\"ע.\n<b>ויש</b> לקשר כ\"ז עם עבודתו של כ\"ק מו\"ח אדמו\"ר, יוסף שבדורנו<sup data-n=\"916\">67</sup>, שהמאמר ד\"ה וחזקת והיית לאיש נאמר בסיום וחותם חגיגת הבר מצוה שלו, שעבודתו העיקרית היתה יפוצו מעינותיך חוצה, שגם בחוצה הכי תחתון שאין חוצה למטהממנו<sup data-n=\"917\">68</sup> יומשכו (נוסף על מים שנמשכים מהמעינות, גם) המעינות עצמם. שזו (הפצת המעינות חוצה) היא ההכנה והכלי לאתי בקרוב ממש מר דא מלכא משיחא<sup data-n=\"918\">69</sup>.\n**********",[["849","*","יצא לאור ב<b>קונטרס י\"ט תמוז – תשמ\"ט</b>, \"לקראת ש\"ק פ' פינחס, י\"ט תמוז הבעל\"ט, יום כניסת כ\"ק אדמו\"ר מהוריי\"צ נ\"ע לבריתו של אאע\"ה (בשנת תר\"ם), ויום השביעי דחגיגת הבר מצוה שלו (בשנת תרנ\"ג) . . <i>י\"ג תמוז</i>,<i> חג הגאולה תשמ\"ט</i>\"."],["850","1","מלכים-א ב, ב."],["851","2","רשימת כ\"ק מו\"ח אדמו\"ר, נדפסה ב\"מפתח מאמרי ודרושי אדמו\"ר מהורש\"ב\" ע' 11 (ובהוצאת תשמ\"א – ע' סד), נעתקה במאמר \"תפילין דמארי עלמא – תרנ\"ג\" (קה\"ת, תשכ\"ח) ע' 32. \"מפתח\" המאמרים שבריש סה\"מ תרנ\"ב-תרנ\"ג ס\"ע VII ואילך. הוספות לסה\"מ שם ע' שכה-שכו [קונטרס בר-מצוה תרנ\"ג (קה\"ת, תש\"ס)]."],["852","3","להעיר, שבר מצוה שייך לחתונה (זהר חדש יו\"ד, ג. טו, ד), ובחתונה – שבעת ימי המשתה."],["853","4","ח\"י תמוז (יום השביעי לי\"ב תמוז) הי' אז תענית (נדחה), ולכן הסיום דשבעת הימים הי' בי\"ט תמוז (רשימה שבהערה 2). ולהעיר, שי\"ט תמוז הוא יום הברית מילה שלו, שזה שייך לבר מצוה – כי \"גמר ועיקר כניסת נפש הקדושה הוא בי\"ג שנים ויום א' . . ותחלת כניסת נפש זו הקדושה היא . . במצות מילה\" (שו\"ע אדה\"ז או\"ח מהדו\"ב סוס\"ד)."],["854","5","נדפס בקונטרס \"תפילין דמארי עלמא\" הנ\"ל. ומשם – בסה\"מ הנ\"ל ע' רלג ואילך."],["855","6","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151302\" data-slug=\"likkutei-sichot\" data-id=\"1300151302\">לקו\"ש חט\"ו ע' 289</a>, ובהנסמן בהערות שם."],["856","7","ראה אנציקלופדי' תלמודית ערך גדול בתחלתו. <i>וש\"נ</i>. וראה קונטרס התפלה פ\"ה (ע' 15 ואילך). סה\"מ עת\"ר ע' קטו. המשך תער\"ב ח\"ג ע' א'רכז."],["857","8","נדפס בסה\"מ ה'תש\"ח ע' 271 ואילך, ומשם בהוספות לסה\"מ תרנ\"ב-תרנ\"ג ע' רעט ואילך. ועיי\"ש בשוה\"ג."],["858","9","סד\"ה הנ\"ל תרנ\"ג (סה\"מ ה'תש\"ח ע' 274. תרנ\"ג ע' רפב). וצע\"ק מפירוש המילות (לאדמו\"ר האמצעי) פ\"ב. ואכ\"מ."],["859","10","דאדם הוא השם ע\"ש השכל ואיש – ע\"ש המדות (סה\"מ ה'ש\"ת ע' 96. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו\"ת שה\"ש כה, א</a>. סה\"מ תרכ\"ט ע' קנז. ועוד).\nבלקו\"ש ח\"ד ע' 1117, שגם במוחין שני הענינים ד\"אדם\" ו\"איש\": מוחין השייכים למדות – איש, ועצם המוחין – אדם. אבל ע\"פ המובא בפנים מד\"ה איתא במדרש תילים דבן י\"ג שנה יש לו מוחין בעצם – הרי גם לפי ביאור זה הול\"ל אדם ולא איש. ועצ\"ע."],["860","11","פי\"ב – קונטרס הנ\"ל ע' 30 ואילך. סה\"מ תרנ\"ג שם ע' רנח ואילך."],["861","12","נחמי' ט, ו."],["862","13","בהבא לקמן, ראה גם סה\"מ תר\"ס ע' מג ואילך. ד\"ה בן פורת יוסף עזר\"ת (סה\"מ עזר\"ת ע' קיז ואילך). סה\"מ קונטרסים ח\"ב רצו, א ואילך. סה\"מ ה'תש\"א ע' 149. ובכ\"מ."],["863","14","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370064\" data-slug=\"torah-or\" data-id=\"3901370064\">תו\"א וירא יד, ב</a>."],["864","15","וראה המשך תרס\"ו ריש ע' קפב, דכללות האור שלפני הצמצום הוא רק יכולת."],["865","16","להעיר מסידור (עם דא\"ח) שער הק\"ש (עג, ג-ד) שהגוף דכל נברא הוא מהכלים והנפש שבו היא מהאורות. וי\"ל שעד\"ז הוא בנוגע לשני הענינים שבאור הקו – דזה שהוא קו קצר ומצומצם הוא דוגמת ענין הכלים."],["866","17","בהקדמה (\"פתח אליהו\") יז, א."],["867","18","הובא גם בשעהיוה\"א פ\"ב. ובכ\"מ. וראה סה\"מ ה'תש\"ד ע' 20 בהערה."],["868","19","אבל התהוות הגוף, וגם גידולו אח\"כ, היא <i>לא</i> מנשמתו (שעהיוה\"א פ\"ו – פא, א)."],["869","20","ראה בארוכה המשך תער\"ב ח\"ב ע' תתקלד ואילך ובכ\"מ, דפעולת הצמצום בהאור שלהאיר העולמות היא בהאור עצמו שנעשה בו ירידה והגבלה, ופעולת הצמצום באור הבל\"ג היא רק שלא יאיר במקום החלל."],["870","21","המשך תער\"ב שם ע' תתקצה. סה\"מ ה'תש\"ד ע' 226."],["871","22","ראה המשך תרס\"ו ע' תקא. ובכ\"מ."],["872","23","וראה גם סה\"מ עזר\"ת ע' קכא."],["873","24","ראה גם סידור (עם דא\"ח) רמח, א."],["874","25","ראה גם המשך תער\"ב ח\"א פ' רעג, דענין התגבורת שעל ידו נעשה בקיעת הקו הוא ההמשכה מת\"ת הנעלם."],["875","26","דנוסף לזה שאין שייך שיהי' מציאות ממש (לא הי' מקום לעמידת העולמות) – מכיון שקודם הצמצום נרגש בגילוי שהעצמות הוא בכל מקום, אין שייך שיהי' גם מציאות דאור (אף שהאור הוא גילוי המאור ולא מציאות ממש), וכנ\"ל ס\"ב שהאור שלפני הצמצום הוא כלול בעצמותו."],["876","27","ראה המשך תרס\"ו ע' קפח ואילך."],["877","28","אגה\"ק ס\"כ (קל, סע\"א ואילך). ולהעיר מהמבואר בכ\"מ, דזה שאת עשית גו' הוא בסמיכת לאתה הוא הוי' לבדך, הוא כי התהוות היש היא בכח העצמות (סה\"מ תרפ\"ו ע' לה. תרפ\"ח ע' קעג. תרצ\"ט ע' 231. ועוד)."],["878","29","לקו\"ת ואתחנן ח, א-ב. סידור (עם דא\"ח) שער הלולב רסב, א. שער החנוכה רעג, ד. סה\"מ תרס\"ה ע' נז ואילך ושם (ע' נח) בנוגע להקו."],["879","30","עקב י, יז. נחמי' ט, לב. תפלת העמידה בתחלתה."],["880","31","שבתפלת העמידה בא בהמשך ל\"והנורא\"."],["881","32","ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380111\" data-slug=\"likkutei-torah\" data-id=\"4001380111\">לקו\"ת צו (ח, סע\"ד</a>) מציין לע\"ח של\"א ספ\"א, ולפנינו הוא בשער לב (שער הארת המוחין). וראה ע\"ח שער הכללים פ\"י [ושם הובא הפסוק דלהלן]. זוהר הרקיע (לזח\"ג קד, א) קעז, ב."],["882","33","ישעי' נח, ח. וראה זח\"ג קד, א: יעקב אמר אז יבקע כשחר אורך."],["883","34","דזה שהארת הקו שבהכלים דמל' דאצילות בקע הפרסא עמהם ומאיר בהם בבי\"ע כמו באצילות (אגה\"ק שם – קלא, ב) – זה מאיר \"בהם\" דוקא, בהכלים דמל' דאצילות, אבל לא בבי\"ע עצמם (המשך תרס\"ו ס\"ע כא)."],["884","35","וכ\"ה בסה\"מ עזר\"ת ע' קכא ואילך. וראה גם בהנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151449\" data-slug=\"likkutei-sichot\" data-id=\"1300151449\">לקו\"ש חט\"ו ע' 436</a> הערה 28."],["885","36","זח\"ב קעה, ריש ע\"ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג (יט, א</a>)."],["886","37","מקץ מב, ו."],["887","38","וישב לז, ב. וראה בהנסמן בלקו\"ש שם."],["888","39","בשלח יג, יט."],["889","40","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370304\" data-slug=\"torah-or\" data-id=\"3901370304\">תו\"א יתרו סח, א</a> (הובא בהמאמר שם). ובכ\"מ."],["890","41","המשך תער\"ב ח\"א פקכ\"ט. סה\"מ ה'תש\"ג ס\"ע 131 ואילך."],["891","42","להעיר, שביעקב כתיב ופרצת (ויצא כח, יד. שבת קיח, ב)."],["892","43","כ\"ה הלשון במקומות שבהערה 41."],["893","44","וכ\"ה בסה\"מ עזר\"ת ע' קכא."],["894","45","ראה בהמאמר שהוא כמו אדם שמכין סעודה בשמחת בנו ומזמין קרואים לאכול, דעיקר שמחת ותענוגהבעל שמחה הוא בגמר הסעודה \"לאחר שכבר אכלו הקרואים כו' ומקבלים תענוג גדול מכל מה שאכלו ושבעו\", ו\"מזה מקבל בעל הסעודה עיקר התענוג\"."],["895","46","ראה בארוכה ד\"ה השם נפשנו בחיים תשכ\"ד (נעתק בקיצור ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061019\" data-slug=\"likkutei-sichot\" data-id=\"1300061019\">לקו\"ש ח\"ו ע' 19</a> הערה 57). וראה גם תו\"ח ד\"ה ויגש פ\"ב-ג (פט, סע\"א ואילך). המשך תער\"ב ח\"ב ע' א'קכ."],["896","47","פיוט \"לכה דודי\"."],["897","48","חלק תושב\"כ פ' ויחי (שה, א)."],["898","49","ואתחנן ו, ח."],["899","50","מנחות לז, א. זח\"ג רסט, א.\nבואתחנן שם: \"ידך\". ודרשת חז\"ל שם היא כנראה עה\"פ (בא יג, טז) והי' לאות על ידכה. אבל כ\"ה בזח\"ג שם. וכ\"ה בד\"ה תפילין דמארי עלמא הנ\"ל. וראה בניצוצי זהר שם."],["900","51","כמ\"ש (יחזקאל כד, יז) פארך חבוש עליך – ברכות יא, א. זח\"ג רל, ב. – הובא ברד\"ה תפילין דמארי עלמא הנ\"ל (קונטרס הנ\"ל ע' 3. סה\"מ שם ע' רלג)."],["901","52","ראה ד\"ה הנ\"ל שם, ובהנסמן שם."],["902","53","שלא כתיב בהם \"פאר\"."],["903","54","תיקו\"ז שבהערה 17."],["904","55","ראה בארוכה ד\"ה הנ\"ל פ\"ב (קונטרס הנ\"ל ע' 8. סה\"מ שם ע' רלו ואילך). הגהות לד\"ה פתח אלי' תרנ\"ח ע' ד. ובכ\"מ."],["905","56","ויחי מט, כב."],["906","57","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370135\" data-slug=\"torah-or\" data-id=\"3901370135\">תו\"א וישב כט, רע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380534\" data-slug=\"likkutei-torah\" data-id=\"4001380534\">לקו\"ת קרח נה, א</a>. מאמרי אדה\"ז ענינים ס\"ע תל. אוה\"ת ויחי תי, סע\"ב. ובכ\"מ."],["907","58","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לה, ג</a>. ד\"ה פדה בשלום ה'תשל\"ח ס\"ד (לעיל ח\"ב ע' קמה)."],["908","59","ראה ד\"ה את הוי' האמרת גו' ה'תש\"ל הערה 10 (לקמן ע' רנז)."],["909","60","דברי הימים-א יז, כא. וראה שם הערה 4."],["910","61","ברכות ו, א. יל\"ש עה\"פ ואתחנן ד, ז (רמז תתכה)."],["911","62","כי העבודה דיחו\"ע היא ע\"י שמאיר גילוי אור בנפשו, והעבודה דיחו\"ת היא מצד האדם העובד, ולכן מעלת העבודה (בכח עצמו) היא בעיקר בהעבודה דיחו\"ת (ראה עד\"ז המשך תרס\"ו ס\"ע שכז ואילך)."],["912","63","להעיר מאוה\"ת ר\"ה ע' א'שצט \"ויש בחי' בהכלה שהיא הגורמת בעטרה שעטרה לו אמו כו' כמו\"כ ע\"י תש\"י נמשך אח\"כ התש\"ר\"."],["913","64","ראה בארוכה ד\"ה זה היום דליל ערב ר\"ה ה'תשמ\"ב ס\"ה (לעיל ח\"א ע' מד) ואילך. ד\"ה אשה כי תזריע ה'תשכ\"ה ס\"ג (לעיל ח\"ג ע' קכג) ואילך."],["914","65","ב\"ר פ\"א, ד."],["915","66","לשון הכתוב – מיכה ז, יח."],["916","67","וראה בארוכה לקו\"ש ח\"ג ע' 835 ואילך. ובכ\"מ."],["917","68","ועד להחוצה דחצי כדור התחתון. ויש לומר שהוא ע\"ד יוסף שהי' במצרים המיצר שבהארץ."],["918","69","אגה\"ק הידועה דהבעש\"ט – נדפסה גם בריש ספר כתר שם טוב. ובכ\"מ."]]],[1500390013,"<h3>בס\"ד<sup data-n=\"919\">*</sup>. ש\"פ מטות-מסעי, מבה\"ח מנחם-אב ה'תשכ\"ב<sup data-n=\"920\">**</sup></h3>\n<b>גדול</b> יהי' כבוד הבית הזה האחרון מן הראשון<sup data-n=\"921\">1</sup>, ויש בזה שני פירושים<sup data-n=\"922\">2</sup>. פירוש הפשוט הוא<sup data-n=\"923\">3</sup> שבית הזה האחרון קאי על בית שני שהי' גדול מבית הראשון בבנין ובשנים, ובזהר<sup data-n=\"924\">4</sup> איתא שהבית הזה האחרון קאי על בית המקדש השלישי שיבנה במהרה בימינו שיהי' גדול מבית הראשון ומבית השני, דשניהם נכללים ב(מן ה)ראשון, כי שניהם לא הי' להם קיום, ובית שלישי יהי' קיים בקיום נצחי. וזהו שאמרו רז\"ל<sup data-n=\"925\">5</sup> לא כאברהם שכתוב בו הר ולא כיצחק שכתוב בו שדה אלא כיעקב שקראו בית, דבית ראשון הוא כנגד אברהם ובית שני כנגד יצחק ובית שלישי כנגד יעקב<sup data-n=\"926\">6</sup>, ומבואר בלקו\"ת<sup data-n=\"927\">7</sup> שהשייכות דבית שלישי ליעקב הוא כי מדתו של יעקב היא אמת, ואמת הוא שאין שייך בו הפסק<sup data-n=\"928\">8</sup> ושינוי.\nב) <b>והנה</b> אף שבמארז\"ל הנ\"ל (לא כאברהם כו') מדובר בביהמ\"ק, הלשון בלקו\"ת שם הוא שלש <i>גאולות</i> הן, גאולה ראשונה בזכות אברהם גאולה שני' בזכות יצחק גאולה שלישית בזכות יעקב. ומבאר שם <i>דגאולה</i> השלישית היא גאולה נצחית. והביאור בזה בפשטות הוא, כי מעיקרי הגאולה הוא – בנין בית המקדש<sup data-n=\"929\">9</sup>. וע\"י שמיתוסף עילוי בביהמ\"ק, הגאולה היא נעלית יותר<sup data-n=\"930\">10</sup>. ולכן מקשר בלקו\"ת המעלה דגאולה השלישית עם המעלה דביהמ\"ק השלישי.\n<b>ויש</b> להוסיף, דהטעם שבלקו\"ת מדבר במעלת <i>גאולה</i> השלישית הוא, כי הגאולה השלישית היא נעלית יותר מהמעלה דביהמ\"ק השלישי. כמובן מזה שהגאולה(קיבוץ גליות) תהי' <i>לאחרי</i> בנין ביהמ\"ק<sup data-n=\"931\">11</sup>. אלא שגם מעלה זו באה ע\"י ביהמ\"ק השלישי (שלכן היא נלמדת (בלקו\"ת) מהמעלה דביהמ\"ק השלישי) כי בבנין ביהמ\"ק השלישי יהיו כלולים כל הענינים והמעלות שיהיו לאח\"ז. וע\"פ מ\"ש בזהר<sup data-n=\"932\">12</sup> בסדר הענינים שיהיו לע\"ל דתחיית המתים הוא אחרון שבכולם, יש לומר, שגילוי המעלה דביהמ\"ק השלישי [אמת שאין שייך בו הפסק ושינוי] יהי' בעיקר בתחה\"מ, שאז יהיו חיים נצחיים. ויש לקשר זה עם מ\"ש<sup data-n=\"933\">13</sup> יחיינו מיומיים ביום השלישי יקימנו ונחי' לפניו, דביום השלישי שני פירושים. שקאי על ביהמ\"ק השלישי<sup data-n=\"934\">14</sup> ושקאי על תחה\"מ<sup data-n=\"935\">15</sup>. והקשר דשני הפירושים<sup data-n=\"936\">16</sup> הוא, כי בתחה\"מ תתגלה המעלה דביהמ\"ק השלישי.\nג) <b>ויובן</b> זה בהקדים מה שארז\"ל<sup data-n=\"937\">17</sup> עלה ארי' במזל ארי' והחריב את אריאל כו' על מנת שיבוא ארי' במזל ארי' ויבנה אריאל. ומזה מובן, דמ\"ש גדול יהי' כבוד הבית הזה האחרון יותר מן הראשון הוא גם באם ביהמ\"ק הראשון לא הי' נחרב והי' לו קיום נצחי. ולכן עלה ארי' כו' והחריב את אריאל בכדי שיבוא ארי' ויבנה אריאל, שיהי' גדול יותר מן הראשון (גם באם הי' לו קיום נצחי)<sup data-n=\"938\">18</sup>. וע\"ד המעלה דבעלי תשובה על צדיקים, דעבודת הצדיקים (גם צדיקים שאין להם יצר הרע<sup data-n=\"939\">19</sup>, שלכן אין שייך שיהי' אצלם חטא, ועבודתם היא באופן דקיום נצחי) מגעת בהשתלשלות, ועבודת הבעלי תשובה בלמעלה מהשתלשלות<sup data-n=\"940\">20</sup>. וזהו עלה ארי' והחריב את אריאל על מנת שיבוא ארי' ויבנה אריאל, וידוע<sup data-n=\"941\">21</sup> דיבוא ארי' [זה הקב\"ה, דכתיב בי'<sup data-n=\"942\">22</sup> ארי' שאג מי לא יירא<sup data-n=\"943\">23</sup>] הוא התגלות הכתר שלמעלה מהשתלשלות. ויש להוסיף, שגם לפי מארז\"ל<sup data-n=\"944\">24</sup> שכשעלו מבבל הי' ראוי להיות בנין זה (ביהמ\"ק השלישי), מ\"מ, בית שלישי שיהי' לע\"ל (לאחרי בית שני) יהי' גדול יותר. דהגם שגם כשעלו מבבל (לאחרי חורבן בית ראשון והתיקון על זה) היו בדוגמת בעלי תשובה<sup data-n=\"945\">25</sup>, הרי בתשובהיש ריבוי דרגות. ולכן הי' גם חורבן בית שני בכדי שע\"י העבודה בהגלות שלאחרי חורבן בית שני יגיעו לשלימות התשובה, ועי\"ז יהי' גדול כבוד הבית הזה האחרון בתכלית השלימות.\n<b>ועפ\"ז</b> יש לבאר מה שאמרו רז\"ל<sup data-n=\"946\">26</sup> עה\"פ<sup data-n=\"947\">27</sup> שמעו דבר ה' בית יעקב, שמעו דברי תורה עד שלא תשמעו דברי נבואה, שמעו דברי נבואה עד שלא תשמעו דברי תוכחות וכו' (ומסיים) שמעו גופיכון עד שלא ישמעו גרמיכון, העצמות<sup data-n=\"948\">28</sup> היבשות שמעו דבר ה'. ולכאורה זה שאומר שמעו דברי תורה עד שלא תשמעו דברי נבואה, יש לומר, כי דברי נבואה הם לצוות על דברי התורה<sup data-n=\"949\">29</sup>, ולכן באם היו שומעים דברי תורה לא היו צריכים לדברי נבואה. ועד\"ז בדברי נבואה עצמם, שבאם היו שומעים דברי נבואה דנביאים הראשונים המצַווים על דברי התורה שלא באופן דתוכחה לא היו צריכים לדברי תוכחה (ועד\"ז הוא בנוגע הענינים שלאח\"ז). אבל מה שמסיים עד שלא ישמעו גרמיכון כו' אינו מובן, איך שייך לומר שבאם היו שומעין דברי תורה או דברי תוכחות וכו' לא היו זוכים ח\"ו לתחה\"מ. ויש לומר הביאור בזה, דע\"י הירידה שלא שמעו דברי תורה וכו' תהי' תחה\"מ באופן נעלה יותר, בדוגמת ביהמ\"ק השלישי שע\"י שיהי' לאחרי הירידה דחורבן בית שני יהי' גדול יותר.\nד) <b>וביאור</b> מעלת בית השלישי על בית ראשון ושני (גם על בית שני כמו שהי' ראוי להיות בצורת התבנית דבית שלישי), יובן בהקדים המעלה דבית המקדש (בכלל)<sup data-n=\"950\">30</sup>, כולל גם המעלה דמקום המקדש, דמקום המקדש (גם לפני בנין ביהמ\"ק) הוא למעלה יותר מהמקום דכל העולם, כמ\"ש<sup data-n=\"951\">31</sup> מה נורא המקום הזה אין זה כי אם בית אלקים ותרגם אונקלוס לית דין אתר הדיוט. שהמקום דכל העולם הוא אתר הדיוט לפי שנברא בעשרה מאמרות שנקראים<sup data-n=\"952\">32</sup> מילין דהדיוטא, ומקום המקדש אינו אתר הדיוט [אף שגם מקום המקדש נברא בעשרה מאמרות. ואדרבה, התחלת ועיקר הבריאה מהעש\"מ היתה בריאת אבן שתי' שבמקדש וממנה הושתת כל העולם<sup data-n=\"953\">33</sup>], כי בעשרה מאמרות נאמר ויאמר אלקים, ובמקום המקדש הי' גילוי שם הוי' כמ\"ש<sup data-n=\"954\">34</sup> אכן יש הוי' במקום הזה.\n<b>וצריך</b> ביאור, דלכאורה, מעלת מקום המקדש על המקום דכל העולם הוא בהגילוי שהי' בביהמ\"ק ולא בהמקום עצמו, שהרי גם מקום המקדש נברא בעשרה מאמרות (מילין דהדיוטא), ופירוש לית דין אתר הדיוט הוא שהמקום עצמו אינו אתרהדיוט. ונקודת הביאור בזה ע\"פ מ\"ש בתניא<sup data-n=\"955\">35</sup> שהתהוות העולם היא משם הוי' (הוי' לשון מהווה<sup data-n=\"956\">36</sup>), אלא שבאם ההתהוות היתה משם הוי' עצמו הי' העולם בטל במציאות ולכן ההתהוות בפועל היתה ע\"י שם אלקים. וההתהוות דמקום המקדש היתה באופן ששם אלקים אינו מסתיר על שם הוי'. וזהו לית דין אתר הדיוט כי במקום המקדש הי' נרגש בגילוי ההתהוות כמו שהיא משם הוי'.\n<b>והענין</b> הוא, דההתהוות משם אלקים היא בדרך התלבשות (בראשית ברא אלקים<sup data-n=\"957\">37</sup>) וההתהוות משם הוי' היא באופן דבדרך ממילא (יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"958\">38</sup>). והחילוק שבאופן ההתהוות (אם ההתהוות היא בדרך ממילא או שהיא בדרך התלבשות) מורה על היחס של הדבר המתהווה להמקור שמהווה אותו. דכאשר המתהווה הוא בקירוב להמהווה, התהוותו היא בדרך ממילא<sup data-n=\"959\">39</sup>. וכמו עילה ועלול, דכיון שהעלול הוא בערך העילה, לכן התהוות העלול מהעילה היא בדרך ממילא [וכמו שכל ומדות, דכיון שהמדה היא בערך השכל, לכן, ע\"י ההתבוננות, באה ממילא המדה שבהתאם לההתבוננות]. וכמו\"כ הוא באור ומאור<sup data-n=\"960\">40</sup>, דכיון שהאור הוא גילוי המאור, לכן, המצאת האור מהמאור היא בדרך ממילא. וכאשר המתהווה הוא בריחוק מהמהווה, התהוותו היא בדרך התלבשות<sup data-n=\"959\">39</sup>, שהמהווה מתעסק ומשתדל להוות את הדבר המתהווה.\n[<b>והטעם</b> לזה הוא, דבהתהוות שבדרך ממילא עיקר ההדגשה הוא גילוי המקור. ולכן, הגם שגם בעילה ועלול (שהתהוות העלול מהעילה היא בדרך ממילא), העלול אינו גילוי העילה אלא מהות לעצמו, מ\"מ, נרגש בו העילה. וכמו שכל ומדות, שבהמדות נרגש השכל. ובכדי שיתהווה דבר שהוא בריחוק ממקורו, הוא דוקא בדרך התלבשות. דענין ההתלבשות הוא (לא שהמקור מתגלה, אלא אדרבה) הוא מתלבש (ומתעסק) להוות דבר חדש, ולכן, הדבר המתהווה ע\"י התלבשות הוא בריחוק ממקורו, באופן שלא נרגש בו מקורו. ויש לומר שהוא ע\"ד הענין דכח ופועל, דמהטעמים על זה שהמשכת הפעולה מהכח היא לא בדרך ממילא אלא ע\"י התלבשות (שהכח <i>פועל</i> את הפעולה), הוא כי הפעולה היא בריחוק מהכח. דהנה ידוע<sup data-n=\"961\">41</sup> שהפעולה היא התחדשות לגבי הכח. דכיון שהכח הוא רוחני והפעולה היא גשמית, הרי המשכת הפעולה מהכח היא (כמו) התהוות חדשה (<i>וע\"ד</i> יש מאין). וענין הכח הוא שבכחו לפעול דבר חדש. ומזה מובן, דזה שמהפעולה יודעים את הכח, הוא <i>שע\"י</i> הפעולה יודעים את הכח. אבל בהפעולה <i>עצמה</i> לא נרגש הכח<sup data-n=\"962\">42</sup>. דכיון שהכח הוא רוחניוהפעולה היא גשמית, אין הכח הרוחני מתגלה בפעולה הגשמית<sup data-n=\"963\">43</sup>. ויש להוסיף, דזה שבהפעולה לא נרגש הכח הוא לא רק מצד הפעולה (שהיא באין ערוך להכח) אלא גם מצד הכח. דכיון שפעולת הכח הוא שעושה דבר חדש שאינו בערכו (כנ\"ל), לכן המשכת הכח לפעול היא המשכה נעלמת [כי פעולת דבר חדש שאינו בערך מקורו היא ע\"י התעלמות המקור. דלאחרי שנפסק גילוי המקור, אז דוקא שייך שיהי' דבר שאינו בערכו], ולכן<sup data-n=\"964\">44</sup>, הפעולה הבאה מהכח היא באופן שלא נרגש בה הכח].\n<b>ועד\"ז</b> הוא למעלה, דההתהוות שמשם אלקים שהיא בדרך התלבשות, היא באופן שהכח המהווה אינו נרגש בהנבראים, ולכן הנבראים שנתהוו משם אלקים הם מציאות והביטול שלהם הוא<sup data-n=\"965\">45</sup> רק ביטול היש. וההתהוות שמשם הוי' שהיא בדרך ממילא, היא באופן שהוא בגילוי בהנבראים, ולכן ביטול הנבראים שנתהוו משם הוי' הוא<sup data-n=\"965\">45</sup> ביטול במציאות.\nה) <b>והנה</b> ידוע דכשמביאים בדרושי חסידות שני משלים (או יותר) לאיזה ענין, הוא, כי אין המשל מכוון להנמשל <i>בכל הפרטים</i>, ולכן מביאים שני משלים (ויותר), שכל אחד מהם מבאר <i>איזה</i> פרטים מהנמשל. וכן הוא בענינינו, דהטעם שמביאים שני משלים על זה שבהתהוות שבדרך ממילא המתהווה הוא בקירוב להמהווה, המשל דעילה ועלול והמשל דאור ומאור, הוא, כי בהנמשל, גם בההתהוות שבדרך ממילא, מתהווה דבר חדש שאינו בערך להמקור המהווה. וכמובן גם מזה שגם בההתהוות שמשם הוי' כתיב כי הוא צוה <i>ונבראו</i>, דלשון בריאה מורה על התהוות יש מאין<sup data-n=\"966\">46</sup>, דיש מאין הוא באין ערוך. וזה שההתהוות שמשם הוי' היא באופן שהוא בגילוי בהנבראים שנתהוו ממנו (כנ\"ל סעיף ד), הכוונה בזה היא שנרגש בהם שאינם מציאות לעצמם וכל מציאותם היא זה שהאור האלקי מהווה אותם מאין ליש, דע\"י הרגש זה הם בטלים למקורם. אבל לא שהוא בגילוי בהנבראים עצמם (ענינם ומעלתם). דכיון שהנבראים הם באין ערוך לגבי', הרי אין שייך שיתגלה בהם אור שאינו בערכם כלל, וע\"ד שאין שייך שבפעולה גשמית יהי' הגילוי דכח הרוחני (כנ\"ל שם). [ולהוסיף, דבכח ופועל, כיון שכח ענינו הוא לפעול ופעולתו היא בדרך התלבשות, לכן, בזה שהכח <i>פועל</i> את הפעולה מתגלה הכח (ורק שאינו מתגלה בהפעולה עצמה). משא\"כ בההתהוות שמשם הוי', כיון שההתהוות שמשם הוי' היא בדרך ממילא, שזה מורה שהוא מופלא מענין ההתהוות<sup data-n=\"967\">47</sup>, הרי אינו מתגלה גם ע\"י <i>התהוות</i> הנבראים, כיון שהוא מופלא מענין ההתהוות]. ולכן המשל דעילה ועלול אינו מכוון להנמשל, כי בעילה ועלול, הקירוב דהעלול להעילה הוא שהעלול הוא<i>בערך</i> העילה, וגילוי העילה הוא בהעלול עצמו<sup data-n=\"968\">48</sup>. [וכמו שכל ומדות שהם עילה ועלול, שבהמדה עצמה ניכר השכל שהולידה. דכשמתעורר באהבה לאיזה דבר לפי שהבין והשיג בשכלו שהדבר טוב לו הרי נרגש בהאהבה עצמה שאהבתו להדבר היא מצד הטוב שבו. ואופן האהבה הוא כאופן הטוב של הדבר<sup data-n=\"969\">49</sup>]. ובכדי לבאר שגם כשהמתהווה הוא באין ערוך להמקור המהווה מ\"מ הוא בקירוב למקורו, הוא ע\"י המשל דאור ומאור. דהגם שהאור הוא הארה בלבד שבאין ערוך להמאור [שלכן אין המאור מתגלה בהאור, שע\"י האור יודעים רק מציאות המאור ולא מהותו<sup data-n=\"970\">50</sup>], מ\"מ, הוא בקירוב להמאור, שנרגש בו מקורו ובטל אליו.\n<b>אלא</b> שגם המשל דאור ומאור אינו מספיק, כי באור ומאור, קירוב האור להמאור וביטולו אליו הוא באופן שהאור אינו מציאות כלל וכל ענינו הוא שהוא גילוי המאור. משא\"כ בהנמשל, גם בההתהוות שמשם הוי' כתיב כי הוא צוה <i>ונבראו</i>, דענין בריאה הוא (לא התפשטות וגילוי המקור, אלא) התהוות דבר. וכמובן גם ממ\"ש בתניא<sup data-n=\"971\">51</sup>, שגם באם היתה ההתהוות משם הוי' שלא ע\"י הצמצום דשם אלקים היו מתהווים הנבראים מאין ליש (אלא שאז היו בטלים בתכלית, כביטול זיו השמש בשמש). ובכדי לבאר שגם מציאות דבר הוא בקירוב למקורו, הוא ע\"י המשל דעילה ועלול. דהגם שהעלול הוא מציאות ולא גילוי העילה מ\"מ הוא בקירוב להעילה.\n<b>ויש</b> לומר, דהטעם על זה שהמשל דעילה ועלול מובא <i>לפני</i> המשל דאור ומאור, הוא, כי עיקר החידוש בזה שהנבראים שמתהווים משם הוי' הם בטלים להוי', הוא, שהגם שהם נבראים (מציאות דבר) מ\"מ נרגש בהם בגילוי האור דשם הוי', וענין זה מובן דוקא מהמשל דעילה ועלול. אלא שבכדי לבאר שגילוי המקור ישנו גם בדבר שבאין ערוך להמקור, מוסיפים המשל דאור ומאור.\nו) <b>והנה</b> ידוע<sup data-n=\"972\">52</sup> דזה שהעולם מוגדר בגדר דמקום וזמן הוא לפי שהתהוותו היא ע\"י שם אלקים, ובאם הי' מתהווה משם הוי' (הי' הוה ויהי' כאחד<sup data-n=\"973\">53</sup>) לא הי' מוגדר בהגדר דמקום וזמן. וזהו שבביהמ\"ק כתיב אכן יש הוי' במקום הזה, כי<sup data-n=\"974\">54</sup>בביהמ\"ק המקום הי' למעלה מגדר מקום, מקום הארון אינו מן המדה<sup data-n=\"975\">55</sup>. אלא שהגילוי שהאיר בביהמ\"ק הי' הגילוי דשם הוי' כמו שמאיר בשם אלקים. דשם הוי' כמו שהוא מצד עצמו הוא למעלה מגדר מקום, וזה שקודש הקדשים הי' מקום מדוד ומוגבל (עשרים אמה על עשרים אמה), וגם הארון הי' במדידה דמקום (אמתיים וחצי ארכו ואמה וחצי רחבו), ואעפ\"כ מקום הארון אינו מן המדה, הו\"ע יחוד הוי' ואלקים<sup data-n=\"976\">56</sup>. וצריך להבין, דכיון שגם בההתהוות שמשם הוי' מתהווה דבר חדש שאינו בערך להמקור המהווה [והגילוי דשם הוי' בהעולם שנתהווה ממנו הוא רק בענין הביטול, שנרגש בהם שמציאותם היא רק זה שהאור האלקי מהוה אותם בכל רגע]<sup data-n=\"977\">57</sup>, הרי גם בהעולם כמו שנתהווה משם הוי' הי' צריך להיות לכאורה ההגבלה דזמן ומקום.\n<b>ויש</b> לומר הביאור בזה בהקדים דמזה שאומרים שהוי' הוא הי' הוה ויהי' (כאחד), דהי' הוה ויהי' הו\"ע הזמן, מובן, שגם העולם כמו שמתהווה משם הוי' יש בו ענין הזמן, אלא שהזמן שבעולם זה הוא באופן שהעבר ההוה והעתיד הם כאחד. ועד\"ז הוא במקום שגם העולם כמו שמתהווה משם הוי' יש בו ענין המקום אלא שהששה קצוות דמקום הם כאחד. ועפ\"ז יש לומר, דהטעם על זה שהזמן ומקום דהעולם כמו שמתהווה משם הוי' אינם בהגבלה והתחלקות (אף שגם העולם כמו שמתהווה משם הוי' הוא באין ערוך להמקור המהווה אותו), הוא מפני הביטול שבו. דכיון שענינם של העבר ההוה והעתיד (וכן ענינם של הששה קצוות) הוא לא המציאות שלהם אלא זה שהוי' מהוה אותם, לכן אינם סותרים זל\"ז והם כאחד.\n<b>ועפ\"ז</b> צריך לומר, דהמבואר בכ\"מ שהמקום דקודש הקדשים הוא משם אלקים (אף שגם מקום זה הי' למעלה מגדר מקום), הוא, כי המקום דקודש הקדשים (עשרים אמה על עשרים אמה) הי' באופן דהתחלקות, שכל אמה היא במקום אחר, וההתחלקות דמקום הוא משם אלקים. וזהו שמקום הארון אינו מן המדה הו\"ע יחוד הוי' ואלקים<sup data-n=\"978\">58</sup>, שההגבלה וההתחלקות דמקום הארון היא מצד אלקים, וזה שהי' אינו מן המדה הוא מצד הגילוי דשם הוי' שהאיר בגילוי בהמקום שנתהווה משם אלקים, יחוד הוי' ואלקים.\nז) <b>וצריך</b> להבין, דזה שמצד שם אלקים הוא ההתחלקות דמקום וזמן הוא לפי שהזמן והמקום כמו שמתהווים משם אלקים הם מציאות, דכאשר נרגש בהששה קצוות דמקום ובהעבר הוה ועתיד דזמן שענינם הוא <i>שאלקות</i> מהווה אותם הם כולם כאחד (כנ\"ל סעיף ו), ואיך שייך שבמקום הארון (מקום שבהתחלקות,שמורה שהוא <i>מציאות</i>) יהי' גילוי שם הוי' (אינו מן המדה)<sup data-n=\"979\">59</sup>. ונקודת הביאור בזה<sup data-n=\"980\">60</sup>, שהצמצום וההסתר דשם אלקים הוא רק לגבי הנבראים, אבל לגבי שם הוי' אינו מסתיר כלל. ולכן, גם לאחרי ההתלבשות דשם הוי' בשם אלקים שעי\"ז נעשה העולם מציאות, מ\"מ, אין המציאות מסתיר לגבי', וגם בהמציאות (שנעשה ע\"י ההעלם דשם אלקים) שעי\"ז נעשה ההתחלקות דמקום וזמן מאיר הגילוי דשם הוי', שענינו דהעולם הוא זה <i>שהוי'</i> מהווה אותו. וכידוע המשל מרב ותלמיד, דכאשר התלמיד הוא באין ערוך להרב, צריך הרב להעלים את עצם שכלו ושישאר רק החיצוניות, וגם החיצוניות צריך להגביל ולהעלים בלבושים והסברים ובמשלים. שהצמצום וההעלם הוא רק לגבי התלמיד ולא לגבי הרב. דהרב רואה את עצם שכלו גם בהחיצוניות וגם בהלבושים ובהמשלים.\n<b>ולהוסיף</b><b>,</b> שבהמשל דרב ותלמיד, זה שלגבי הרב אין הצמצום מסתיר, הוא <i>שלאחרי</i> הצמצום מאיר אצלו פנימיות השכל גם בהחיצוניות וגם בהלבושים, משא\"כ למעלה, זה שהצמצום אינו כפשוטו<sup data-n=\"981\">61</sup> (היינו שהצמצום אינו מעלים לגבי אוא\"ס), שני ענינים בזה. שאחרי הצמצום מאיר אוא\"ס בגילוי ממש במקום החלל כמו קודם הצמצום. ושגם בעת הצמצום, אין הצמצום מסתיר לגבי', כמבואר בארוכה בהדרושים<sup data-n=\"982\">62</sup>. ועפ\"ז מובן עוד יותר שגם בהמציאות שנעשה ע\"י ההעלם דשם אלקים מאיר הגילוי דשם הוי', כי בהמשל דרב ותלמיד, הצמצום עצמו הוא העלם גם לגבי הרב, שהרי בעת הצמצום מתעלם השכל גם אצל הרב. ולכן, גם לאחרי הצמצום, כשהרב רואה את עצם שכלו גם בהלבושים והמשלים, אין זה שייך להלבושים עצמם. משא\"כ למעלה, גם הצמצום עצמו אינו מעלים לגבי אוא\"ס, ולכן, מאיר הגילוי דשם הוי' גם בהמציאות עצמו. ועפ\"ז יובן עוד יותר הלשון לית דין אתר הדיוט <i>שמקום המקדש</i> אינו אתר הדיוט<sup data-n=\"983\">63</sup> [ועד\"ז הלשון מקום ארון אינו מן המדה, <i>שהמקום</i> אינו מן המדה], כי הגילוי דשם הוי' הוא בהמקום עצמו.\nח) <b>וביאור</b> הענין דלית דין אתר הדיוט בעומק יותר יובן בהקדים שבענין היחוד דהוי' ואלקים, הוי' ואלקים כולא חד, שני ביאורים בכללות. שגם שם אלקים (צמצום) ענינו הוא לגלות, שבכדי שהגילוי דשם הוי' יומשך למטה הוא ע\"י הצמצום וההעלם דשם אלקים<sup data-n=\"984\">64</sup>. ועוד ביאור, דשני השמות הוי' ואלקים הם שמותיו של הקב\"ה שלמעלה משניהם<sup data-n=\"985\">65</sup>, אלא שכך עלה ברצונו ית' שהגילוי שלו יהי' בשני הקוין דבל\"ג וגבול (גילוי וצמצום).<b>ועפ\"ז</b> יש להוסיף ביאור בזה שלמעלה גם הצמצום עצמו אינו מעלים לגבי אוא\"ס (נוסף על הביאור שבהדרושים<sup data-n=\"986\">66</sup>), דכיון שגם הצמצום דשם אלקים הוא חד עם הוי', אין שייך שיסתיר לגבי'. ועפ\"ז יש לבאר בעומק יותר הלשון לית דין אתר הדיוט <i>שמקום המקדש</i> אינו אתר הדיוט [ועד\"ז מקום הארון אינו מן המדה], שהגילוי דלמעלה מהמקום שהאיר במקום הי' מצד המקום עצמו.\nט) <b>ויש</b> לומר, שגילוי ענין זה דלית דין אתר הדיוט יהי' בבית השלישי. והענין הוא, דבית ראשון ושני הם בד' האותיות דשם הוי' שרומזים על עשר ספירות [בית ראשון הוא ה' עילאה (בינה) שעל ידה הוא גילוי היו\"ד (חכמה), ובית שני הוא ה' תתאה (מלכות) שעל ידה הוא גילוי הוא\"ו (ז\"א)]<sup data-n=\"987\">67</sup>, ובית שלישי הוא כתר כמובא לעיל (סעיף ג) דיבוא ארי' הוא גילוי הכתר שלמעלה מהשתלשלות.\n<b>והנה</b> בעשר ספירות הגילוי וההעלם שבהם (אורות וכלים) הם שני ענינים, וזה ששני הענינים דגילוי והעלם הם שמותיו של הקב\"ה <i>שלמעלה משניהם</i> הוא ע\"י גילוי הכתר שלמעלה מהשתלשלות. דכמו שענין ההתחלקות דספירות (חכמה, בינה וכו') הוא (בעיקר) בספירות הגלויות דאצילות משא\"כ ע\"ס הגנוזות שבכתר הם כלולים כאחד, עד\"ז הוא גם בענין ההתחלקות דאורות וכלים (גילוי והעלם), שבע\"ס הגנוזות הם (האורות והכלים) בהתאחדות. ועפ\"ז יש לומר, שאמיתית הענין דלית דין אתר הדיוט שגם המקום עצמו יהי' כמו כלי להגילוי דלמעלה מהמקום יהי' בגילוי בבית השלישי. כי אז יומשך בגילוי גם בהשמות הוי' ואלקים כמו שהם בהשתלשלות [ועי\"ז, גם בשני הענינים דלמעלה ממקום ומקום, גם כמו שהם למטה בעוה\"ז הגשמי] ששניהם הם שמותיו של הקב\"ה שלמעלה משניהם, וכולא חד.\n<b>ועפ\"ז</b> יובן מ\"ש בכ\"מ (הובא לעיל סעיף א) דמעלת בית השלישי הוא שיהי' קיים בקיום נצחי, דלכאורה, כיון שענין הנצחיות הי' אפשר להיות גם בבית הראשון (כמובא לעיל סעיף ג) איך אומרים שזוהי המעלה דבית השלישי. ויש לומר הביאור בזה, דהנצחיות שהיתה יכולה להיות בבית ראשון היא (בעיקר) מצד הגילוי דלמעלה מהזמן, והחידוש בהנצחיות שתהי' בבית השלישי הוא שגם הזמן יהי' כלי לזה<sup data-n=\"988\">68</sup>. וזהו שמעלת בית השלישי היא שיהי' קיים בקיום נצחי, כי אמיתית ענין הבלי גבול (נצחיות) הוא, שהנצחיות היא לא רק מצד ההמשכה מלמעלה אלא שהמטה הוא כלי לזה, ו\"נצחיות\" זו היא רק בבית השלישי.\nיו\"ד) <b>וע\"י</b> הגילוי דיחוד הוי' ואלקים (באופן הנ\"ל) שיהי' בביהמ\"ק (השלישי) שגם המקום (שנתהווה משם אלקים) הוא כלי להגילוי דהוי' שלמעלה מהמקום, יומשך מעין גילוי זה גם בכל העולם. וגילוי זה יהי' בעיקר בהגאולה שלאחרי בנין ביהמ\"ק. דהטעם על זה שגאולה העתידה תהי' גאולה נצחית שאיןשייך אחרי' גלות הוא לפי שהעולם יהי' כלי להגאולה. וכמבואר בלקו\"ת<sup data-n=\"989\">69</sup> שגאולה השלישית היא בזכות יעקב שמדתו מדת אמת שאין שייך בו שינוי, דאמיתית ענין הבל\"ג (מדת האמת) הוא שהמטה הוא כלי לזה. ועד\"ז הוא בהענין דקיבוץ גלויות (דהגאולה), שיהי' בכל ששה הקצוות (דמקום), ממזרח אביא זרעך וממערב אקבצך אמר לצפון תני ולתימן אל תכלאי הביאי בני מרחוק ובנותי מקצה הארץ<sup data-n=\"990\">70</sup>, דיש לומר שרחוק וקצה הם כנגד ב' הקצוות מעלה ומטה. ויש לומר, שקיבוץ הגליות מכל הששה קצוות תהי' באופן שהששה קצוות יסייעו לזה<sup data-n=\"991\">71</sup>.\n<b>והנה</b> אף שהגילוי שיומשך בעולם יהי' רק מעין הגילוי שבביהמ\"ק עצמו, מ\"מ יש יתרון בההמשכה בעולם. כי היחוד דהוי' ואלקים שבביהמ\"ק עצמו, כיון שלית דין אתר הדיוט, אין ניכר בזה כ\"כ שהיחוד דהוי' ואלקים הוא גם מצד שם אלקים, והגילוי דענין זה (שהיחוד הוא גם מצד שם אלקים) הוא בעיקר ע\"י שנמשך מעין הגילוי דביהמ\"ק בעולם, אתר הדיוט. ועפ\"ז יש לבאר היתרון דהגאולה לגבי ביהמ\"ק [שלכן תהי' הגאולה לאחרי בנין ביהמ\"ק, כנ\"ל סעיף ב], כי המשכת הגילוי דביהמ\"ק בעולם תהי' (בעיקר) בהגאולה, כנ\"ל.\nיא) <b>ועיקר</b> הגילוי דיחוד הוי' ואלקים (שהיחוד הוא גם מצד אלקים) יהי' בתחיית המתים שלאחרי קיבוץ גלויות, אחרון שבכולם. דהגילוי שיהי' בעולם (גאולה מגלות וקיבוץ גלויות) הוא גילוי מוגבל (בערך הגילויים שיהיו לע\"ל), וכנ\"ל שהוא רק מעין הגילוי דביהמ\"ק, ובתחה\"מ, שאז יהי' חיות הגוף מהסובב<sup data-n=\"992\">72</sup> [נעלה יותר מהחיות דהנשמה, שלכן, הנשמה תהי' ניזונית מהגוף<sup data-n=\"992\">72</sup>], יהיו שתי המעלות. גילוי בל\"ג (סובב), וגילוי זה יהי' בהגוף ששרשו הוא<sup data-n=\"993\">73</sup> משם אלקים.\nיב) <b>וזהו</b> גדול יהי' כבוד הבית הזה האחרון מן הראשון, דהגם שבגאולה העתידה יהיו כו\"כ ענינים ועד לתחה\"מ שהוא אחרון שבכולם, מ\"מ, עיקר ההדגשה היא בכבוד הבית הזה האחרון, כי שורש דכל הענינים יהי' בביהמ\"ק, וממנו יומשכו בעולם (כנ\"ל סעיף ב).\n<b>וזהו</b> גם מהטעמים שהפעולה הראשונה של משיח (לאחרי שיהי' בחזקת משיח) הוא בנין ביהמ\"ק<sup data-n=\"994\">74</sup>, כי זהו השורש דכל הענינים שלאח\"ז. ויהי רצון ועיקר שכל זה יהי' בקרוב ממש.\n**********",[["919","*","יצא לאור ב<b>קונטרס שבת נחמו – תש\"נ</b>, לקראת ש\"ק פ' ואתחנן שבת נחמו . . <i>עש\"ק נחמו</i>,<i> שנת ה'תש\"נ</i>."],["920","**","ברשימת כ\"ק אדמו\"ר שליט\"א משנת תשכ\"ב: \"<i>יאיר נתיב</i>\"<i> דהמאמר</i>:<i> בונה ירושלים – תרכ\"ט [סה\"מ תרכ\"ט ע' רצד ואילך]</i>.<i> ראה קראתי – תרס\"ה [סה\"מ תרס\"ה ע' קעו ואילך]</i>.<i> עיי\"ש</i>.<i> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">לקו\"ת מטות ד\"ה ואשה [פג</i>,<i> ג</a>-ד]</i>.<i> ע\"כ יאמרו תרצ\"א [סה\"מ קונטרסים ח\"א קצא</i>,<i> ב ואילך]</i>."],["921","1","חגי ב, ט."],["922","2","התיווך דשני הפירושים – ראה מכתב בין כסא לעשור וכ\"ג טבת תש\"ה*. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091029\" data-slug=\"likkutei-sichot\" data-id=\"1300091029\">לקו\"ש ח\"ט ע' 29</a> בהערות."],["923","3","מפרשים לחגי שם. וכ\"ה בב\"ב ג, סע\"א."],["924","4","ח\"א כח, א. תקו\"ז תיקון ח. וראה ג\"כ בפי' הראב\"ע."],["925","5","פסחים פח, א."],["926","6","ראה חדא\"ג מהרש\"א שם. אלשי\"ך לתהלים כד (הובא בלקו\"ת שם)."],["927","7","מטות פג, ג-ד."],["928","8","\"היפך נהרות המכזבים במשנה פ\"ח דפרה, שהיא מה שנפסקים לפעמים\" (לקו\"ת שם. ובכ\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061103\" data-slug=\"likkutei-sichot\" data-id=\"1300061103\">לקו\"ש ח\"ו ע' 92</a> שוה\"ג להערה 38)."],["929","9","ולהעיר מהלשון הרגיל \"זמן הבית וזמן הגלות\"."],["930","10","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380948\" data-slug=\"likkutei-torah\" data-id=\"4001380948\">לקו\"ת</a> דרושים לר\"ה נז, ב \"ולא הי' בו (בבית שני) גילוי הה' דברים . . <i>ולכן</i> לא הי' בו חירות\".\n*) <i>נדפס באגרות-קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' ד</i>.<i> שם ע' כג</i>. <b>המו\"ל</b>."],["931","11","פס\"ד ברמב\"ם הל' מלכים פי\"א (בתחלת הפרק ובסופו). וראה ברכות מט, א. תנחומא פ' נח יא. זהר שבהערה הבאה. אגרות-קודש כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע ח\"א אגרת קל (ס\"ע שח ואילך)."],["932","12","ח\"א קלט, א (במדרש הנעלם). וראה שם קלד, א."],["933","13","הושע ו, ב."],["934","14","פרש\"י שם."],["935","15","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600432\" data-slug=\"or-hatorah-hb\" data-id=\"8316600432\">אוה\"ת נ\"ך</a> להושע שם ע' תלב ואילך. <i>וש\"נ</i>."],["936","16","להעיר מד\"ה יחיינו מיומיים תרצ\"א (סה\"מ קונטרסים ח\"א קמד, ב), שמפרש שם שביום השלישי קאי על תחה\"מ <i>בהמשך לפרש\"י</i>."],["937","17","יל\"ש ירמי' רמז רנט."],["938","18","ראה אוה\"ת ואתחנן (ע' סה; שם ע' צג, ממג\"ע אופן קפו ואוה\"ח ר\"פ ואתחנן), שאילו הי' משה רבינו מכניס את בני ישראל לארץ ובונה ביהמ\"ק, לא הי' נחרב ביהמ\"ק לעולם והי' לו קיום נצחי <i>כמו שיהי' לע\"ל</i>. ומבאר שם (ע' פז. וראה גם שם כרך ו ע' ב'רכד) דהטעם על זה שלא פעל משה מבוקשו הוא לפי \"שמהירידות שנמשכו בגלות הארץ יהי' עלי' גדולה יותר\"."],["939","19","ובפרט להמבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א (ה, ב</a>) <i>שזהו</i> פירוש צדיק."],["940","20","ראה ד\"ה שובה ישראל דשבת תשובה ה'תשל\"ז ס\"ב (לעיל ח\"א ע' צו) ואילך (וש\"נ). ובכ\"מ."],["941","21","אוה\"ת נ\"ך כרך ב ע' א'נו ואילך."],["942","22","עמוס ג, ח."],["943","23","יל\"ש שבהערה 17."],["944","24","הובא בפרש\"י יחזקאל מג, יא (הובא בפתיחת התויו\"ט למס' מדות)."],["945","25","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091067\" data-slug=\"likkutei-sichot\" data-id=\"1300091067\">לקו\"ש ח\"ט ע' 67</a>."],["946","26","יל\"ש ירמי' רמז רסד."],["947","27","ירמי' ב, ד."],["948","28","יחזקאל לז, ד."],["949","29","רמב\"ם הל' יסוה\"ת פ\"ט ה\"ב."],["950","30","ביאור המעלה דביהמ\"ק (דלקמן בפנים) מיוסד על המאמר ד\"ה ראה קראתי בשם תרס\"ה (סה\"מ תרס\"ה ע' קעו ואילך). עיי\"ש."],["951","31","ויצא כח, יז."],["952","32","זח\"ג קמט, ב. וראה בארוכה לקו\"ת אחרי כה, ד. ועוד."],["953","33","יומא נד, ב."],["954","34","ויצא שם, טז."],["955","35","שעהיוה\"א פ\"ד."],["956","36","שעהיוה\"א רפ\"ד. וראה גם זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט."],["957","37","בראשית א, א."],["958","38","תהלים קמח, ב."],["959","39","ראה גם המשך תרס\"ו ס\"ע קצז ואילך. <i>עיי\"ש</i>."],["960","40","בסה\"מ תרס\"ה שבהערה 30 (ע' קעט) מביא ב' הדוגמאות (דעילה ועלול, ודאור ומאור). וראה לקמן סעיף ה."],["961","41","סה\"מ תרמ\"ו ע' ג. המשך תער\"ב ח\"א פ' שיא (ע' תרלג). סה\"מ קונטרסים ח\"ג ע' לח."],["962","42","ראה סה\"מ עת\"ר ע' לב דכח הוא נעלם. והמבואר במק\"א (ראה סה\"מ תרס\"ד ע' קכט) דכח הואגילוי, וכמו בזריקת אבן מלמטלמ\"ע נראה ונגלה כח הזורק שהרי בהכרח לומר שיש כח הנושאו למעלה, מ\"מ הוא כח נעלם ולכן אין הכח נרגש בהנפעל."],["963","43","עיקר ענין \"כח\" הוא שפועל בדבר נבדל, פעולה גשמית, כזריקה וכיו\"ב. ובפעולה זו (משא\"כ בציור או בעשיית כלי) אין נרגש הכח – ראה המשך תער\"ב ח\"א פנ\"ג (ע' צו). סה\"מ תש\"ז ע' 130. ועוד."],["964","44","סה\"מ עת\"ר שבהערה 42."],["965","45","ראה לקמן ס\"ע רפו. וש\"נ."],["966","46","רמב\"ן ר\"פ בראשית."],["967","47","סה\"מ קונטרסים ח\"א קצד, רע\"א. ובכ\"מ."],["968","48","ראה סה\"מ קונטרסים ח\"ב רעז, א \"מכל עלול אפשר לידע מעלת עילתו . . (כי) יש בו התפשטות עילתו\". ובהמשך הענין שם דוגמא משכל ומדות."],["969","49","ראה סה\"מ אידיש ע' 21. ובכ\"מ."],["970","50","סה\"מ ה'ש\"ת ע' 12. ובכ\"מ."],["971","51","שעהיוה\"א פ\"ד. וראה מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' שפ. וראה גם ספהמ\"צ להצ\"צ קלב, ב ואילך."],["972","52","שעהיוה\"א פ\"ז (פב, א). ושם ששורש המקום והזמן הוא משם <i>אד'</i>. ומ\"ש בפנים (מסה\"מ תרס\"ה ס\"ע קפ והמשך תרס\"ו ע' רכח) שהוא מצד שם אלקים, יש לומר <i>דשורש</i> הזמן והמקום הוא משם אד' כבשעהיוה\"א שם. ובסה\"מ תרס\"ה ותרס\"ו שם מדבר (לא בשורש הזמן והמקום עצמם, אלא) בזה שבהזמן ומקום לא מאיר גילוי שם הוי' שלמעלה מזמן ומקום, שזהו מצד שם אלקים שמעלים ומסתיר על שם הוי'*. ולהעיר שבכללות אלקים ואד' הם ענין אחד."],["973","53","שעהיוה\"א שם, מרע\"מ פ' פינחס (רנז, סע\"ב). פרדס שבהערה 36."],["974","54","בסה\"מ תרס\"ה שבהערה 30 (ע' קפב) שהראי' על הגילוי דשם הוי' שהי' במקדש, שלכן לית דין אתר\n*) <i>וענין זה הוא גם במקום ארון שאינו מן המדה – כי מצד הגילוי דהוי' עצמו הי' המקום מתבטל </i><b>לגמרי</b>.הדיוט, הוא מהניסים שהיו בביהמ\"ק. ובסה\"מ תרמ\"ג ס\"ע קב ואילך, שהראי' היא ממקום הארון שאינו מן המדה (וראה גם סה\"מ תר\"פ ע' קפו. תרפ\"ז ע' פו)."],["975","55","יומא כא, א. וש\"נ."],["976","56","כ\"ה להדיא בהמשך תרס\"ו ע' רכח."],["977","57","כנ\"ל סעיף ה."],["978","58","ובסה\"מ תרמ\"ג ע' ק שהו\"ע שילוב אד' בהוי'. וכ\"ה בסה\"מ תרס\"ה ע' קפה אלא ששם מדבר (לא בענין מקום הארון אינו מן המדה, אלא) בהניסים שהיו בביהמ\"ק."],["979","59","בכ\"מ מבואר, דמקום הארון אינו מן המדה הוא מצד \"נמנע הנמנעות\" שנושא הפכים. אבל במקומות שבהערות הקודמות שהו\"ע ביטול מקום לגבי למעלה ממקום, התגברות הוי' על אד' (וכיו\"ב), היינו שיש לזה גם אחיזה עכ\"פ בשכל, כי חיבור ההפכים שמצד \"נמנע הנמנעות\" הוא גם כששניהם הם בתוקף (ואין אחד מתגבר על השני או בטל אליו)."],["980","60","בהבא לקמן ראה סה\"מ תרס\"ה שם ע' קפב ואילך. וראה בארוכה סה\"מ תרנ\"ז ע' מח ואילך. ובכ\"מ."],["981","61","שעהיוה\"א פ\"ז (פג, סע\"ב ואילך)."],["982","62","סה\"מ תרס\"ה שם."],["983","63","ראה לעיל סעיף ד."],["984","64","סה\"מ תרנ\"ז ע' נא ואילך. ובכ\"מ."],["985","65","ראה גם שעהיוה\"א פ\"ו (פ, ב)."],["986","66","ראה לקמן סעיף ט שביאור זה הוא דוקא כשנרגש בהגילוי ובהצמצום שענינם הוא (לא הם אלא) <i>שרשם</i>. והביאורים שבהדרושים הוא, שגם מצד <i>ענינם</i>, הצמצום אינו מסתיר."],["987","67","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380949\" data-slug=\"likkutei-torah\" data-id=\"4001380949\">לקו\"ת</a> דרושים לר\"ה נז, ג-ד."],["988","68","וע\"ד החילוק בענין <i>מקום</i> הארון אינו מן המדה."],["989","69","שבהערה 7."],["990","70","ישעי' מג, ה-ו."],["991","71","לכאורה, רק בצפון נאמר \"תני\" משא\"כ בתימן רק \"אל תכלאי\". ומכ\"ש במזרח ומערב – \"אביא\", \"אקבצך\", ואינו מדבר אליהם. אבל ראה מצודת דוד שם \"הביאי – כאילו יצוה <i>לכל אחד</i> מרוחות השמים <i>להביא</i> את ישראל\"."],["992","72","המשך וככה תרל\"ז פצ\"א. סה\"מ קונטרסים ח\"ב תיג, ב. ובכ\"מ."],["993","73","שעהיוה\"א פ\"ו (פא, רע\"א)."],["994","74","רמב\"ם הל' מלכים פי\"א ה\"ד."]]],[1500390014,"<h3>בס\"ד. יום ג' פ' דברים, ה' מנחם-אב ה'תשכ\"ה<sup data-n=\"995\">*</sup></h3>\n<b>בלע</b> המות לנצח ומחה הוי' אלקים דמעה מעל כל פנים<sup data-n=\"996\">1</sup>, ומבאר אדמו\"ר מהר\"ש במאמרו ד\"ה זה<sup data-n=\"997\">2</sup>, דזה שלע\"ל יהי' בלע המות לנצח הוא לפי שאז יהי' ואת<sup data-n=\"998\">3</sup> רוח הטומאה אעביר מן הארץ. ויובן זה בהקדים הטעם דהמבואר בקרא (דלקמן) שע\"י חטא עה\"ד נעשה מיתה בעולם, היינו שמיתה וחטא עה\"ד שייכים זל\"ז. והענין הוא, דע\"י חטא עה\"ד נעשה תערובות טוב ורע<sup data-n=\"999\">4</sup>. דמציאות הרע הי' גם קודם החטא, אלא שאז הי' הרע מובדל מהטוב, וכידוע<sup data-n=\"1000\">5</sup> שבתחלת הבריאה הי' מדור הקליפות למטה מהעולמות דקדושה, וע\"י חטא עה\"ד נעשה תערובות טוב ורע (בכל העולם<sup data-n=\"1001\">6</sup>), שהרע מעורב בהטוב והטוב בהרע, ועד אשר אין טוב בלא רע ואין רע בלא טוב<sup data-n=\"1002\">7</sup>. וזהו מ\"ש<sup data-n=\"1003\">8</sup> ועתה פן ישלח ידו ולקח גם מעץ החיים ואכל וחי לעולם, דלכאורה, הרי בריאת האדם (מלכתחילה) היתה באופן שיהי' חי לעולם, והטעם על זה שנצטווה שלא לאכול מעה\"ד הוא בכדי שלא ימות (כמ\"ש<sup data-n=\"1004\">9</sup> ומעץ הדעת גו' לא תאכל ממנו <i>כי</i> ביום אכלך ממנו מות תמות), ומה איכפת שיאכל מעה\"ח ויהי' חי לעולם. ומבאר אדמו\"ר הזקן<sup data-n=\"1005\">10</sup>, דמכיון שע\"י חטא עה\"ד נתערב רע בהאדם, לכן, ועתה (לאחרי חטא עה\"ד) יש לחשוש פן ישלח ידו גו' וחי לעולם, כי כשיהי' הוא חי לעולם, גם הרע המעורב בו יהי' לו קיום לעולם. ועפ\"ז יש לומר, דזה שע\"י חטא עה\"ד נעשה מיתה בעולם הוא בכדי שלא יהי' קיום להרע, כנ\"ל.\n<b>ויש</b> לומר, דהמיתה בעולם שנעשתה ע\"י חטא עה\"ד היא מסובבת מהחטא עצמו. והענין הוא, דענין החיות הוא בקדושה דוקא, משא\"כ הרע והטומאה (היפךהקדושה) הם מות<sup data-n=\"1006\">11</sup>, ולכן, מכיון שע\"י חטא עה\"ד נתערב רע בהאדם, מות רוחני, מזה נשתלשל בו גם מיתה כפשוטה. וזהו גם מה שלע\"ל יהי' בלע המות לנצח, דמכיון שאז יתבטל הרע, מות הרוחני<sup data-n=\"1007\">12</sup>, עי\"ז יהי' במילא גם בלע המות כפשוטו.\nב) <b>והנה</b> הטעם על זה שדוקא לע\"ל יתבטל הרע (מות הרוחני, ובמילא גם המות כפשוטו) הוא, כי אז יהי' גילוי אור נעלה ביותר, שלגבי אור זה, מתבטלים במילא כל המנגדים. ומבאר בהמאמר<sup data-n=\"1008\">13</sup>, דהגם שגם בזמן שביהמ\"ק הי' קיים, ובפרט בזמן בית ראשון, ועאכו\"כ בימי שלמה דקיימא סיהרא באשלמותא<sup data-n=\"1009\">14</sup>, הי' גילוי אור נעלה ביותר, ומצד גילוי זה, כל הגוים נתבטלו לפניו, שלא ע\"י מלחמה כלל<sup data-n=\"1010\">15</sup> [שלכן נק' בשם שלמה כי שלום הי' בימיו<sup data-n=\"1011\">16</sup>], מ\"מ הגילוי שהי' בימי שלמה הי' באופן שהי' עדיין מקום ליניקת החיצונים, אלא שיניקתם אז היתה רק מאחוריים דקדושה ולא הי' להם אחיזה בפנימיות. [ויש לומר, דזה שבימי שלמה הי' עדיין מקום ליניקת החיצונים, ניכר גם באופן הביטול דהגוים שנתבטלו לפניו. וכמו מלכת שבא, דעם היות שגם בהיותה בארצה ורק שמעה את שמע שלמה נעשה בה ביטול (קצת), שמצד זה<sup data-n=\"1012\">17</sup> באה אל שלמה<sup data-n=\"1013\">18</sup>, ובפרט לאחרי שבאה אליו וראתה את חכמתו וכו' שעי\"ז נתבטלה לפניו באופן שלא הי' בה עוד רוח<sup data-n=\"1014\">19</sup>, מ\"מ, גם אז היתה מלכה, ויתירה מזו, שגם שלמה כיבד אותה בכבוד גדול<sup data-n=\"1015\">20</sup>]. משא\"כ הגילוי דלע\"ל<sup data-n=\"1016\">21</sup> יהי' באופן שלא תהי' יניקה לחיצונים כלל (גם לא מבחינת אחוריים) ויתבטל הרע לגמרי, בלע המות לנצח.\nג) <b>וביאור</b> החילוק בין הגילוי שהי' בימי שלמה (שמצד גילוי זה הי' עדיין מקום ליניקת החיצונים, מבחינת אחוריים עכ\"פ) להגילוי דלע\"ל (שמצד גילוי זה לא יהי' להם יניקה כלל), מבאר בהמאמר<sup data-n=\"1017\">22</sup>, שהוא ע\"ד החילוק (בעבודת האדם) בין העבודה דסור מרע להעבודה דמואס ברע. דסור מרע הוא שמדחה את הרע אבלאינו שונא את הרע בעצם. ובמילא, אף שבפועל הוא מדחה את הרע, נשאר אצלו עדיין נתינת מקום להרע, ועד שבהעלם יש לו איזה שמץ אהבה לרע, כמבואר בתניא<sup data-n=\"1018\">23</sup> בדרגת צדיק שאינו גמור. משא\"כ כשהוא מואס ברע, היינו שהוא מואס ברע בתכלית (דרגת צדיק גמור), אין אצלו שום נתינת מקום לרע, שהרי אדרבא, הוא שונא את הרע ומואס בו בתכלית השנאה והמיאוס. ועד\"ז הוא החילוק בין הגילוי שהי' בימי שלמה להגילוי דלע\"ל, דהגילוי שהי' בימי שלמה, עם היות שגם לגבי גילוי זה מתבטלים כל המנגדים (בדוגמת שגם בהעבודה דסור מרע הוא מדחה את הרע), מ\"מ, יש עדיין מקום ליניקת החיצונים (מבחינת אחוריים דקדושה עכ\"פ). משא\"כ הגילוי דלע\"ל הוא דוגמת המואס ברע בתכלית המיאוס, שאין בו שום נתינת מקום לענין דהיפך הקדושה.\n<b>ויש</b> להוסיף, דע\"פ המבואר בתניא<sup data-n=\"1018\">23</sup> שגודל השנאה לסט\"א והמיאוס ברע הוא כפי ערך גודל האהבה להוי', החילוק בין סור מרע למואס ברע הוא (לא רק בנוגע לאופן שלילת הרע, אלא גם) בגודל ואופן אהבתו להוי'. ועפ\"ז תומתק ההשוואה דחילוק זה (שבין סור מרע למואס ברע) להחילוק שבין הגילוי שהי' בימי שלמה להגילוי דלע\"ל, דהחילוק שביניהם באופן שלילת הרע (שבהגילוי שהי' בימי שלמה יש עדיין נתינת מקום ליניקת החיצונים משא\"כ בהגילוי דלע\"ל) הוא מצד החילוק שבהם בדרגת ואופן <i>האור והגילוי</i>.\nד) <b>והנה</b> ידוע שכל הגילויים דלע\"ל תלויים במעשינו ועבודתינו עכשיו<sup data-n=\"1019\">24</sup>. דמזה מובן, דזה שלע\"ל יהי' גילוי זה שאינו נותן מקום ליניקת החיצונים (בלע המות לנצח) הוא, כמבואר בהמאמר&lt;22&gt;, דע\"י שישראל שונאים את הרע בתכלית השנאה, עי\"ז נעשה למעלה ואת עשו שנאתי<sup data-n=\"1020\">25</sup> בתכלית השנאה, ומצד שנאה זו יהי' ואת רוח הטומאה אעביר מן הארץ, בלע המות לנצח. והנה מכיון דראה הקב\"ה בצדיקים שהם מועטים<sup data-n=\"1021\">26</sup> (ובפרט ששנאת הרע בתכלית היא דרגת צדיק גמור), ואפילו בנוגע לדרגת הבינוני ידוע הפתגם<sup data-n=\"1022\">27</sup> הלואי בינוני, והענין דבלע המות לנצח יהי' בכל ישראל, מובן מזה, שעבודה זו (לשנוא את הרע בתכלית השנאה) יכולה להיות גם בבינונים, ואפילו באלה שלמטה מדרגת בינוני. דבכאו\"א מישראל ישנם זמנים מיוחדים – בשעת התפלה, או בשעת עסק התורה, או בשעה שהוא מקיים מצוה דהוה זהיר בה טפי<sup data-n=\"1023\">28</sup>, או אפילו בשעה שעוסק בדברי הרשות לשם שמים<sup data-n=\"1024\">29</sup> ועאכו\"כ<sup data-n=\"1025\">30</sup>באופן דבכל דרכיך דעהו<sup data-n=\"1026\">31</sup> – שבשעה זו הוא מוסר את כל מציאותו (ער גיט זיך איבער אינגאַנצן) לאלקות, ועי\"ז אינו שייך לבגדים הצואים<sup data-n=\"1027\">32</sup>, כמו צדיק גמור. ומכיון שיחוד זה למעלה הוא נצחי לעולם ועד<sup data-n=\"1028\">33</sup>, לכן נמשך עי\"ז הגילוי שאינו נותן מקום כלל ליניקת החיצונים, בלע המות לנצח.\nה) <b>וזהו</b> בלע המות לנצח, דכל זמן שלא נשלמו עדיין הבירורים והטוב והרע מעורבים זב\"ז (כולל גם בזמן שביהמ\"ק הי' קיים, ואפילו בימי שלמה דקיימא סיהרא באשלמותא) יש ענין המיתה, בכדי שלא יהי' קיום להרע, כנ\"ל. וזהו גם הטעם שגם צדיקים יחזרו לעפרן שעה אחת קודם תחיית המתים<sup data-n=\"1029\">34</sup> [דהגם שאין רימה שולטת בהם<sup data-n=\"1030\">35</sup> ועד לשעה זו (שקודם תחה\"מ) הי' גופן קיים מאות ואלפים שנים, ומ\"מ, קודם תחה\"מ יחזרו לעפרן], כי מכיון שע\"י חטא עה\"ד נעשה תערובות רע בכל העולם, לכן, גם גופות הצדיקים יצטרכו לזיכוך<sup data-n=\"1031\">36</sup>. משא\"כ לע\"ל (לאחרי התחי'), כשיהי' ואת רוח הטומאה אעביר מן הארץ, לא תהי' אז מיתה וגם הגוף יחי' בחיים נצחיים. דגם להדיעה<sup data-n=\"1032\">37</sup> דמ\"ש<sup data-n=\"1033\">38</sup> כי הנער בן מאה שנה ימות הוא כפשוטו, הוא רק בנוגע לב\"נ, משא\"כ בנוגע לישראל יהי' בלע המות לנצח. ויתירה מזו, דגם המיתה שתהי' (לדיעה זו) בב\"נ היא לא מיתה ממש, אלא נפילה, דמאן דנפיל מדרגי' אקרי מית<sup data-n=\"1034\">39</sup>. וכמבואר בהמאמר<sup data-n=\"1035\">40</sup>, דע\"י שניצוצות הקדושה שנבלעו בהם יתבררו מהם ויעלו למעלה, הרע שבהם (היינו גוף הגשמי שלהם שנקרא בשם רע בערך לניצוצות הקדושה שבו) יפול למטה. דזהו באוה\"ע, משא\"כ בישראל יתעלה גם הגוף, שגם הגוף יזון מרוחניות כמו הנשמה, ולא עוד אלא שאז יהי' הגוף למעלה מהנשמה, נקבה תסובב גבר<sup data-n=\"1036\">41</sup>. וכל זה יהי' בפועל ובגילוי למטה מעשרה טפחים, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n**********",[["995","*","יום סיום אמירת קדיש אחרי הרבנית הצדקנית מרת חנה ע\"ה, אמו של – יבלחט\"א – כ\"ק אדמו\"ר שליט\"א.\nהמאמר יצא לאור ב<b>קונטרס כ\"א אדר – תשמ\"ח</b>, \"לקראת יום ה' פ' ויקהל-פקודי, כ\"א אדר, סיום השלושים להסתלקות הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע . . <i>יום ג' ויק\"פ</i>,<i> שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["996","1","ישעי' כה, ח."],["997","2","דשנת תרכ\"ח – נדפס בסה\"מ תרכ\"ח ע' מ. ולאחריו בא ד\"ה רבת את ריבם, שהוא דרוש הנ\"ל עם הוספות."],["998","3","זכרי' יג, ב."],["999","4","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו\"א בראשית ה, ג</a> ואילך. וראה מאמרי אדהאמ\"צ דברים ח\"ד ע' א'קעו ואילך. ד\"ה דבר וגו' כי אתם עוברים תרנ\"א (סה\"מ תרנ\"א ע' קצז). ובארוכה – ד\"ה ושבתה במאמרי אדהאמ\"צ ויקרא ח\"ב ע' תדש ואילך. ד\"ה הנ\"ל תרס\"ב (סה\"מ תרס\"ב ע' ש ואילך)."],["1000","5","ל\"ת להאריז\"ל פ' בראשית ד\"ה ונבאר מעלת אדה\"ר. אוה\"ת דרושים לפסח ע' תשנח. סוף המשך פדה בשלום תרנ\"ט (סה\"מ תרנ\"ט ע' קעו) ותש\"ד (סל\"ג – סה\"מ תש\"ד ס\"ע 139 ואילך). ועוד."],["1001","6","ראה בארוכה ד\"ה ושבתה הנ\"ל, דע\"י חטא עה\"ד נעשה תערובות טו\"ר בכל ד' הסוגים דדצח\"מ."],["1002","7","ראה לקו\"ד כרך א פז, א ואילך."],["1003","8","בראשית ג, כב."],["1004","9","שם ב, יז."],["1005","10","בתו\"א שם."],["1006","11","ראה בארוכה ד\"ה דבר וגו' תרנ\"א הנ\"ל (ע' קצז ואילך). ד\"ה וידבר גו' ערי מקלט תהיינה תרס\"ה (סה\"מ תרס\"ה (קה\"ת, תשמ\"ח) ע' שכה ואילך)."],["1007","12","ראה תו\"א שם ה, ד \"בלע המות לנצח שיהי' ובערת כמאמר והרשעה כולה בעשן תכלה\"."],["1008","13","ד\"ה רבת את ריבם הנ\"ל (ע' מא ואילך)."],["1009","14","זהר ח\"א קנ, א. רכה, ב. רמג, סע\"א. ח\"ב פה, א. ח\"ג מ, ב. מו, א. וראה שמו\"ר פט\"ו, כו."],["1010","15","ראה בארוכה המשך פדה בשלום תרנ\"ט (ע' קסב. שם ע' קסד) ותש\"ד (סי\"ט וסכ\"א – ע' 107 וע' 11-110), וראה גם תו\"א שם (ו, א), שהבירור שהי' בימי שלמה הוא בירור בדרך מנוחה ובתו\"א שם שזהו בדוגמת אדה\"ר <i>קודם</i> החטא."],["1011","16","כמ\"ש (דברי הימים-א כב, ט) שלמה יהי' שמו ושלום ושקט אתן על ישראל בימיו."],["1012","17","דזהו שנתעורר בה רצון לבוא לשלמה הוא מצד הביטול שנעשה בה (בהיותה עדיין בארצה) ע\"י ששמעה את שמעו – ראה המשך הנ\"ל תרנ\"ט (ע' קסב) ותש\"ד (ע' 107) \"דמצד גדולת שמו שנשמע למרחוק גם באיים הרחוקים <i>מתבטלים</i> כולם אליו <i>ונמשכים</i> אליו\"."],["1013","18","מלכים-א יו\"ד, א-ב."],["1014","19","שם, ד-ה."],["1015","20","ראה שם, יג."],["1016","21","ראה גם ד\"ה פדה בשלום תשמ\"א (לעיל ח\"ב ע' צה ואילך) בתחלתו ובסעיף ו. וראה בהנסמן שם הערה 5."],["1017","22","ד\"ה רבת את ריבם הנ\"ל (ע' מב)."],["1018","23","פ\"י (טו, א)."],["1019","24","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1020","25","מלאכי א, ג."],["1021","26","יומא לח, ב. וראה תניא פ\"א (ה, ב)."],["1022","27","בית רבי ח\"ב פ\"ח (יד, א) הערה א. וראה ד\"ה ואלה המשפטים תשל\"ח ס\"ה (לעיל ח\"ג ע' י)."],["1023","28","ראה שבת קיח, סע\"ב."],["1024","29","ראה אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241661\" data-slug=\"likkutei-sichot\" data-id=\"1300241661\">לקו\"ש חכ\"ד ע' 646</a> בהערה ד\"ה כל מעשיך לשם שמים."],["1025","30","ראה בארוכה לקו\"ש ח\"ג ע' 907. שם ע' 932. ח\"י ע' 104."],["1026","31","משלי ג, ו. רמב\"ם וטושו\"ע שם. שו\"ע אדה\"ז או\"ח סקנ\"ו ס\"ב."],["1027","32","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא פ\"י</a>."],["1028","33","<a class=\"ft-cite\" href=\"#/read/tanya/3401310030\" data-slug=\"tanya\" data-id=\"3401310030\">תניא פכ\"ה</a>."],["1029","34","שבת קנב, ב. וראה זח\"ב קח, ב."],["1030","35","ראה מדרש תהלים עה\"פ קיט, ט."],["1031","36","אלא שזיכוך זה יכול להיות ע\"י הביטול דונפשי כעפר לכל תהי', ואז א\"צ לחזור לעפרן כפשוטו – ראה שיחת ש\"פ בא תשמ\"ח בסופה (התוועדויות תשמ\"ח ח\"ב ס\"ע 273)."],["1032","37","דעת ר' חנינא בב\"ר פכ\"ו, ב. וראה פסחים סח, א. סנהדרין צא, ב."],["1033","38","ישעי' סה, כ."],["1034","39","כ\"ה בלקו\"ת חוקת נז, רע\"א. ובכ\"מ בדא\"ח. ובזח\"ג קלה, ב – הובא בע\"ח שער ט (שער שבה\"כ) פ\"ב ובמבו\"ש ש\"ב ח\"ב פ\"ג – איתא: מאן דנחית מדרגא קדמאה דהוה בי', קארי בי' מיתה."],["1035","40","סד\"ה בלע המות לנצח (ס\"ע מ) וד\"ה רבת את ריבם (ע' מב)."],["1036","41","ירמי' לא, כא."]]],[1500390015,"<h3>בס\"ד. יום השלישי שהוכפל בו כי טוב, ערב ר\"ח מנחם-אב, תשל\"ה<sup data-n=\"1037\">*</sup>.</h3>\nהנחה\n<b>ציון</b> במשפט תפדה ושבי' בצדקה<sup data-n=\"1038\">1</sup>, הנה פסוק זה הוא בתחילת ספר ישעי', שענינו (של ישעי') כשמו כן הוא (ישעי' מלשון ישועה<sup data-n=\"1039\">2</sup>), וכדאיתא בגמרא<sup data-n=\"1040\">3</sup> ישעי' כולי' נחמתא. ועד שאפילו אלו הענינים בנבואות ישעי' שלכאורה אינם ישועה, הנה באמת גם הם ישועה ונחמה, וכמבואר בקבלה<sup data-n=\"1041\">4</sup> שהם בחי' גבורות ממותקות, ולפי שהישועה (גאולה) העתידה תהי' על ידי מיתוק הגבורות, ולכן יצחק יהי' עיקר כו' [וכדאיתא בגמרא<sup data-n=\"1042\">5</sup>, שלעת\"ל יאמרו ליצחק (דוקא) כי אתה אבינו, שיצחק הו\"ע הגבורות], לכן בהישועות שבספר ישעי' ישנן הישועות שבבחי' חסדים הגלויים, והישועות דבחי' גבורות ממותקים, גבורות שנהפכים לחסדים<sup data-n=\"1043\">6</sup> (שהם נעלים יותר<sup data-n=\"1044\">7</sup> מחסדים הגלויים). ועד\"ז הוא גם בהנבואה שבתחילת הספר, שיש בה שני סוגים הנ\"ל, מסיים בשנים ציון במשפט תפדה ושבי' בצדקה, כדלקמן.\nב) <b>והנה</b> מבואר בהדרושים ד\"ה ציון במשפט תפדה ושבי' בצדקה (לכ\"ק אדמו\"ר הזקן ורבותינו נשיאינו ממלאי מקומו<sup data-n=\"1045\">8</sup>), שבפסוק זה מדובר ע\"ד שתי בחי'. ציון, שבחי' ציון עם היותה בגלות שלכן צריכה פדי', מ\"מ אינה בבחי' שבי', ולכן פדייתה מהגלות הוא במשפט. ובחי' ושבי', שהם שבויים ממש, ופדייתם מהשבי' הוא בצדקה דוקא. וביאור הענין דשתי בחי' אלו באדם, היינו בהנשמה שהיא עיקר האדם (כדאיתא בתניא פל\"ב), דאתם קרויים אדם<sup data-n=\"1046\">9</sup> על שם אדמה לעליון<sup data-n=\"1047\">10</sup>, הנה הנשמה<sup data-n=\"1048\">11</sup> ישנה כפי שהיא למעלה מהתלבשות בגוף, עצם הנשמה, פנימיות הלב וכו', וחלק הנשמה המתלבש בגוף, שבכללות הם כחות הגלויים של הנשמה שהם בבחי' התלבשות, הנקרא רגל שבנשמה. וע\"ז נאמר ציון במשפט תפדה ושבי' בצדקה, ציון קאי על עצם הנשמה בחי' פנימיות הלב, ובבחי' זו אין שייך ענין השבי' והשעבודבלעו\"ז ח\"ו, ורק ענין הגלות. משא\"כ בכחות הנשמה שבבחי' התלבשות בגוף שייך ענין השבי', וע\"ז אומר ושבי' בצדקה, שגם כחות הנשמה (שבבחי' התלבשות בגוף) שהם שבויים ממש בלעו\"ז, יפדו ע\"י הצדקה.\nג) <b>ולבאר</b> הענין דבחי' פנימיות הלב (הנקראת בשם ציון), מביא בדרושים הנ\"ל<sup data-n=\"1049\">12</sup> מ\"ש<sup data-n=\"1050\">13</sup> והיו הדברים האלה אשר אנכי מצוך היום וארז\"ל<sup data-n=\"1051\">14</sup> בכל יום יהיו בעיניך כחדשים. דצריך להבין איך אפשר להיות כן [שהרי זה דבכל יום יהיו בעיניך כחדשים צ\"ל (ככל הענינים שבתורת אמת) באמת<sup data-n=\"1052\">15</sup>, ומכיון שאין הקב\"ה מבקש אלא לפי כחן<sup data-n=\"1053\">16</sup>, הרי מוכח שבכחו של האדם הוא להגיע לזה, ולכאורה מכיון שהאדם הוא מוגבל ובעל שינויים, איך יכול לבוא לזה שבכ\"י יהיו בעיניו כחדשים]. והביאור בזה (כמובן מדרושים הנ\"ל), שזהו מצד בחי' פנימיות הלב שהיא למעלה מענין השינויים<sup data-n=\"1054\">17</sup>, ולכן, כאשר פנימיות הלב היא כדבעי (היינו שהיא בגילוי), פועלת היא גם על כחות הנשמה שבהתלבשות בגוף, וגם על לבושי הנשמה מחשבה דיבור ומעשה, שגם בהם יהיו ד\"ת כחדשים, כי ע\"י הגילוי דבחי' פנימיות הלב, גם כחות הגלויים של הנשמה הם בשלימותן. וזהו מה שישראל נקראים (בפסוק זה) בשם ציון [כמ\"ש אדמו\"ר הצ\"צ<sup data-n=\"1055\">18</sup> שהפירוש (דבציון במשפט תפדה) דציון קאי על העיר (או על כללות א\"י) הוא דוחק קצת. ומפרש שציון קאי על עם ישראל], כי ציון הוא לשון סימן, וכאשר מאיר באדם (גילוי ד)בחי' פנימיות הלב, אז הוא בבחי' ציון לשון סימן, (אנא סימנא בעלמא<sup data-n=\"1056\">19</sup>) שכל מציאותו הוא רק סימן דהענינים שלמעלה.\nד) <b>והנה</b> פירוש הנ\"ל (של הצ\"צ) שציון קאי על עם ישראל, מובן שם שהוא ע\"פ מאמר הירושלמי<sup data-n=\"1057\">20</sup> ע\"פ<sup data-n=\"1058\">21</sup> ואשים דברי בפיך ובצל ידי כסיתיך לנטוע שמים וליסוד ארץ ולאמר לציון עמי אתה, חזרנו על כל המקרא ולא מצאנו שנקראו ישראל ציון אלא זה (שנאמר) ולאמר לציון עמי אתה. ומבאר כ\"ק אדמו\"ר הצ\"צ<sup data-n=\"1059\">22</sup>, שע\"י ג' הדברים שבפסוק זה (לפי פירוש הירושלמי שם) ואשים דברי בפיך זו תורה[דבר הוי' זו הלכה<sup data-n=\"1060\">23</sup> דהיינו תורה<sup data-n=\"1061\">24</sup>], ובצל ידי כסיתיך זו גמ\"ח [שהוא כללות כל המצוות<sup data-n=\"1062\">25</sup>, והמצוות הם בחי' לבושים<sup data-n=\"1063\">26</sup>, כסיתיך<sup data-n=\"1064\">27</sup>], לנטוע שמים וליסוד ארץ אלו הקרבנות [כי ע\"י הקרבנות מתקיימים חוקות שמים וארץ<sup data-n=\"1065\">28</sup>. וע\"י הקרבנות (ותפלה) נעשה יחוד זו\"נ הנק' שמים וארץ<sup data-n=\"1066\">29</sup>], ע\"י קיום ג' דברים אלו ישראל הם בבחי' ציון. והיינו, דכאשר ג' דברים אלו הם בשלימות (וכפי שהם נרמזים בפסוק זה), שלימוד התורה הוא בתכלית הביטול עד שאין הדיבור בא מצד עצמו אלא שנדבר בו דבר הוי' וע\"ד שכינה מדברת מתוך גרונו (של משה)<sup data-n=\"1067\">30</sup>, דזהו ואשים דברי בפיך שדבר ה' הוא המדבר בפיו<sup data-n=\"1068\">31</sup>, וכן קיום המצוות שלו הוא בבחי' ביטול, שמציאותו אינה נרגשת כ\"א הוא מכוסה (כסיתיך) בצל ידי (ידו של הקב\"ה) היינו בחי' המצוות כמו שהם מצוות הוי'<sup data-n=\"1069\">32</sup>. ועאכו\"כ שכן הוא בקו העבודה, שעבודתו היא לנטוע שמים וליסוד ארץ<sup data-n=\"1070\">33</sup>. (וע\"ד דאיתא בזהר<sup data-n=\"1071\">34</sup> שע\"י שמשתדל במילי דאורייתא אתעביד מההוא מלה שמים חדשים וארץ חדשה, והיינו שדיבור התורה שלו הוא דוגמת דיבורו של הקב\"ה, מה אנא במלולא דילי עבדית שמים וארץ כו' אוף הכי את). הנה ע\"י קיום ג' דברים הנ\"ל באופן כזה, נקראים כנס\"י בשם ציון, שאינם בבחי' מציאות בפ\"ע כ\"א מציאותם היא שהם סימן דהענינים שלמעלה.\nה) <b>אמנם</b><b>,</b> כאשר חסר בהעבודה בג' קוין הנ\"ל, מפני חטאינו, הנה הגם שענין החטא הוא מצד בחי' הנשמה המתלבשת בגוף, מ\"מ זה פועל גם בעצם הנשמה. וכמ\"ש<sup data-n=\"1072\">35</sup> שובה ישראל עד ה\"א כי כשלת בעונך, דנכשל בפועל הוא הרגל וישראל הוא אותיות לי ראש, ראש שבנשמה, ואומר שובה ישראל, לפי שהכשלון דרגל הנשמה פועל גם בבחי' הנשמה שלמעלה. וכמשל אדם הנכשל ברגלו, שעי\"ז נופל גם ראשו. וזהו\"ע ציון במשפט תפדה, שבחי' ציון, עצם הנשמה הנק' ציון, צריך להיות בה הפדי' מהדברים המכסים עלי', שמונעים הגילוי בהנשמה שבגוף. והיינו שהפדי' שצ\"ל בבחי' ציון היא לא פדי' מהשבי', כי בעצם הנשמה אין שייךענין השבי' ח\"ו, וכמ\"ש<sup data-n=\"1073\">36</sup> וכבודי לאחר לא אתן, שוכבודי<sup data-n=\"1074\">37</sup> קאי על בחי' פנימיות המלכות, ובאדם הו\"ע פנימיות הלב, פנימיות הנשמה ועד לבחי' עצם הנשמה, שבחי' זו לאחר לא אתן, ומה שצ\"ל ענין הפדי' בבחי' ציון הוא רק היציאה מהדברים המכסים עלי' כנ\"ל [ועיין בהמבואר באגה\"ק<sup data-n=\"1075\">38</sup> ובהדרושים עה\"פ<sup data-n=\"1076\">39</sup> פדה בשלום נפשי בענין פדיית השכינה הכללית מהגלות ובענין פדיית כל ניצוץ פרטי מהשכינה שבנפש כל אחד מישראל ובשלום דוקא]. ופדי' זו היא במשפט, היינו ע\"י התורה, שע\"י עסק התורה מתגלה בחי' פנימיות הלב. אבל בכדי לפדות מהגלות הכחות של הנשמה (שבהתלבשות בגוף) שהם שבויים ממש, צריך לצדקה דוקא, ושבי' בצדקה. וע\"י שפודים אותם מהשבי', נעשה עי\"ז יתרון האור בתכלית השלימות<sup data-n=\"1077\">40</sup>, וכמשל בן מלך שכאשר הוא נמצא תמיד בבית אביו, אין השמחה בתוקף כ\"כ, משא\"כ כאשר בן המלך הי' בשבי' וטוחן בבית האסורים כו' ויצא לחפשי אל בית אביו המלך, הנה אז דוקא תתגדל השמחה מאד וישמחו שניהם שמחה רבה ועצומה<sup data-n=\"1078\">41</sup>. ובדוגמת הידוע<sup data-n=\"1079\">42</sup> בענין גודל השמחה שתהי' לע\"ל בהזמן דג' שבועות, ובפרט בהט' ימים, ובפרט בימי שבעה עשר בתמוז ות\"ב, שהשמחה דמועדים אלו [מה שימים אלו יהפכו לששון ולשמחה ולמועדים טובים<sup data-n=\"1080\">43</sup>] תהי' שמחה גדולה ביתר שאת ויתר עז מהשמחה שבמועדים ע\"ד הרגיל.ו) <b>והנה</b> עצם הענין ומהטעמים שהפדי' דבחי' עצם הנשמה היא במשפט שהוא התורה, והפדי' דבחי' כחות הנשמה שבאו בשבי' היא ע\"י צדקה שהיא כללות המצוות, הוא לפי שהתורה והמצוות גופא הן ג\"כ דוגמת ב' ענינים אלו. דהנה התורה גם כמו שירדה למטה, ואפילו בעת שנלמדת ע\"י אדם שאינו טהור, היא כמו שהיא למעלה, דבר הקב\"ה, וכדרשת רז\"ל<sup data-n=\"1081\">44</sup> עה\"פ<sup data-n=\"1082\">45</sup> הלא כה דברי כאש. ומכיון שהתורה אינה בבחי' התלבשות<sup data-n=\"1083\">46</sup>, הרי אין שייך בה ענין השבי' ח\"ו<sup data-n=\"1084\">47</sup>. אלא שמ\"מ שייך בה ענין הפדי', כי מצד הדברים שבהם ירדה (אף שאינה בהם בהתלבשות), אפשר שתהי' בהעלם<sup data-n=\"1085\">48</sup>. אמנם המצוות, מכיון שנתלבשו בדברים גשמיים, ציצית בצמר גשמי ותפלין בקלף גשמי וכו' וגם המצוות דחובות הלבבות צ\"ל נרגשות במוח ולב הגשמי, לכן שייך בהן ענין השבי'<sup data-n=\"1086\">49</sup>, וכמשנ\"ת במ\"א בענין מ\"ש<sup data-n=\"1087\">50</sup> שש אנכי על אמרתיך כמוצא שלל רב, שבמצוות הו\"ע השלל, היינו ששוללים ומוציאים מהלעו\"ז.\nז) <b>והנה</b> ב' ענינים הנ\"ל (בחי' ציון במשפט תפדה ובחי' ושבי' בצדקה) ישנם בכל ג' הבחינות דעולם שנה ונפש<sup data-n=\"1088\">51</sup>. ובבחי' נפש ישנם הן, הן בכאו\"א מישראל והן בכללות ישראל [כי מכיון שכאו\"א מישראל הוא עולם מלא<sup data-n=\"1089\">52</sup>, הרי מובן שהענינים שבכ\"א מישראל ישנם גם בכללות ישראל והענינים שבכללות ישראל ישנם גם בכאו\"א מישראל]. דכאו\"א מישראל<sup data-n=\"1090\">53</sup>, מצד עבודתו בקו התורה הוא בבחי' ציון במשפט תפדה, ומצד עבודתו בקו המצוות הוא בבחי' ושבי' בצדקה. ועד\"ז הוא גם בכללות ישראל, שנחלקים לב' סוגים יששכר וזבולון, מארי תורה ומארי עובדין טבין. דמארי תורה הם בבחי' ציון במשפט תפדה, ומארי עובדין טבין הם בבחי' ושבי' בצדקה. ובכללות יותר, הוא החילוק שבין צדיקים לבעלי תשובה<sup data-n=\"1091\">54</sup>. דבצדיקים אין שייך ענין השבי' ח\"ו שהרי לא יאונה לצדיק כל און<sup data-n=\"1092\">55</sup>, ועאכו\"כ בצדיקים שהםבבחי' ולבי חלל בקרבי<sup data-n=\"1093\">56</sup>. אלא שאעפ\"כ גם בהם שייך ענין הפדי', וע\"ד שלפעמים הצדיק נתפס בעון הדור<sup data-n=\"1094\">57</sup>, או ע\"ד מ\"ש גבי משה לך רד כי שחת עמך, שמצד שחת עמך נעשה ירידה<sup data-n=\"1095\">58</sup> גם בו<sup data-n=\"1096\">59</sup>, אבל מ\"מ מכיון שהירידה (וגם כאשר הוא נתפס בעון הדור) היא רק מצד ענינים שמחוץ ממנו, הרי גם אז אינו בשבי' ח\"ו כי ענינו של הצדיק הוא סימנא (דאלקות) בעלמא, כביכול, כמו שאלקות הוא למטה<sup data-n=\"1097\">60</sup>, דמציאותו (של הצדיק) היא זה שהוא שלוחו של אדם העליון, ושלוחו של אדם הוא כמותו ממש<sup data-n=\"1098\">61</sup>. ולכן, גם כשהוא בבחי' ירידה וכו', הפדי' שלו היא ע\"י התורה. לפי שבתורה, ענין זה (שגם למטה היא אלקות בגילוי, כנ\"ל בענין הלא כה דברי כאש) הוא בגלוי יותר. משא\"כ הבע\"ת, שעבודתם היא להוציא את הניצוצות שנפלו ונשבו בלעו\"ז (ובדוגמת – בקדושה – מ\"ש וישב ממנו שבי<sup data-n=\"1099\">62</sup>), לכן גם הגאולה צ\"ל בדוגמת זה. וזהו ושבי' בצדקה, שגאולתם בקו הצדקה, שהיא כללות המצוות [דכל הגוף נכלל בימין<sup data-n=\"1100\">63</sup>], שהעבודה דקו המצוות היא באופן דשבי ושלל. וע\"ד המבואר באגה\"ק<sup data-n=\"1101\">64</sup>, שעיקר עבודת ה' בעתים הללו בעקבות משיחא היא עבודת הצדקה (ודלא כבזמן הש\"ס, שת\"ת הי' עיקר העבודה שלהם), כי בכדי להעלות את סוכת דוד שנפלה עד בחי' רגלים ועקביים שהיא בחי' עשי' צ\"ל גם העבודה בבחי' עשי' דוקא, שהיא מעשה הצדקה.\nח) <b>ועד\"ז</b> גם בבחי' עולם, מקום, שישנם בו שני ענינים הנ\"ל. דעולם האצי' הוא מבורר<sup data-n=\"1102\">65</sup> ועולמות בי\"ע עליהם נאמר ומשם יפרד ודוקא בעלמא דפרודא עולם העשי' העבודה דמצוות מעשיות. ועד\"ז א\"י אשר עיני ה\"א בה מרשית השנה ועד אחרית שנה<sup data-n=\"1103\">66</sup>, משא\"כ ארץ העמים שגושה טמא ואוירה טמא<sup data-n=\"1104\">67</sup>, הנה בכדי לעשות ארץ העמים לארץ ישראל<sup data-n=\"1105\">68</sup> צ\"ל העבודה הגדולה יותר דושבי' בצדקה. ועד\"ז הוא גם בבחי' שנה, זמן, שיש בו ג\"כ שני סוגים הנ\"ל. שבכללות הוא החילוק שבין זמן הקיץ לזמן החורף, כמבואר במ\"א<sup data-n=\"1106\">69</sup> שבזמן הקיץ העבודה היא בנקל יותר מבזמןהחורף, שבימות החמה השמש זורח<sup data-n=\"1107\">70</sup> והוא בחי' שם הוי' (והיו\"ט שבקיץ הם בתכיפות יותר). וכדאיתא במדרש<sup data-n=\"1108\">71</sup> ע\"י שהן יוצאים מן הקיץ לחורף כו' למקום רחוק כו' לית בעונתה ליזיל ולמיתי. והיינו שהעבודה בזמן החורף היא רחוקה, קשה יותר מבזמן הקיץ. ועד\"ז הוא החילוק שבין יומין זכאין לימים שהם היפך הזכות<sup data-n=\"1109\">72</sup>. שהעבודה בימים דהיפך הזכות ה\"ה ע\"ד ושבי' בצדקה, מה שישראל (על ידי עבודתם) מהפכים הימים האלה לששון ולשמחה, בגאולה העתידה לבוא בקרוב ממש. וענין זה (הפיכת ימים אלו לששון ולשמחה) נעשה ע\"י העבודה דקו התשובה דוקא, כי ענין התשובה הוא אתהפכא חשוכא לנהורא, שזוהי מעלת עבודת הבע\"ת על עבודת הצדיקים. וזוהי גם השייכות דגאולה העתידה לענין התשובה דוקא [שישראל עושין תשובה (ועי\"ז דוקא) ומיד הן נגאלין<sup data-n=\"1110\">73</sup>, ועד שהעילוי דגאולה העתידה<sup data-n=\"1111\">74</sup> הוא מה שמשיח אתא לאתבא צדיקייא בתיובתא<sup data-n=\"1112\">75</sup>], כי החידוש שבגאולה העתידה הוא הענין דאתהפכא.\nט) <b>וע\"פ</b> הנ\"ל יובן מה שבפסוק זה מדובר רק ע\"ד שני הענינים דתורה (משפט) וצדקה, אף שישנם ג' קוין, כי הכוונה בענין התורה (משפט) וצדקה (בפסוק זה) היא לשני סוגים הכללים שבכל הבחינות דעולם שנה ונפש (עד\"ז – הענין דאורות וכלים, שם הוי' ושם אלקים וכו'). ובכל א' – צ\"ל העבודה בכל ג' הקוין. כי הפדי' מהגלות [הן בענינים אלו [מארי תורה וצדיקים (נפש), ארץ ישראל (עולם), ויומין זכאין (שנה)] שפדייתם מהגלות היא באופן דציון במשפט (תורה) תפדה. והן בענינים אלו [מארי עובדין טבין ובע\"ת, ארץ העמים, וימים שהם היפך הזכות] שפדייתם היא באופן דושבי' בצדקה], היא ע\"י העבודה בכל ג' הקוין דוקא. וכמרז\"ל<sup data-n=\"1113\">76</sup> כל העוסק בתורה וגמ\"ח ומתפלל עם הצבור כו' כאילו פדאני לי ולבני מבין אומות העולם, שפדיית הקב\"ה וישראל מבין אוה\"ע היא ע\"י העבודה בכל ג' הקוין (ובאופן של צבור<sup data-n=\"1114\">77</sup>). וכמו שנת\"ל בענין בחי' ציון, דזה מה שישראל הם בחי' ציון הוא ע\"י עבודתם בכל ג' הקוין [ויתירה מזו, עי\"ז שכל ג' הקוין הם בשלימות]. ומ\"ש ציון במשפט (תורה) תפדה הוא לפי שהפדי' דבחי' ציון (בכל ג' הבחי' דעש\"ן) היא בעיקר ע\"י התורה, עד\"ז הוא גם בענין ושבי' בצדקה, שהפדי' דשבי' (בכל ג' הבחינות דעש\"ן) היא ע\"י העבודה בכל ג' הקוין דוקא. ומ\"ש ושבי' בצדקה (דוקא) הוא לפי שפדייתם (של שבי') היא בעיקר ע\"י הצדקה. ונוסף לזה, גם בענין המצוותגופא (דצדקה היא כללות המצוות, כנ\"ל) יש כל ג' הקוין, ההלכה בזה שהוא ענין התורה, העשי' בדבר הגשמי שהוא הקו דגמ\"ח, העלאת הגשמי (שעושים בו המצוה) שהוא קו העבודה, דבקרבנות נאמר ריח ניחוח שריח הו\"ע ההעלאה מלמטלמ\"ע<sup data-n=\"1115\">78</sup>, וכן תפלה (שכנגד קרבנות) עז\"נ<sup data-n=\"1116\">79</sup> סולם מוצב ארצה וראשו מגיע השמימה. נוסף על הידוע שבכל מצוה יש ג' הענינים דמחשבה דיבור ומעשה שהם ג' הקוין<sup data-n=\"1117\">80</sup>. וע\"פ הנ\"ל יובן גם סדרן של ג' דברים אלו (במרז\"ל הנ\"ל), תורה גמ\"ח ותפלה (לא כסדר הרגיל), כי בכללות הענין דפדאני לי ולבני מבין האומות הוא ע\"י העסק בתורה וגמ\"ח, ציון במשפט תפדה ושבי' בצדקה, אלא שבכל ענין (ובפרט בענין הפדי' מהגלות<sup data-n=\"1118\">81</sup>) צ\"ל כל ג' הקוין, ומתפלל עם הצבור<sup data-n=\"1119\">82</sup>.\nי) <b>וזהו</b> ציון במשפט תפדה ושבי' בצדקה, שפסוק זה נקבע בההפטורה דשבת שלפני ת\"ב (דשבת מיני' מתברכין כולהו יומין<sup data-n=\"1120\">83</sup> – כולל ת\"ב), שזהו בדוגמת הנהגתו של הקב\"ה שמקדים רפואה למכה<sup data-n=\"1121\">84</sup>, שרפואתו של הקב\"ה היא באופן שמלכתחילה לא אשים עליך<sup data-n=\"1122\">85</sup>, ועי\"ז פועלים הפדי' דכאו\"א מישראל הן בנשמתו והן בגופו ונפשו הבהמית, שפדיית הנשמה היא (בכללות) באופן דציון במשפט תפדה, ופדיית הגוף ונה\"ב היא באופן דושבי' בצדקה [כמובן מהמבואר בתניא<sup data-n=\"1123\">86</sup>, שהנשמה עצמה אינה צריכה תיקון כלל וירידתה למטה הוא רק בכדי לתקן את הגוף ונה\"ב]. ובכדי שהתורה והצדקה (יעלו למעלה, שעי\"ז) יפעלו הפדי' בפועל, הוא ע\"י התפלה, קו העבודה, כנ\"ל<sup data-n=\"1124\">87</sup>.\nיא) <b>וע\"י</b> העבודה בכל ג' הקוין, הנה בדורות הקודמים נעשה עי\"ז כאילו פדאני (בכ\"ף הדמיון), והוא ע\"ד המבואר באגה\"ק<sup data-n=\"1125\">88</sup> בענין גאולה הפרטית. משא\"כ עכשיו אשר הנה זה עומד אחר כתלנו וכידוע השיחה של בעל הגאולה (די\"ב תמוז), שכבר נגמרו כל הבירורים וצריך רק צופּוצן די קנעפּלאַך<sup data-n=\"1126\">89</sup>, הנה עכשיו, ע\"י העסק בתורה ובגמ\"ח ותפלה עם הצבור יהי' פדאני כו' ממש, ובאופן של פדה בשלוםנפשי, כי אמיתית הענין דפדי' בשלום תהי' בביאת המשיח דוקא, כמו שמבאר כ\"ק אדמו\"ר האמצעי<sup data-n=\"1127\">90</sup>. וזהו ג\"כ מה שכתב אדמו\"ר הזקן (באגה\"ק שלו בבואו מפ\"ב<sup data-n=\"1128\">91</sup>) וכשקריתי בס' תהלים בפסוק פדה בשלום נפשי כו' יצאתי בשלום מה' שלום, דהנה ידוע<sup data-n=\"1129\">92</sup> שעיקר הענין דיפוצו מעינותיך חוצה הותחל לאחרי פ\"ב. ולכן יצא בשלום כשקרא בפסוק פדה בשלום נפשי, כי (עיקר) הענין דפדה בשלום הוא בגאולה העתידה (כנ\"ל), ויפוצו מעינותיך חוצה הוא ההכנה<sup data-n=\"1130\">93</sup> לזה, לקא אתי מר.\n<b>ועי\"ז</b> פתח וסלל את הדרך, שכאו\"א יכול (ולכן צריך הוא) לעסוק בהכנה זו ולהביא את הגאולה ע\"י שיעשה את התלוי בו וכפסק הרמב\"ם<sup data-n=\"1131\">94</sup> שע\"י פעולה אחת (הן במעשה, הן בדיבור והן במחשבה) מכריע את עצמו ואת כל העולם כולו לכף זכות וגורם לו ולהם תשועה והצלה, שנעשה פדה בשלום נפשי, פדאני לי ולבני מבין אוה\"ע, בקרוב ממש ובעגלא דידן, בגאולה האמיתית והשלימה ע\"י משיח צדקנו.\n**********",[["1037","*","מאמר זה ושלאחריו יצאו לאור בשעתו, \"<i>יום השלישי שהוכפל בו כי טוב</i>,<i> ז' מנ\"א ה'תשל\"ה</i>\"."],["1038","1","ישעי' א, כז."],["1039","2","ראה רשימות הצ\"צ לאיכה (ע' 28. אוה\"ת נ\"ך ח\"ב ריש ע' א'נט): ישעי' מלשון וישע ה' כו' (ובאגה\"ק ס\"ג: <i>ישועה</i> היא מלשון וישע ה')."],["1040","3","ב\"ב יד, ב."],["1041","4","קה\"י ערך ישעי'. – ספר שהובא בכ\"מ ע\"י אדמו\"ר (מהורש\"ב) נ\"ע."],["1042","5","שבת פט, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א ויצא כא, רע\"ג</a> ואילך."],["1043","6","שני סוגים אלו הם דוגמת \"מטעמים לשון רבים, שני מיני נחת רוח\" – ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז</a>."],["1044","7","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380384\" data-slug=\"likkutei-torah\" data-id=\"4001380384\">לקו\"ת במדבר יט, סע\"א</a>. סידור שער התקיעות רמז, א (בענין גבורות דיצחק). ובכ\"מ. ולהעיר גם מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא שם</a>, שדוקא \"דברים חריפים או חמוצים\" (כאשר הם מתובלים כו') הם <i>משיבים הנפש</i>."],["1045","8","נדפסו בלקו\"ת ר\"פ דברים (ובקונ' בפ\"ע (קה\"ת, תשט\"ו. תש\"ל) – עם הגהות הצ\"צ (ולאח\"ז באוה\"ת דברים כרך ו בתחלתו)). אוה\"ת שם (כרך א ע' כז ואילך). אוה\"ת לישעי' עה\"פ."],["1046","9","יבמות סא, רע\"א."],["1047","10","של\"ה כ, ב. רסח, ב. שא, ב. עש\"מ מאמר אכ\"ח ח\"ב סל\"ג."],["1048","11","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">לקו\"ת תצא לה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380969\" data-slug=\"likkutei-torah\" data-id=\"4001380969\">ר\"ה סב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">שה\"ש טז, ד</a>. ובכ\"מ."],["1049","12","לקו\"ת (ו<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780003\" data-slug=\"or-hatorah-hb\" data-id=\"8159780003\">אוה\"ת דברים כרך ו</a>) שבהערה 8. קונטרס הנ\"ל (ע' 3. 10)."],["1050","13","ואתחנן ו, ו."],["1051","14","ספרי שם. פרש\"י שם."],["1052","15","ואפ\"ל שזהו הטעם שלא הובא כאן (ובכמה מקומות) מרז\"ל (פרש\"י יתרו יט, א. עקב יא, יג. תבא כו, טז) יהיו בעיניך <i>חדשים</i> (ולא <i>כ</i>חדשים – בכ\"ף הדמיון) – כי דרגא זו לאו מכאו\"א תמיד נדרשת היא."],["1053","16","תנחומא נשא יא. במדב\"ר פי\"ב, ג."],["1054","17","ראה לקו\"ת ר\"ה שם, שבחי' ישראל (היינו בחי' הנשמה שלמעלה מהגוף) היא \"כענין שמשא . . וכמו בהשמש אין שום שינויים בחי' לא שניתי כך בבחי' ישראל\".\nועפ\"ז יומתק הקשר להמובא בהדרושים שבהערה 12 שהנשמות \"נמשכו מבחי' מחשבה . . המחשבה היא תמידית\" – כי הענין דבכ\"י כחדשים הוא מצד ענין התמידות (למעלה משינויים) שבנשמה."],["1055","18","אוה\"ת דברים שם ע' לו."],["1056","19","זח\"א רכה, א. הובא בלקו\"ת (שבהערה 8 – א, סע\"ב) לענין ציון במשפט גו'."],["1057","20","תענית פ\"ד סה\"ב. מגילה פ\"ג סה\"ו. וכ\"ה בזח\"ג לה, א (הובא באוה\"ת שם)."],["1058","21","ישעי' נא, טז."],["1059","22","אוה\"ת שם (מקה\"ע לירושלמי שם). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380333\" data-slug=\"likkutei-torah\" data-id=\"4001380333\">לקו\"ת במדבר ו, ב</a>."],["1060","23","שבת קלח, ב."],["1061","24","רש\"י שבת שם."],["1062","25","ראה ירושלמי פאה פ\"א ה\"א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["1063","26","<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא ספ\"ה</a>. אגה\"ק ס\"ג. ובכ\"מ."],["1064","27","ראה אוה\"ת שם (ע' מ): כסתיך זהו\"ע כסותה."],["1065","28","קה\"ע לירושלמי שם."],["1066","29","אוה\"ת שם."],["1067","30","להעיר מזח\"ג רלב, א ושם ז, א. רסה, סע\"א. שמו\"ר פ\"ג, טו. ויק\"ר פ\"ב, ג. מכילתא שמות יח, יט."],["1068","31","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380063\" data-slug=\"likkutei-torah\" data-id=\"4001380063\">לקו\"ת פקודי ה, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380409\" data-slug=\"likkutei-torah\" data-id=\"4001380409\">נשא כה, ב</a>. ובכ\"מ."],["1069","32","ראה תו\"א לה, ב, דזה שכל המצוות נק' מצוות הוי' הוא לפי שהקב\"ה מקיים את המצוות. ושם, שע\"י שהקב\"ה מקיים את המצוות, הם נעלים יותר מכמו שהם מצד עצמם."],["1070","33","וכפי' הה\"מ באין עומדין להתפלל אלא מתוך כובד ראש דלמע' דוקא ופשיטא דלא הוי כאותן דעבדין לגרמייהו (ר\"פ ויגש ובכ\"מ)."],["1071","34","ח\"א ד, סע\"ב ואילך. וראה גם זח\"ג לה, א."],["1072","35","הושע יד, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380969\" data-slug=\"likkutei-torah\" data-id=\"4001380969\">לקו\"ת ר\"ה סב, ג</a> ואילך."],["1073","36","ישעי' מב, ח. מח, יא."],["1074","37","ראה אוה\"ת שמע\"צ ס\"ע א'תתכח. סהמ\"צ להצ\"צ קפא, ב."],["1075","38","סי' ד'."],["1076","39","תהלים נה, יט."],["1077","40","משא\"כ \"יתרון האור\" שע\"י \"ציון במשפט תפדה\" – מכיון שבחי' עצם הנשמה לא הייתה בשבי', הרי אין בזה הענין דהפיכת החשך (והחשך הוא \"רק גרם בעלמא\"), ולכן גם \"יתרון האור\" שבזה אינו בתכלית השלימות – ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670125\" data-slug=\"torat-chaim\" data-id=\"2300670125\">תו\"ח נח ס, סע\"ב</a> ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091021\" data-slug=\"likkutei-sichot\" data-id=\"1300091021\">לקו\"ש ח\"ט ע' 21</a> הערה 52.\nולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, סע\"א</a>): ואין לך שמחה גדולה כצאת מהגלות והשבי' – שיש לומר: ענין ה\"גלות\" שייך גם בבחי' ציון (כנ\"ל בפנים, מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">לקו\"ת דברים א, סע\"ב</a>), ומוסיף (בתניא שם) \"והשבי'\" – שעי\"ז השמחה גדולה יותר.\nולהעיר גם מהאריכות דהמשל בתניא שם: \"בשבי' וטוחן בבית האסורים ומנוול באשפה\" – כי כל פרטים אלו מוסיפים בהשמחה."],["1078","41","תניא שם. אוה\"ת שמע\"צ ע' א'תשפ."],["1079","42","ראה ד\"ה נחמו עת\"ר (ע' רכא) בפירוש מרז\"ל \"לא היו ימים טובים לישראל כחמשה עשר באב\", \"שהוא עוד יו\"ט ביותר משאר מועדים, דהיינו אפילו מפסח וסכות\". ומזה שמבאר שם (ס\"ע רכט ואילך) שהטעם לזה הוא לפי שהעלי' באה לאחרי הירידה בת\"ב – מובן שכ\"ה (ובמכש\"כ) בנוגע לה\"מועדים\" דימים אלו גופא.\nולהעיר גם מתו\"ח בראשית מ, ד: \"וכל שמתגלה יותר הדין והעונש יותר ניכר בזה עוצם האה\"ר . . שט\"ב . . יהפך ליו\"ט כי יתגלה בו מה שהי' בהעלם מבחי' האה\"ר שמלובש בחרון אפו . . וזהו שת\"ב הוא באותו יום שהוא יום א' דפסח\". שמזה משמע, שהיו\"ט דת\"ב יהי' גדול יותר מהיו\"ט דפסח."],["1080","43","זכרי' ח, יט. תוספתא סוף מס' תענית. בזכרי' שם: <i>יהי'</i> לששון גו'. והלשון \"יהפכו\" (שבפנים) הוא ע\"פ היעוד בירמי' לא, יב: <i>והפכתי</i> אבלם לששון. וראה יל\"ש ירמי' רמז רנט: עלה כו' על מנת כו' והפכתי גו'. רשימות הצ\"צ לאיכה ע' כו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי (ע' א'שפד</a> ואילך). ובסליחות לי\"ז תמוז – <i>הפך</i> לנו לששון ולשמחה. ובס' השיחות קיץ ה'ש\"ת (ע' קנז): זאָל נדחה ווערן באמת ויהפך לששון ולשמחה.\nומ\"ש בזכרי' שם: <i>יהי'</i> לששון גו' – י\"ל לפי שהמדובר בזכרי' הוא בזמן בית שני (כאמרו \"לבית יהודא\" – ראה רד\"ק שם) שחסרו בו ה' דברים (יומא כא, ב). וראה ט\"ז לשו\"ע או\"ח ר\"ס תק\"נ. יד אפרים שם."],["1081","44","ברכות כב, א. וע\"פ מ\"ש בפנים – יש לומר הפירוש ב\"דברי כאש\", דמכיון שהיא \"דברי\" (דברי הקב\"ה), לכן היא \"כאש\" שאינו מקבל טומאה."],["1082","45","ירמי' כג, כט."],["1083","46","\"וענין התלבשות בתורה אין זה מענין ההתלבשות של התעסקות, כ\"א מה שהתורה מכנסת עצמה לדון בזה\" (ד\"ה ויאמר משה תש\"ד פ\"כ)."],["1084","47","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380796\" data-slug=\"likkutei-torah\" data-id=\"4001380796\">לקו\"ת ראה כ, א</a>: דהתורה היא עץ החיים . . ואין כח בקליפה לשלוט שם.\nומ\"ש בתניא פל\"ט (ועד\"ז בהל' ת\"ת פ\"ד ה\"ג) ש\"התורה היא בבחי' גלות בתוך הקליפות לפי שעה\" – <i>אין</i> זה שהקליפות <i>שולטים</i> ח\"ו עלי', כי אם, שעל ידם היא בבחי' העלם אז (וע\"ד ה\"גלות\" שבבחי' ציון)."],["1085","48","ולכאורה צ\"ע שהרי גם מוסיפה כח בקליפה לפי שעה (הל' ת\"ת שם) וביומא עב, ב: נעשית לו סם כו'. ואף שזהו רק בנוגע פעולתה על האדם – וכדיוק לשון רז\"ל \"נעשית <i>לו</i>\" – מ\"מ, היא <i>נעשית</i> סם כו'. ואולי אפ\"ל שזהו מצד בחי' התורה כמו שהיא נעשית אחת מרמ\"ח מ\"ע שהם כנגד רמ\"ח איברים (ולא בדוגמת דם – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת (במדבר יג, א</a>)). ולכן גם אפ\"ל מגלה פנים <i>בתורה</i> שלא כהלכה. ועצ\"ע."],["1086","49","ראה לקו\"ת שם, שדוקא בתורה \"אין כח בקליפה לשלוט\", \"משא\"כ במצוה כו'\". וראה גם לקו\"ת ואתחנן ט, ד. ד\"ה אז ישיר תש\"ד פ\"ל."],["1087","50","תהלים קיט, קסב."],["1088","51","שעל ענין ג' בחי' אלו הוא היסוד של ס' יצירה (אוה\"ת יתרו ע' תתטז ואילך)."],["1089","52","סנהדרין לז, א (במשנה)."],["1090","53","מצד נפשו – נוסף ע\"ז שגוף ונפש הם ג\"כ בדוגמת ב' בחי' הנ\"ל – כדלקמן ס\"י."],["1091","54","אוה\"ת דברים ע' נא."],["1092","55","משלי יב, כא – (יאונה בשוגג (פרש\"י שם), ולמזיד – הרי אינו שייך)."],["1093","56","תהלים קט, כב. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>, שבחינה זו היא \"אמיתת שם התואר והמעלה\" דצדיק."],["1094","57","ראה שבת נד, ב. ד\"ה אם רוח המושל תרצ\"ה (בסה\"מ קונטרסים ח\"ב שנח, ב ואילך)."],["1095","58","אף שלא נתפס בעון הדור, כמבואר בד\"ה אם רוח המושל שם."],["1096","59","תשא לב, ז. ברכות לב, א. פירש\"י עה\"ת שם."],["1097","60","וי\"ל שזהו למעלה מסימנא כו' – ולהעיר ממרז\"ל: והוי' בהיכל קדשו דא ריב\"א בכנישתא מדרתא דקסרין (ירוש' בכורים פ\"ג ה\"ג); מאן פני האדון הוי' דא רשב\"י (זח\"ב לח, א)."],["1098","61","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">לקו\"ת ויקרא א, ג</a>. וראה שיחת ט\"ז תמוז תשל\"ה (נדפסה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131286\" data-slug=\"likkutei-sichot\" data-id=\"1300131286\">לקו\"ש חי\"ג ע' 280</a> ואילך) ס\"ב ובהערות שם."],["1099","62","חקת כא, א. וראה פירש\"י (ומפרשיו) שם."],["1100","63","אגה\"ק סל\"ב."],["1101","64","סי' ט'."],["1102","65","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א</a> בי' כי כאשר השמים (ג, א). ובכ\"מ."],["1103","66","עקב יא, יב."],["1104","67","שבת טו, ב. רמב\"ם רפי\"א מהל' טומאת מת."],["1105","68","ברוחניות וכפתגם אדמו\"ר הצ\"צ (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021345\" data-slug=\"likkutei-sichot\" data-id=\"1300021345\">לקו\"ש ח\"ב ע' 621</a>) מאַך דאָ ארץ ישראל. ועי\"ז נעשה ה\"שתתפשט א\"י בכל העולם\" (ראה פסיקתא רבתי פ' שבת ור\"ח. ילקוט ישעי' רמז תקג)."],["1106","69","סד\"ה ביום השמע\"צ תרל\"ב. ולהעיר מסד\"ה להבין ענין שמח\"ת תש\"ו באו\"א קצת. – ועייג\"כ אוה\"ת להצ\"צ שמע\"צ ע' א'תשעד באופן אחר."],["1107","70","בד\"ה ביום השמע\"צ הנ\"ל מציין שם ללקו\"ת ד\"ה שחורה אני דענין שזפתני השמש הוא בחי' יחו\"ע כו'."],["1108","71","שהש\"ר פ\"ז עה\"פ מה יפו פעמיך. וראה סד\"ה להבין ענין שמח\"ת שם: נשואות במקום קרוב הם הצדיקים . . נשואות למקום רחוק הם הבע\"ת כו'."],["1109","72","ראה תענית כט, א."],["1110","73","רמב\"ם הל' תשובה פ\"ז ה\"ה."],["1111","74","משא\"כ ביצי\"מ שהיו בבחי' צדיקים וראה ד\"ה החודש הזה (אוה\"ת בא ע' רנט, רעא)."],["1112","75","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381094\" data-slug=\"likkutei-torah\" data-id=\"4001381094\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. וראה זח\"ג קנג, ב."],["1113","76","ברכות ח, א. וראה חדא\"ג מהרש\"א שם: הן הן ג' עמודי העולם ששנינו על שלשה דברים העולם עומד כו'. ועיין בהצ\"צ לתהלים עה\"פ פדה בשלום נפשי (ע' רד)."],["1114","77","וכמש\"נ הטעם: כי <i>ברבים</i> היו עמדי. וראה בהצ\"צ שם בארוכה. – וכבר דובר (שיחת ט\"ז תמוז תשל\"ה. נדפסה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131288\" data-slug=\"likkutei-sichot\" data-id=\"1300131288\">לקו\"ש חי\"ג ע' 282</a> ואילך) ע\"ד ההשתדלות עתה אודות העסק בתורה ובגמ\"ח ועאכו\"כ תפלה – בצבור."],["1115","78","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370096\" data-slug=\"torah-or\" data-id=\"3901370096\">תו\"א כ, רע\"ד</a>. לקו\"ת שמע\"צ צב, ד. ובכ\"מ."],["1116","79","ויצא כח, יב. זח\"א רסו, ב. ח\"ג שו, ב. תקו\"ז תי' מה."],["1117","80","ראה רשב\"א (הובא ברשימות הצ\"צ שם (ע' רה)): ג' דברים הנ\"ל תורה וגמ\"ח ותפלה הם מחשבה דיבור ומעשה."],["1118","81","ראה רשימות הצ\"צ שם (ריש ע' רח) בענין הפדיון \"שהם הג' שמות . . נמשכים ע\"י תורה עבודה וגמ\"ח\"."],["1119","82","ועפ\"ז יובן מה שמחלק ג' הענינים לב' חלוקות [תורה וגמ\"ח הו\"ע בשלום, ותפלה בצבור הו\"ע כי ברבים היו עמדי – ראה רש\"י ברכות שם]. וראה לקמן הערה 87."],["1120","83","זח\"ב סג, ב. פח, א."],["1121","84","מגילה יג, ב."],["1122","85","בשלח (טו, כו) ולפי פשוטו (פרש\"י שם וכגירסת הרא\"ם והדפוסים)."],["1123","86","פל\"ז (מח, ב)."],["1124","87","ועפ\"ז יומתק לשון הכתוב פדה בשלום נפשי גו' כי ברבים היו עמדי – ד\"ברבים היו עמדי\" בא בתור טעם (\"כי\") על \"פדה בשלום נפשי\" – כי ע\"י התפלה (בצבור) התורה וגמ\"ח עולים ופועלים פעולה הנ\"ל."],["1125","88","סי' ד'."],["1126","89","שיחת שמח\"ת תרפ\"ט (סה\"ש תרפ\"ט ע' 42)."],["1127","90","ראה ד\"ה פדה בשלום נפשי (בשעה\"ת לאדמו\"ר האמצעי) פי\"א. וראה ד\"ה זה דשנת העת\"ר (תער\"ב ח\"ב ע' תשסו ואילך) ותשכ\"ו (לעיל ח\"ב ע' קטז)."],["1128","91","נדפס בחוברת י\"ט כסלו ע' 23. אגרות-קודש אדמו\"ר הזקן ח\"א ע' צח ואילך."],["1129","92","תורת שלום ס\"ע 112 ואילך."],["1130","93","אגה\"ק הידועה דהבעש\"ט – נדפסה בתחילת ס' כתר שם טוב. ובכ\"מ. והרי הכנה פשיטא דצ\"ל מעין הענין שאליו באה ההכנה."],["1131","94","הל' תשובה פ\"ג ה\"ד."]]],[1500390016,"<h3>בס\"ד. ש\"פ דברים, שבת חזון, תשל\"ה<sup data-n=\"1132\">*</sup>.</h3>\n<b>ציון</b> במשפט תפדה ושבי' בצדקה<sup data-n=\"1133\">1</sup>, ומבאר כ\"ק אדמו\"ר הזקן<sup data-n=\"1134\">2</sup> וכ\"ק אדמו\"ר הצ\"צ<sup data-n=\"1135\">3</sup> (ורבותינו נשיאינו שלאח\"ז), דציון קאי על בחי' פנימיות הלב. ונק' ציון לשון סימן, כי בחי' פנימיות הלב היא ציון וסימן ללמעלה. ובבחי' זו אא\"פ להיות שבי' ח\"ו, רק שהיא צריכה לפדי' בלבד, והפדי' היא במשפט היינו תורה, כתרגומו ע\"פ כמשפט הראשון<sup data-n=\"1136\">4</sup> כהלכתא קדמיתא. ושבי' הם כחות הגלויים של הנשמה שבבחי' התלבשות בגוף, בחי' רגל שבנשמה, שהם בבחי' שבי' ממש, ופדייתם מן השבי' היא בצדקה דוקא, שהוא מעשה המצוות, כמשנת\"ל (בד\"ה ציון במשפט<sup data-n=\"1137\">5</sup>) בארוכה.\nיב) <b>והנה</b> לפי פירוש זה, ציון במשפט תפדה (פדי' שע\"י תורה) הוא למעלה מושבי' בצדקה (פדי' שע\"י מצוות), וע\"פ משנ\"ת בכ\"מ שתורה היא למעלה ממצוות. אמנם ברשימות הצ\"צ לנ\"ך<sup data-n=\"1138\">6</sup> עה\"פ ציון במשפט תפדה ושבי' בצדקה, מביא פירוש, שושבי' הו\"ע לאתבא צדיקייא בתיובתא. דציון קאי על צדיקים<sup data-n=\"1139\">7</sup>, ושבי' דציון הו\"ע לאתבא צדיקייא בתיובתא<sup data-n=\"1140\">8</sup>, ופדיית הצדיקים היא ע\"י התורה, משא\"כ לאתבא צדיקייא בתיובתא נעשה ע\"י צדקה דוקא. ולפי פירוש זה ושבי' בצדקה הוא למעלה מציון במשפט תפדה, ולא עוד אלא שהוא עילוי שלא בערך. וכמובן גם מזה שלאתבא צדיקייא בתיובתא הוא ע\"י משיח דוקא, וכמאמר<sup data-n=\"1141\">9</sup> משיח אתא לאתבא צדיקייא בתיובתא, שדרגת נשמת משיח היא באין ערוך מדרגות שאר הנשמות, וכידוע בכתבי האריז\"ל<sup data-n=\"1142\">10</sup>, שדרגת הנשמה שזכו אלי' גדולי ישראל שעד משיח היא רק בהבחינות נרנ\"ח, ואדם הראשון זכה לחי', משא\"כ משיח יזכה ליחידה, יחידה הכללית של כללישראל. והרי העילוי דבחי' יחידה על הבחינות נרנ\"ח הוא עילוי שבאין ערוך. וכמובן גם מזה שנקראת יחידה מלשון יחיד, שתואר זה מורה אשר אין לה ערך להבחינות דנרנ\"ח. וכידוע<sup data-n=\"1143\">11</sup> ההפרש בין יחיד לאחד, דאחד מורה שיש לו ערך לעוד דבר [דהגם שהתואר אחד אינו כהתואר ראשון, שראשון מכריח שיש שני, משא\"כ אחד הרי יש אחד ואין שני גו' לו<sup data-n=\"1144\">12</sup>, מ\"מ, מזה גופא שצריך לומר ואין שני הרי מוכח שאפשר שיהי' שני לו, בערך לו כו'], משא\"כ התואר יחיד, הרי זה גופא מורה שאין שני לו. ומזה מובן גודל העילוי דלאתבא צדיקייא בתיובתא, מכיון שזהו אחד הענינים שיתחדשו ע\"י משיח דוקא, בחי' יחידה.\nיג) <b>והנה</b> פירוש זה שבחי' ושבי' בצדקה היא למעלה מבחי' ציון במשפט תפדה הוא בהתאם עם הפירוש שבלקו\"ת ובס' הליקוטים להאריז\"ל<sup data-n=\"1145\">13</sup> עה\"פ ציון במשפט תפדה [אלא ששם מבאר ב' הבחינות בדרגא תחתונה], דציון היא נקודת ציון יסוד שבנוקבא ולפי שהוא חלול והאורות מתגלים שם שם הוא אחיזת החיצונים ולכן אמר שבמשפט כו' גורמין שתפדה ודוחין משם החיצונים, אבל עדיין אין כ\"ז רק כדי שלא יתאחזו בה לבד ותהי' ניכרת שם במקומה ולא תעלה עדיין למקומה הראשון ותצא מביניהם מכל וכל. אבל כדי להוציא' מביניהם ולהעלותה ולהושיבה למקומה הראשון צריך שיעשו כו' צדקה כו' וזהו ושבי' בצדקה להשיבה למקומה צריך צדקה ובזכות הצדקה תשוב למקומה הראשון. הרי שושבי' בצדקה הוא למעלה מציון במשפט תפדה. וכן מובן גם בפשטות, כמש\"כ שם, דמשפט (הגם דמשפט איהו רחמי<sup data-n=\"1146\">14</sup>) ענינו הוא כפי שורת הדין, משא\"כ צדקה הוא לפנים משורת הדין.\nיד) <b>והנה</b> מבואר במ\"א<sup data-n=\"1147\">15</sup> שפירושים שהם בכתוב אחד שייכים זל\"ז, ומזה מובן, אשר הפירוש דושבי' בצדקה הוא למטה מציון במשפט תפדה יש לו שייכות עם הפירוש שושבי' בצדקה הוא למעלה מציון במשפט תפדה (והוא ע\"ד הידוע<sup data-n=\"1148\">16</sup> בענין חותם המתהפך). והענין הוא, הנה ידוע<sup data-n=\"1149\">17</sup> שמרז\"ל<sup data-n=\"1150\">18</sup> תלמוד גדול הוא עכשיו, אבל בימות המשיח יהי' מעשה גדול. והנה תלמוד ומעשה הם בדוגמת צומח ודומם, ולעתיד יהי' מעשה גדול, כי אז תתגלה מעלת הדומם. והוא ע\"ד המבואר<sup data-n=\"1151\">19</sup> ע\"פ ויגש אליו יהודה בענין ההפרש בין משכן לביהמ\"ק [שענין זה יש לו שייכות מיוחדת לשבת חזון, וכמ\"ש הרר\"ה מפּאַריטש<sup data-n=\"1152\">20</sup>: ויתבאר עומק ענין זה (שבשבתחזון מראין לכאו\"א המקדש דלעתיד) עם המבואר במ\"א בענין ויגש אליו יהודה, קורות בתינו כו']. שהמשכן הי' עצי שטים, ארזים, צומח, משא\"כ ביהמ\"ק הי' מאבנים ועפר דוקא (ואסור לעשות בו עץ בולט כו' כמ\"ש<sup data-n=\"1153\">21</sup> לא תטע לך אשרה כל עץ). לפי שבביהמ\"ק הי' גילוי מעלת הדומם. ועיקר גילוי מעלת הדומם יהי' לע\"ל (בביהמ\"ק השלישי), שאז יתעלה יהודה (בחי' דומם) להיות למעלה מיוסף (בחי' צומח), וכמ\"ש<sup data-n=\"1154\">22</sup> הנה אני לוקח את עץ יוסף גו' ונתתי אותם עליו את עץ יהודה גו' ועבדי דוד מלך עליהם גו' ודוד עבדי נשיא להם לעולם<sup data-n=\"1155\">23</sup>. דזהו ג\"כ מה שלע\"ל יהי' מעשה גדול, כי ענינו של דוד הוא מעשה<sup data-n=\"1156\">24</sup>, וכמבואר במ\"א<sup data-n=\"1157\">25</sup> בענין ההפרש שבין דוד ליהונתן (מל' ויסוד ע\"ד יודא ויוסף) בן שאול, דיהונתן בן שאול הו\"ע תלמוד (עבודתו ע\"פ טו\"ד משא\"כ שמוע מזבח טוב (קב\"ע דדוד) ונאמר שאול מרחובות הנהר, דרחובות הנהר הו\"ע הבנה והשגה, תלמוד) ודוד הוא בחי' מעשה. ונאמר עד דוד הגדיל.\nטו) <b>והנה</b> הגם שעכשיו תלמוד גדול, מ\"מ יש כמה ענינים (גם עכשיו) שבהם מעלה למעשה על התלמוד. וכמו מה שמבטלין ת\"ת מפני מצוה שא\"א לעשותה ע\"י אחרים<sup data-n=\"1158\">26</sup>. ותוכן אגה\"ק ד\"ה איהו וחיוהי [שכתבה כ\"ק אדמו\"ר הזקן בכפר פּייענא בימים שלפני הסתלקותו<sup data-n=\"1159\">27</sup>] ה\"ה בהמעלה דמצוות מעשיות. וטעם הדבר שגם עכשיו מדגישים מעלת המעשה י\"ל שהוא לפי שכל הגילויים דלעתיד תלויים במעשינו ועבודתנו כל משך זמן הגלות<sup data-n=\"1160\">28</sup>, ומכיון שלעתיד יהי' מעשה גדול, לכן גם עכשיו מדגישים מעלת המעשה, כי עי\"ז יהי' הגילוי דלעתיד שאז יהי' מעשה גדול. וע\"ד המבואר באגה\"ק<sup data-n=\"1161\">29</sup> שלא אמרו רז\"ל ת\"ת שקול כנגד גמ\"ח אלא בימיהם משא\"כ בעתים הללו בעקבות משיחא, עיקר עבודת ה' היא עבודת הצדקה.\nטז) <b>ועפ\"ז</b> יתאימו ב' הפירושים בושבי' בצדקה, שהפירוש שושבי' בצדקה הוא למטה מציון במשפט תפדה הוא ע\"ד תלמוד גדול. אמנם מצד זה שלעתיד יהי' מעשה גדול [וענין זה ישנו גם עכשיו, כנ\"ל], הנה מצד זה, ושבי' בצדקה הוא למעלה מציון במשפט תפדה. וכמו שהוא בענין הצדקה, שמצד הענינים דלעתיד יש בה מעלה לגבי תורה כנ\"ל, עד\"ז הוא גם בענין התשובה (ושבי'), שישבה מעלה לגבי תורה, וכמארז\"ל<sup data-n=\"1162\">30</sup> שאלו לתורה כו' שאלו להקב\"ה אמר יעשה תשובה ויתכפר לו. אלא שמעלה זו שבתשובה היא באה לאחרי קדימת התורה, שלכן מקדים שאלו לתורה כו' [ועד\"ז הוא גם בנוגע מה שמקדים שאלו לחכמה כו' שאלו לנבואה כו'], לפי שתחילה צ\"ל הענין ד[חכמה נבואה ו]תורה, ומזה באים למעלת התשובה, שאמיתית ענין מעלת התשובה תתגלה לעתיד, ומשיח אתא לאתבא צדיקייא בתיובתא, ואמרו רז\"ל שגאולה העתידה תהי' ע\"י התשובה דוקא, דישראל עושין תשובה ומיד הן נגאלין<sup data-n=\"1163\">31</sup>, בקרוב ממש.\n**********",[["1132","*","המאמר הוא המשך למאמר שלפניו ויצאו לאור בשעתו בקונטרס אחד, \"<i>יום השלישי שהוכפל בו כי טוב</i>,<i> ז' מנ\"א ה'תשל\"ה</i>\"."],["1133","1","ישעי' א, כז."],["1134","2","לקו\"ת ר\"פ דברים."],["1135","3","אוה\"ת דברים ע' לה. ד\"ה ציון במשפט תפדה (קה\"ת תשט\"ו. תש\"ל – ע' 14. אוה\"ת דברים ח\"ו ע' ב'קעט)."],["1136","4","וישב מ, יג – כן הוא בלקו\"ת (כבדפוסים הראשונים וכו' דהתרגום – ולא \"קדמאה\")."],["1137","5","דער\"ח מנ\"א, תשל\"ה (לעיל ע' קכה ואילך)."],["1138","6","ע' צו."],["1139","7","\"כי ציון בחשבון יוסף שהוא בחי' צ\"ע\" (אוה\"ת נ\"ך שם. וכ\"ה גם באוה\"ת דברים ריש ע' לב (בהגהות הצ\"צ לד\"ה ציון שבלקו\"ת שם))."],["1140","8","בפירוש הראשון שבאוה\"ת נ\"ך שם (וכ\"ה גם באוה\"ת דברים שם) מפרש \"ושבי' הם בעלי תשובה\", בעלי תשובה סתם; אבל לפירוש השני – \"ושבי'\" היינו מעלה נוספת בציון (שלפנ\"ז) בצדיקים, לאתבא <i>צדיקייא</i> בתיובתא."],["1141","9","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381094\" data-slug=\"likkutei-torah\" data-id=\"4001381094\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. וראה זח\"ג קנג, ב."],["1142","10","ד\"ה וידבר אלקים אכה\"ד תרצ\"ט (השני) בשם הרמ\"ז. וראה ל\"ת (להאריז\"ל) בראשית עה\"פ ויתהלך חנוך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380109\" data-slug=\"likkutei-torah\" data-id=\"4001380109\">לקו\"ת צו (ח, ב</a> ואילך). שם סוף שה\"ש. וש\"נ."],["1143","11","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א נה, ב</a>. ובכ\"מ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380598\" data-slug=\"likkutei-torah\" data-id=\"4001380598\">לקו\"ת בלק ע, א</a>. ואמ\"ב שער הק\"ש פ\"ח (ובלקו\"ת שם ואמ\"ב שם מובא זה לענין <i>יחידה</i>)."],["1144","12","קהלת ד, ח."],["1145","13","מאמר זה נאמר ביום ד' מנ\"א – ערב יום ההילולא של האריז\"ל."],["1146","14","הקדמת תקו\"ז – פתח אלי'."],["1147","15","ראה לקו\"ש ח\"ג ע' 782. ועוד."],["1148","16","אגה\"ק ס\"ך (קלא, א). לקו\"ת עקב יז, ג וש\"נ למ\"ח. וראה גם ד\"ה שימני כחותם (בלקו\"ת שה\"ש, סדור שער התפלין, אמ\"ב שם). אוה\"ת ר\"פ ויגש."],["1149","17","אוה\"ת שם. ד\"ה ועבדי דוד תרצ\"ט (סה\"מ תרצ\"ט ע' 193)."],["1150","18","קדושין מ, ב. וש\"נ."],["1151","19","תו\"א ר\"פ ויגש. תו\"ח ואוה\"ת שם. ועוד."],["1152","20","נעתק ברשימות הצ\"צ לאיכה ע' 45 בשוה\"ג."],["1153","21","שופטים טז, כא. תמיד כח, ב. רמב\"ם הל' ביהב\"ח פ\"א ה\"ט. חינוך מצוה תצב."],["1154","22","יחזקאל לז, יט. כד-כה."],["1155","23","כן הוא בתו\"ח ועוד, אבל ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370199\" data-slug=\"torah-or\" data-id=\"3901370199\">תו\"א (מד, סע\"א</a>): קח כו' עד ועבדי דוד מלך עליהם. וצ\"ע שזה כבר הי', משא\"כ \"נשיא להם <i>לעולם</i>\"."],["1156","24","וכמש\"נ ויעש דוד שם. וראה אגה\"ק ס\"ה."],["1157","25","ראה ל\"ת וס' הלקוטים סוף ש\"א. אוה\"ת בראשית (יא ואילך), סוף המשך והחרים תרל\"א. אוה\"ת שם ע' תתשמא. ועוד. וראה לקוטי לוי יצחק אגרות-קודש ע' רעז."],["1158","26","מו\"ק ט, סע\"א ואילך. רמב\"ם הל' ת\"ת פ\"ג ה\"ד. הל' ת\"ת לאדה\"ז פ\"ד ס\"ג-ד. וראה ד\"ה יביאו לבוש מלכות (שבתו\"א ושערי אורה) בתחילתו."],["1159","27","סהמ\"צ להצ\"צ קע, א."],["1160","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1161","29","סי' ט. וראה לעיל ס\"ז."],["1162","30","יל\"ש לתהלים כה (רמז תשב). ירושלמי מכות פ\"ב ה\"ו (אבל שם ליתא \"שאלו לתורה כו'\"). וראה ווי העמודים (לבנו דהשל\"ה) פכ\"א ע' לא. ד\"ה טוב וישר, תרס\"ד (סה\"מ תרס\"ד (הוצאת תשנ\"ד) ע' קא ואילך)."],["1163","31","רמב\"ם הל' תשובה פ\"ז ה\"ה."]]],[1500390017,"<h3>בס\"ד. ש\"פ דברים, שבת חזון, ד' מנחם-אב ה'תשל\"ו<sup data-n=\"1164\">*</sup></h3>\n<b>ציון</b> במשפט תפדה ושבי' בצדקה<sup data-n=\"1165\">1</sup>, ומביא אדמו\"ר הזקן בלקו\"ת ד\"ה זה<sup data-n=\"1166\">2</sup> בתחלתו מ\"ש<sup data-n=\"1167\">3</sup> והיו הדברים האלה אשר אנכי מצוך היום, שזה קאי על כל יום, כי בכל יום יהיו בעיניך כחדשים<sup data-n=\"1168\">4</sup>. ומבאר<sup data-n=\"1169\">5</sup>, שבכדי לבוא לזה (שבכל יום יהיו בעיניך כחדשים), הוא ע\"י ההתבוננות בפסוק זה גופא – והיו הדברים האלה אשר אנכי מצוך היום. דהתהוות כל העולמות היא ממדת המלכות שהיא רק הארה בלבד, וע\"י קיום המצוות בעוה\"ז הוא המשכת העצמות. דזהו אשר <i>אנכי</i> מצוך היום, אנכי מי שאנכי<sup data-n=\"1170\">6</sup>. ולכן יפה שעה אחת בתשובה ומעשים טובים בעולם הזה מכל חיי העולם הבא<sup data-n=\"1171\">7</sup>, כי עולם הבא הוא שנהנין מזיו השכינה<sup data-n=\"1172\">8</sup>, זיו בלבד, וע\"י תשובה ומעשים טובים בעוה\"ז הוא המשכת העצמות<sup data-n=\"1173\">9</sup>. וזהו אשר אנכי מצוך היום, היום דוקא, היום לעשותם ולמחר לקבל שכרם<sup data-n=\"1174\">10</sup>, דשכר המצוות שבעוה\"ב (למחר) הוא רק זיו, וע\"י קיום המצוות בעוה\"ז, היום לעשותם, ממשיכים העצמות. וע\"י ההתבוננות בהענין דאנכי מצוך היום, שע\"י קיום המצוות היום (בעוה\"ז) נמשך העצמות (אנכי), עי\"ז יהיו אצלו המצוות באופן דהיום, שבכל יום יהיו בעיניו כחדשים ממש. וממשיך בהמאמר<sup data-n=\"1175\">11</sup>, דכל זה הוא כפי שצריך להיות, אבל כשאינו כן, והמרירות והשמחה שלו הם מעניני עוה\"ז, אזי, הניצוץ אלקי שבו הוא בגלות בנפשו הבהמית, כרחל לפני גוזזי' נאלמה<sup data-n=\"1176\">12</sup>, ועל זה כתיב ציון במשפט תפדה גו' (כדלקמן סעיף ט).\n<b>וצריך</b> להבין, דלכאורה, גם כשהמצוות הם כמו דיוטגמא ישנה<sup data-n=\"1177\">13</sup> בעיניו, אפשר שיקיים אותם בחיות<sup data-n=\"1178\">14</sup>, ועד, שזה (קיום התומ\"צ) יהי' אצלו העיקר. וממ\"שבהמאמר אבל כשאינו כן כו', משמע לכאורה<sup data-n=\"1179\">15</sup> דכאשר המצוות אינם כחדשים בעיניו אז ודאי שהמרירות והשמחה שלו הם מעניני עוה\"ז. וגם צריך להבין מ\"ש בהמאמר שבכדי לבוא לבכל יום יהיו בעיניך כחדשים הוא ע\"י ההתבוננות בהענין דאנכי מצוך היום, שע\"י קיום המצוות בעוה\"ז (היום) הוא המשכת העצמות (אנכי), שהוא נעלה הרבה יותר משכר המצוות בעוה\"ב שהוא רק זיו, דלכאורה, מכיון שההנאה (והתענוג) מזיו השכינה בעוה\"ב הוא תענוג גדול ביותר<sup data-n=\"1180\">16</sup> [ובפרט שהכוונה בעוה\"ב כאן היא לא רק לג\"ע אלא גם לעולם התחי'<sup data-n=\"1181\">17</sup>, שהגילוי שיהי' בעולם התחי' הוא נעלה הרבה יותר מהגילוי דג\"ע<sup data-n=\"1182\">18</sup>], הרי גם ע\"י ההתבוננות בהעילוי דשכר המצוות (בעוה\"ב) יהי' לו חיות גדול בקיום המצוות, ובהמאמר אומר, שבכדי שהמצוות יהיו בעיניו כחדשים ולא כדיוטגמא ישנה צ\"ל ההתבוננות דוקא בהענין דאנכי מצוך היום, המעלה דהיום לעשותם שלמעלה מלמחר לקבל שכרם.\nב) <b>ויובן</b> זה בהקדים שבכדי שבכל יום יהיו בעיניך כחדשים הוא ע\"י גילוי בחינה שלמעלה משינויים. ומכיון שגדר עולם הוא (מקום ו)זמן<sup data-n=\"1183\">19</sup>, שזמן הוא שינוי, לכן, בכדי שבכל יום יהיו בעיניך כחדשים הוא ע\"י הגילוי דאוא\"ס שלמעלה מהתלבשות בעולמות, אור הסובב<sup data-n=\"1184\">20</sup>. דהאור המתלבש בעולמות, אור הממלא, הוא בא בציור מוגבל להחיות את הנבראים לפי ערכם. וכמרז\"ל<sup data-n=\"1185\">21</sup> מה הנפש ממלאה את הגוף כך הקב\"ה ממלא את עולמו, דכמו שחיות הנפש המתלבש בהגוף הוא לפי אופן אברי הגוף, דבכל אבר החיות הוא לפי ערכו, עד\"ז הוא בהחיות דהעולם שנמשך בו אור הממלא (זה שהקב\"ה ממלא את עולמו), שהחיות דכל נברא הוא לפי ערכו<sup data-n=\"1186\">22</sup>. ומזה מובן במכ\"ש<sup data-n=\"1187\">23</sup> בנוגע לגדר העולם בכללותו (מקום וזמן), שמצד אור הממלא, א\"א שיהי' בהעולם ענין שלמעלה מזמן ומקום. והגם שגם האור שמתלבש בעולם אינו נתפס בגדרי העולם, וכמ\"ש<sup data-n=\"1188\">24</sup> אין קדוש כהוי' ואיתא בזהר<sup data-n=\"1189\">25</sup> כמה קדישין אינון ולית קדוש כהוי', דהחידוש בקדוש הוי' הוא שהגם שהוא מלובש<sup data-n=\"1190\">26</sup>בהנבראים<sup data-n=\"1191\">27</sup> ומחי' אותם (בפנימיותם) מ\"מ הוא קדוש ומובדל מהם ואינו נתפס בהם [וי\"ל דזהו פירוש הוא מקומו של עולם ואין העולם מקומו<sup data-n=\"1192\">28</sup>, דהוא מקומו של עולם קאי על אור הממלא<sup data-n=\"1193\">29</sup>, שהוא מחי' את העולם, ואעפ\"כ אין העולם מקומו, שאינו נתפס בזה<sup data-n=\"1194\">30</sup>], הנה זה שהאור נשאר בפשיטותו (גם לאחרי שמתלבש בהעולם) הוא בנוגע להאור, אבל בנוגע להעולם, החיות דהעולם המתלבש הוא מדוד ומוגבל בגדרי העולם. ולכן, בכדי שבכל יום יהיו בעיניך כחדשים (ענין שלמעלה מזמן) הוא ע\"י גילוי אור הסובב.\nג) <b>והנה</b> מכיון שגדר העולם הוא מקום וזמן, מובן, דזה שע\"י גילוי אור הסובב נמשך בעולם ענין שלמעלה מזמן ומקום הוא שגדרי העולם <i>בטלים</i> מפני הגילוי דאור הבל\"ג שלמעלה מהעולם. וע\"ד הרצון (דרצון הוא משל על סובב), דזה שהרצון מושל ושולט על האברים שיעשו היפך טבעם הוא מפני שהם בטלים להרצון<sup data-n=\"1195\">31</sup>. ומכיון שהענין דבכל יום יהיו בעיניך כחדשים הוא שיהי' לו חיות בהמצוות (כבדברים חדשים), דחיות הוא פנימי, לכן, הענין דלמעלה מהזמן שמאיר בהאדם (שעי\"ז יהיו בעיניך כחדשים) צריך להיות אצלו בפנימיות. ולכן, הנתינת כח על זה שבכל יום יהיו בעיניך כחדשים הוא זה שאנכי מצוך היום, אנכי מי שאנכי, שלמעלה גם מסובב. והענין הוא, דאור הבל\"ג (השרש דאור הסובב), הוא מוגדר בהגדר דבל\"ג, ולכן, זה שא\"ס להתפשטותו והוא נמצא בגילוי בכל מקום, גם בעוה\"ז הגשמי<sup data-n=\"1196\">32</sup>, הוא מצד זה שהאור הוא א\"ס, אבל אין זה שייך להעולם. ושני אופנים בזה. או שבעולם אינו נרגש כלל האור<sup data-n=\"1196\">32</sup>, או שנרגש בו האור, שעי\"ז נמשך בו ענין שלמעלה מזמן ומקום, אבל הוא באופן שגדר העולם בטל מפני האור. ובכדי שהגילוי דאור הבל\"ג בעולם יהי' בפנימיותו, הוא ע\"י העצמות<sup data-n=\"1197\">33</sup> שאינו מוגדר בשום גדר, לא בגדר הגבול ולא בגדר הבל\"ג. ולכן, ע\"י גילוי כח העצמות, נעשה החיבור דבל\"ג וגבול, יחוד סובב וממלא, והגילוי דלמעלה מהזמן (שנמשך מהסובב) בעולם (שחיותו הוא מאור הממלא) הוא בפנימיותו.\nד) <b>ויש</b> להוסיף, דזה שהענין דבכל יום יהיו בעיניך כחדשים הוא ע\"י יחוד סובב וממלא הוא לא רק בכדי שהענין דלמעלה מהזמן (סובב) יורגש בהאדם בפנימיות, אלא גם מפני שבהענין דבכל יום כחדשים עצמו ישנם שני ההפכיםדלמעלה מהזמן וזמן. שהרי הענין דחדשים (והיוקר והחביבות שבזה) הוא השינוי<sup data-n=\"1198\">34</sup>, שבתחלה לא הי' הדבר ונתחדש רק עכשיו. וזה שבכל יום הם בעיניו כחדשים הוא שהחידוש (השינוי) הוא באופן תמידי שאינו משתנה. ונמצא דזה שהענין דבכל יום כחדשים הוא ע\"י יחוד סובב וממלא הוא לא רק שהגילוי דסובב (דלמעלה מהזמן) נרגש אצלו בפנימיות (שעי\"ז יש לו חיות בהמצוות כבדברים חדשים), אלא יתירה מזו, שהזמן עצמו (שמצד אור הממלא) הוא באופן דלמעלה מזמן ושינוי (גילוי הסובב).\n<b>ויש</b> לומר, דזה שקיום המצוות צ\"ל באופן של כחדשים ממש הוא לא רק בכדי שעי\"ז יהי' קיום התומ\"צ ביותר חיות, אלא ש(גם) ענין זה עצמו (דבכל יום יהיו בעיניך כחדשים) נוגע לקיום המצוות. כי ענין המצוות הוא שעל ידם נעשה יחוד קוב\"ה ושכינתי'<sup data-n=\"1199\">35</sup>, יחוד סובב וממלא<sup data-n=\"1199\">35</sup>. וכיון שעבודת האדם (אתערותא דלתתא) שעל ידה נעשית ההמשכה (אתערותא דלעילא) צריכה להיות מעין ההמשכה, לכן כשקיום המצוות דהאדם הוא באופן שבכל יום הם בעיניו כחדשים, חיבור דזמן עם למעלה מהזמן, עי\"ז מיתוסף בגילוי היחוד דסובב וממלא שנעשה ע\"י המצוות.\nה) <b>והנה</b> שני הענינים דסובב וממלא הם שני השמות דהוי' ואלקים. וכמבואר בכ\"מ<sup data-n=\"1200\">36</sup> דשם אלקים הוא לא רק המגן ונרתק שמעלים ומסתיר על האור דשם הוי', אלא שגם האור דשם הוי' כמו שנמשך ומתצמצם ע\"י שם אלקים להיות מקור לנבראים, שבכללות הוא אור הממלא, נקרא אלקים. וע\"פ הידוע<sup data-n=\"1201\">37</sup> דזה שהגוף מעלים על הנפש הוא כי שרש הנפש הוא מהוי' ושרש הגוף הוא מאלקים<sup data-n=\"1202\">38</sup>, ולכן כמו שאלקים מעלים על הוי' כן הגוף מעלים על הנפש, יש לומר, שעד\"ז הוא גם בהענין דסובב וממלא [שגם אור הממלא נק' אלקים, כנ\"ל], שבכדי שהאדם ידע וירגיש שהעיקר הוא עניני הנשמה ועניני הגוף הם רק טפל, הוא ע\"י יחוד סובב וממלא. דבאור הממלא (כמו שהוא מצד עצמו) להיותו מקור לנבראים והנבראים תופסים מקום לגבי', יש תפיסת מקום לעניני הגוף, וע\"י היחוד דסובב וממלא, שגם בהאור כמו שנעשה מקור לעולמות מאיר הגילוי דאוא\"ס שלמעלה מעולמות, דכולא קמי' כלא חשיב, עי\"ז ישנה ההכרה שעניני הגוף הם רק בשביל הנשמה. ועפ\"ז יש לבאר מ\"ש בלקו\"ת דכאשר לא ישנו הענין דבכל יום כחדשים אזי המרירות והתענוג שלו הם מעניני עוה\"ז, כי בכדי שיהי' היחוד דסובב וממלא, שעי\"ז עניני עוה\"ז אינם תופסים מקום אצלו, הוא ע\"י שקיום המצוות שלו הוא באופן דבכל יום כחדשים.\nו) <b>ועפ\"ז</b> יש לבאר השייכות דגלות לשכחה, כמ\"ש<sup data-n=\"1203\">39</sup> למה לנצח תשכחנו גו', כי סיבת השכחה היא שהידיעה שהיתה אצלו מקודם היתה מוגבלת, ולכןבמשך הזמן היא נפסקת<sup data-n=\"1204\">40</sup>. ומזה מובן בענין הזכרון והשכחה (כביכול) למעלה, דענין הזכרון הוא בסובב, דכיון שהוא בל\"ג, אין שייך שם הפסק, וענין השכחה הוא במלכות, דמלכות היא שרש הנבראים, ממלא<sup data-n=\"1205\">41</sup>. ולכן, כשקיום התומ\"צ דהאדם הוא באופן דבכל יום הם כחדשים, שעי\"ז מאיר הגילוי דאור הבל\"ג גם באור המוגבל, אין שייך ענין השכחה, אבל כאשר קיום התומ\"צ דהאדם הוא בהגבלה, שאז, כשמקיים אותה המצוה בפעם שני' ושלישית אין לו אותו החיות כמו שהי' אצלו בפעם הראשונה, שעי\"ז גורם גם למעלה שבאור המוגבל לא יהי' הגילוי דאור הבל\"ג, מזה נמשך ענין השכחה. וכמו שבאדם, כשקיום התומ\"צ שלו הוא באופן דהגבלה, משתלשל מזה שהתענוג שלו הוא בעניני עוה\"ז, שזה (התענוג בעניני עוה\"ז, גם בתאוות היתר) הוא היפך הקדושה, עד\"ז הוא למעלה, דע\"י שז\"א (סובב) מסתלק, קוב\"ה סליק לעילא<sup data-n=\"1206\">42</sup>, ונשאר רק המלכות (ממלא), זה גורם ירידת המלכות להחיות הקליפות, גלות השכינה.\nז) <b>ויש</b> לקשר זה עם מ\"ש בהפטרה דשבת חזון<sup data-n=\"1207\">43</sup> ידע שור קונהו גו' ישראל לא ידע עמי לא התבונן, ופירש האריז\"ל<sup data-n=\"1208\">44</sup> [שהיום הוא ערב יום ההילולא שלו<sup data-n=\"1209\">45</sup>], דשור קאי על העגל שעשו הערב רב במדבר, ע\"י שהשליכו הטס שכתב בו משה עלה שור בכדי להעלות ארונו של יוסף<sup data-n=\"1210\">46</sup>. ומבאר, דבטס זה הי' כתוב השם יל\"י (שם השני של השם בן ע\"ב שמות), שהוא הממונה על כח השור העליון. וזהו ידע שור קונהו גו' ישראל לא ידע גו', שהשור עצמו ידע שהוא משם קדוש, וישראל לא ידע עמי לא התבונן, לא ידעו ולא התבוננו בזה, ואמרו שהעגל עלה מעצמו ולכן טעו אחריו. וזהו שהר\"ת של ישראל לא ידע עמי לא התבונן הוא יל\"י על\"ה, שלא ידעו ולא התבוננו דזה שעל\"ה (השור) הוא ע\"י שם יל\"י, ולכן אמרו שעלה מעצמו.\n<b>ויש</b> לומר, דפירוש זה בישראל לא ידע עמי לא התבונן הוא לימוד זכות על ישראל. שהסיבה לזה שטעו אחרי העגל, היתה מפני שלא התבוננו בהענינים (השם יל\"י) שלמעלה מהעולם, היינו שגם אז עבדו את הוי', אלא שכיון שאז הי' לפני הציווי דבכל יום יהיו בעיניך כחדשים<sup data-n=\"1211\">47</sup>, לכן היתה עבודתם בהגבלה, שלכן, הגילוישהאיר להם אז הוא רק האור שמלובש בהעולם. ומזה נשתלשל שטעו אחרי העגל<sup data-n=\"1212\">48</sup>. וזהו גם שחטא העגל גרם לשבירת הלוחות שעי\"ז נעשה האפשרות דשכחת התורה<sup data-n=\"1213\">49</sup>, היינו שגם לאחרי החטא נשאר הקשר שלהם עם התורה, ורק שלימוד התורה שלאחרי שבירת הלוחות הוא בהגבלה שלכן שייך בזה הפסק (שכחה). ועי\"ז נעשה אפשרות שתהי' אומה ולשון שולטת בהם<sup data-n=\"1214\">50</sup>, כי כשהגילוי הוא רק מבחינת המלכות, יש נתינת מקום לגלות, כנ\"ל.\nח) <b>וזהו</b> מ\"ש<sup data-n=\"1215\">51</sup> זכור הוי' מה הי' לנו, ומבאר הצ\"צ<sup data-n=\"1216\">52</sup> דמה הוא שם הוי' (במילוי אלפי\"ן בגימטריא מ\"ה) ולנו הוא בגימטריא אלקים, ופירוש מה הי' לנו הוא, שהוי' נעשה בבחינת אלקים. ויש לומר, דענין מה הי' לנו בעבודת האדם הוא, דהוי' הוא למעלה מהטבע ואלקים בגימטריא הטבע<sup data-n=\"1217\">53</sup>, שגם כשישנה לאדם הצלחה שלמעלה מהטבע הוא חושב שזה טבע. ויתירה מזו, שלפעמים, ההצלחה שלמעלה מהטבע גורמת לו לחשוב שכחו ועוצם ידו עשה לו את החיל הזה<sup data-n=\"1218\">54</sup> [וע\"ד שהי' בעגל, דזה שע\"י השם יל\"י נעשה עליית השור (ענין שלמעלה מהטבע) הביא אותם לחשוב שעלה מעצמו].\n<b>והעצה</b> לזה הוא זכור הוי', שהעבודה תהי' באופן דזכרון, למעלה מהגבלה (בכל יום יהיו בעיניך כחדשים), שעי\"ז מאיר הגילוי דהוי', אור הסובב גם שלמעלה מהתלבשות. ויש לקשר זה עם פירוש הבעש\"ט עה\"פ<sup data-n=\"1219\">55</sup>, דמה הי' לנו הוא גילוי מ\"ה דהנשמה, כי מ\"ה דהנשמה הוא עצם הנשמה שלמעלה מהתלבשות, שקשורה עם הוי' שלמעלה מהתלבשות בעולם, ועי\"ז באים להעבודה דזכור, עבודה שלמעלה מהגבלה.\nט) <b>וזהו</b><sup data-n=\"1220\">56</sup> ציון במשפט תפדה ושבי' בצדקה, שהם ב' דרגות בנשמה. ציון היא דרגת הנשמה שלמעלה מהתלבשות בגוף (מ\"ה דנשמה), דבחינה זו אין שייך שתהי' בשבי' בנפש הבהמית, שהמרירות והשמחה שלה יהיו מעניני עוה\"ז, ורק שהיא בגלות, שאינה מאירה בגילוי (בהנשמה שבגוף). ושבי' היא דרגת הנשמה שבהתלבשות, דבחינה זו שייך שתהי' בשבי' בנה\"ב, שהמרירות והשמחה שלה הםמעניני עוה\"ז. ויש לומר, שהוא ע\"ד המבואר<sup data-n=\"1221\">57</sup> בפירוש הכתוב<sup data-n=\"1222\">58</sup> ותאמר ציון עזבני הוי' ואד' שכחני, דשכחה הוא שיש דבר המשכח ולא רק העדר הזכרון. וזהו עזבני הוי' ואד' שכחני, דבהוי' שהוא אור הסובב שלמעלה מהתלבשות בעולמות אין שייך ענין השכחה ח\"ו ורק ענין העזיבה, והוא שבגלותא קוב\"ה סליק לעילא ואינו מאיר בגילוי למטה (ע\"ד הגלות בבחינת ציון, שאינה מאירה בהנשמה שבגוף<sup data-n=\"1223\">59</sup>), ואד' (מלכות<sup data-n=\"1224\">60</sup>) שבכללות הוא אור הממלא, שייך בו גם ענין השכחה, ירידת המלכות להחיות הקליפות (ע\"ד השבי' בדרגת הנשמה שבבחינת התלבשות<sup data-n=\"1223\">59</sup>, שהמרירות והשמחה שלה יכולים להיות מעניני עוה\"ז). וזהו&lt;56&gt; ציון במשפט תפדה ושבי' בצדקה, שהפדי' דבחינת ציון מהדברים המכסים עלי' ומונעים הגילוי שלה בהנשמה שבגוף, הוא ע\"י התורה [משפט הוא הלכות התורה, כמו שמתרגם ע\"פ<sup data-n=\"1225\">61</sup> כמשפט הראשון כהלכתא קדמייתא], כי התורה היא אור (תורה אור<sup data-n=\"1226\">62</sup>) ולכן על ידה נעשה הגילוי דבחינת ציון. והפדי' דדרגת הנשמה שבהתלבשות שהיא בשבי' בנה\"ב (ושבי') הוא בצדקה, היינו כללות המצוות שנקראו צדקה<sup data-n=\"1227\">63</sup>, ובפרט ע\"י צדקה כפשוטה<sup data-n=\"1228\">64</sup>, דבצדקה כתיב<sup data-n=\"1229\">65</sup> רחבה מצותך מאד, שע\"י מצות צדקה נמשך הגילוי דאור הבל\"ג<sup data-n=\"1230\">66</sup>, והגילוי הוא גם בהנשמה המלובשת בגוף<sup data-n=\"1231\">67</sup>, [ועד\"ז למעלה – בספירת המלכות שנקראת בשם שכינה על שם<sup data-n=\"1232\">68</sup> שמתלבשת בתחתונים להחיותם<sup data-n=\"1231\">67</sup>], ובאופן דהתלבשות. ועי\"ז נמשך גם הגילוי דעצם הנשמה ממש, שלמעלה גם מדרגת הנשמה שלמעלה מהתלבשות, וע\"ד שנת\"ל (סעיף ג) שהיחוד דסובב וממלא הוא ע\"י גילוי כח העצמות. וכיון שגם את העולם נתן בלבם של בני האדם<sup data-n=\"1233\">69</sup>, הנה עי\"ז נמשך גם בעולם, שהגילוי דלמעלה מהטבע (שנמשך מהסובב) יהי' בגילוי גם בהטבע (שנמשך מממלא), ועי\"ז יהי' גם גילוי העצמות (שמחבר את שניהם), שעי\"ז תושלם הכוונה דדירה לו ית' בתחתונים<sup data-n=\"1234\">70</sup>, לו לעצמותו<sup data-n=\"1235\">71</sup>.\n<b>ויהי</b> רצון, שבקרוב ממש תקויים ההבטחה והיעוד ציון במשפט תפדה ושבי' בצדקה, שיעמוד<sup data-n=\"1236\">72</sup> מלך מבית דוד הוגה בתורה (משפט) ועוסק במצוות(צדקה), וילחום מלחמת ה' וינצח [די\"ל שזה שילחום מלחמת ה' הוא ע\"י העבודה<sup data-n=\"1237\">73</sup> בדרגת הנשמה המלובשת בגוף, שהעבודה בדרגא זו<sup data-n=\"1238\">74</sup> היא באופן דמלחמה עם נה\"ב], ויבנה מקדש במקומו [שעי\"ז יהי' הגילוי גם בכל העולם, דהחלונות דביהמ\"ק היו שקופים אטומים<sup data-n=\"1239\">75</sup> שמהם אורה יוצאת לכל העולם<sup data-n=\"1240\">76</sup>] ויקבץ נדחי ישראל ויתקן את העולם<sup data-n=\"1241\">77</sup> כולו לעבוד את ה', וכל זה – בקרוב ממש ובעגלא דידן.\n**********",[["1164","*","יצא לאור ב<b>קונטרס שבת חזון – תשמ\"ט</b>, \"לקראת ש\"ק פ' דברים, שבת חזון, ד' מנחם-אב . . <i>ר\"ח מנ\"א</i>,<i> ה'תשמ\"ט</i>\"."],["1165","1","ישעי' א, כז. סיום וחותם הפטורת שבת חזון."],["1166","2","ריש פרשתנו (דברים). וראה הגהות הצ\"צ לד\"ה זה – אוה\"ת דברים ע' כח ואילך."],["1167","3","ואתחנן ו, ו."],["1168","4","ראה ספרי ופרש\"י עה\"פ. שו\"ע אדה\"ז או\"ח סי' סא סעיף ב (וש\"נ). ולהעיר, דהגם שהלשון במרז\"ל זה הוא כחדשים (בכ\"ף הדמיון) – הכוונה היא שהענין ד\"כחדשים\" יהי' באמת. ולהעיר מהלשון ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">לקו\"ת שם (א, ב</a> – נעתק לקמן בפנים) \"כחדשים ממש\"."],["1169","5","בד\"ה הנ\"ל ס\"ב (א, ב)."],["1170","6","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380641\" data-slug=\"likkutei-torah\" data-id=\"4001380641\">לקו\"ת</a> שם. וראה לקו\"ת פינחס (פ, ב), ד\"אנכי מי שאנכי\" \"הוא בחי' דלא אתפס בשם ולא אתרמיז בשום אות וקוצא כלל\"."],["1171","7","אבות פ\"ד מי\"ז."],["1172","8","ברכות יז, א."],["1173","9","כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא ספ\"ד</a>."],["1174","10","עירובין כב, א. וש\"נ."],["1175","11","רפ\"ג (א, סע\"ב)."],["1176","12","לשון הכתוב – ישעי' נג, ז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380679\" data-slug=\"likkutei-torah\" data-id=\"4001380679\">לקו\"ת מסעי פח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380682\" data-slug=\"likkutei-torah\" data-id=\"4001380682\">פט, ג</a>."],["1177","13","לשון הספרי ופרש\"י שבהערה 4."],["1178","14","להעיר משו\"ע אדה\"ז שם, דכששמע דבר אחד הרבה פעמים \"אינו חביב אצלו <i>כבתחלה</i>\", היינו שגם אז הוא חביב אצלו אלא שאינו כבתחלה."],["1179","15","כי י\"ל שזהו עוד ענין."],["1180","16","ראה בארוכה סהמ\"צ להצ\"צ בתחלתו (גם) בנוגע התענוג <i>שבג\"ע</i>."],["1181","17","כמ\"ש להדיא בהגהות הצ\"צ לד\"ה זה (אוה\"ת פרשתנו ס\"ע ל ואילך)."],["1182","18","אגה\"ק סי\"ז. ספהמ\"צ להצ\"צ יד, ב. ועוד. וראה ד\"ה לה\"ע תחיית המתים דש\"פ אחרי ה'תשמ\"ו (לעיל ח\"ג ע' רכא ואילך). וש\"נ."],["1183","19","שעהיוה\"א פ\"ז (פב, א)."],["1184","20","כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940237\" data-slug=\"or-hatorah-hb\" data-id=\"8159940237\">אוה\"ת בחוקותי ע' תרמג</a>. תרנו. אלא שהביאור שם הוא באו\"א."],["1185","21","מדרש תהלים מזמור קג. ובברכות י, א: מה הקב\"ה מלא כל העולם אף נשמה מלאה את כל הגוף."],["1186","22","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת אמור לא, ב</a>. ובכ\"מ."],["1187","23","להעיר מזה שגם חיות הכללי שאינו מתצמצם לפי אופן אברי הגוף, מ\"מ, בנוגע הגדר דכללות הגוף – הוא נעשה חיות בשרי (ראה סה\"מ עת\"ר ע' יב ואילך. ה'תש\"ח ע' 24 ואילך. ועוד)."],["1188","24","שמואל-א ב, ב."],["1189","25","ח\"ג מד, א."],["1190","26","ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, ב</a> (הובא בהמשך תער\"ב ח\"ב פשצ\"ז ע' תתיח) \"ואע\"פ שמהוה את הכל אעפ\"כ הוא קדוש ומובדל מהם בבחי' <i>סוכ\"ע</i>\", אבל בהמשך תער\"ב שם (וכ\"ה בסה\"מ תרס\"ד ע' קכח. המשך תרס\"ו ע' תקב ואילך. ובכ\"מ) שעיקר החידוש ד\"אין קדוש כהוי'\" הוא באור הקו שבא בהתלבשות."],["1191","27","בהמשך תרס\"ו שם מדובר בנוגע אור הקו שמתלבש בכלים. אבל בסה\"מ תרס\"ד והמשך תער\"ב שם שכ\"ה גם בנוגע להארת הקו שמתלבשת בהנבראים."],["1192","28","ב\"ר פס\"ח, ט."],["1193","29","ראה ספר החקירה להצ\"צ ערך מקום (עה, סע\"ב ואילך) ובכ\"מ, דלפירוש אדה\"ז – מקום הוא בחי' ממכ\"ע. ושם (עו, סע\"א באופן הא'), שלפי פירוש זה – גם \"<i>הוא</i> מקומו של עולם\" קאי על ממלא."],["1194","30","וע\"פ מ\"ש בלקו\"ת שה\"ש שבהערה 26, דענין אין קדוש כהוי' הוא (גם) באור הסובב, שעם היותו מהוה מ\"מ הוא קדוש ומובדל – יש לבאר החידוש ד\"אין העולם מקומו\" (גם) להפירוש שקאי על סובב."],["1195","31","ראה בארוכה אוה\"ת נשא ע' רכח ואילך. המשך תער\"ב ח\"א פנ\"א ואילך. ובכ\"מ."],["1196","32","ראה המשך תרס\"ו ע' תקא. וראה ד\"ה וחזקת והיית לאיש תשכ\"ח ס\"ג (לעיל ע' קה). <i>וש\"נ</i>."],["1197","33","ראה עד\"ז המשך תרס\"ו ע' נה."],["1198","34","להעיר גם מאוה\"ת ואתחנן ע' קי, שהענין דבכ\"י כחדשים הוא בבחי' ירח, אתר דמשתני."],["1199","35","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a> ואילך). המשך תרס\"ו שם. ובכ\"מ."],["1200","36","המשך תרס\"ו ע' רכב. ובכ\"מ. וראה גם סהמ\"צ להצ\"צ סב, א דענין יחוד הוי' ואלקים הוא היחוד דסובב וממלא."],["1201","37","סהמ\"צ להצ\"צ ה, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650010\" data-slug=\"or-hatorah-hb\" data-id=\"8316650010\">אוה\"ת נ\"ך ח\"ב ע' תשלט</a>."],["1202","38","שעהיוה\"א פ\"ו (פא, רע\"א)."],["1203","39","איכה ה, כ."],["1204","40","ראה אוה\"ת נ\"ך ח\"ב ע' א'פה, ששכחה היא בדוגמת נהרות המכזבים."],["1205","41","ראה בכ\"ז אוה\"ת שם. וראה גם ס' הליקוטים – דא\"ח צ\"צ ערך שכחה בתחלתו. וש\"נ."],["1206","42","ראה זהר ח\"א רי, א. ח\"ג כ, ב. וראה סידור (עם דא\"ח) נח, ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650323\" data-slug=\"or-hatorah-hb\" data-id=\"8316650323\">אוה\"ת נ\"ך כרך ב ע' א'נ</a>. שם ע' א'נח. סה\"ל שם ערך גלות ס\"ג (ע' שכג ואילך). וש\"נ."],["1207","43","ישעי' א, ג."],["1208","44","בשער הפסוקים עה\"פ. ועד\"ז הוא בל\"ת להאריז\"ל עה\"פ. ל\"ת פ' תשא. ועוד."],["1209","45","ה' מנחם-אב ה'של\"ב (שה\"ג להחיד\"א בערכו. ובכ\"מ)."],["1210","46","פדר\"א פמ\"ה. תנחומא תשא יט (וראה ג\"כ שם בשלח ב). פרש\"י עה\"פ תשא לב, ד. ועוד."],["1211","47","דהפסוק והיו הדברים האלה אשר אנכי מצוך היום, שממנו למדים שבכ\"י יהיו בעיניך כחדשים – נאמר בפ' ואתחנן.\nבפרש\"י יתרו יט, א \"מהו ביום הזה שיהיו דברי תורה חדשים עליך כאילו היום ניתנו\", אבל ביתרו שם נאמר זה בדרך <i>סיפור</i>. ועצ\"ע."],["1212","48","להעיר מד\"ה וידעת תרנ\"ז (סה\"מ תרנ\"ז ע' נה ואילך) שבכדי שלא יהי' נתינת מקום לע\"ז צ\"ל הידיעה שהוי' ואלקים כולא חד."],["1213","49","כמארז\"ל (עירובין נד, א) אלמלי לא נשתברו לוחות הראשונות לא נשתכחה תורה מישראל."],["1214","50","עירובין שם."],["1215","51","איכה ה, א."],["1216","52","אוה\"ת נ\"ך ח\"ב עה\"פ (ע' א'פו)."],["1217","53","פרדס שער יב (שער הנתיבות) פ\"ב. ר\"ח שער התשובה פ\"ו ד\"ה והמרגיל (קכא, ב). שעהיוה\"א רפ\"ו. וראה בהנסמן לקמן ע' רסג הערה 76."],["1218","54","ראה עקב ח, יז."],["1219","55","סה\"מ אידיש ע' 212."],["1220","56","בהבא לקמן – ראה לקו\"ת ד\"ה זה ס\"ג (א, סע\"ב ואילך). וראה ד\"ה זה תשל\"ה (לעיל ע' קכה ואילך) <i>וש\"נ</i>."],["1221","57","המשך תרס\"ו ע' רמג ואילך. וראה שם ע' רמה. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450514\" data-slug=\"or-hatorah-hb\" data-id=\"8316450514\">אוה\"ת עקב ע' תקיד</a> ואילך."],["1222","58","ישעי' מט, יד."],["1223","59","ראה המשך תרס\"ו שם ע' רמו."],["1224","60","שעהיוה\"א רפ\"ז."],["1225","61","וישב מ, יג."],["1226","62","משלי ו, כג."],["1227","63","לקו\"ת פרשתנו ד\"ה ברבות פ' עקב (א, ד) בענין ושבי' בצדקה. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פרק לז (מח, ב</a>)."],["1228","64","כ\"ה בלקו\"ת ד\"ה ציון בסופו (א, ג)."],["1229","65","תהלים קיט, צו."],["1230","66","אגה\"ק סי\"ז."],["1231","67","אגה\"ק סוס\"ח."],["1232","68","ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a>)."],["1233","69","קהלת ג, יא. וראה לקו\"ת במדבר ה, ריש ע\"ב."],["1234","70","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["1235","71","המשך תרס\"ו ס\"ע ג. שם ע' תמה. ובכ\"מ. – נסמנו לעיל ח\"ב ע' שח הערה 32."],["1236","72","רמב\"ם הל' מלכים ומלחמותיהן והלכות מלך המשיח ספי\"א."],["1237","73","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a> שכל הענינים דלעת\"ל תלויים במעשינו ועבודתינו."],["1238","74","משא\"כ ע\"י העבודה שמצד דרגת הנשמה שלמעלה מהתלבשות בטלים <i>במילא</i> הרצונות דנה\"ב – ראה בארוכה ד\"ה פדה בשלום תשל\"ט ס\"ג (לעיל ח\"ב ע' מ ואילך). וש\"נ."],["1239","75","מלכים-א ו, ד."],["1240","76","ויק\"ר פל\"א, ז."],["1241","77","נוסף על הגילוי בעולם שע\"י ביהמ\"ק."]]],[1500390018,"<h3>בס\"ד. ש\"פ דברים, שבת חזון, ערב תשעה באב ה'תשמ\"א<sup data-n=\"1242\">*</sup></h3>\n<b>ציון</b> במשפט תפדה ושבי' בצדקה<sup data-n=\"1243\">1</sup>, ומדייק אדמו\"ר (מהורש\"ב) נ\"ע במאמרו ד\"ה זה דשנת עדר\"ת<sup data-n=\"1244\">2</sup>, הרי הכוונה בציון כאן היא לא על עיר ציון<sup data-n=\"1245\">3</sup> [בפרט<sup data-n=\"1246\">4</sup>] אלא על [כללות<sup data-n=\"1246\">4</sup>] ישראל, ולמה אומר ציון. וגם מדייק מ\"ש ושבי' גו', מי הם שבי'. [ויש לומר, שגם דיוק זה (מי הם שבי') הוא ע\"פ מה שאומר לפנ\"ז שהכוונה בציון כאן היא על כללות ישראל. דיש מפרשים<sup data-n=\"1247\">5</sup> שציון קאי על עיר ציון ושבי' קאי על ישראל. אבל להפירוש (שבהמאמר) שציון קאי על ישראל, מה הם שני הסוגים דציון ושבי']. וגם מהו\"ע שפדיית ציון תהי' במשפט והפדי' של שבי' בצדקה.\nב) <b>ונקודת</b> הביאור (ע\"פ המבואר ברשימות הצ\"צ עה\"פ<sup data-n=\"1248\">6</sup> ובמאמר הנ\"ל<sup data-n=\"1249\">7</sup>), דציון קאי על ישראל העוסקים בתורה ומצוות, ונק' בשם ציון לפי שהם מצויינים בתומ\"צ. [וכדאיתא בירושלמי<sup data-n=\"1250\">8</sup> עה\"פ<sup data-n=\"1251\">9</sup> ואשים דברי בפיך ובצל ידי כסיתיך לנטוע שמים וליסוד ארץ ולאמר לציון עמי אתה, חזרנו על כל המקרא ולא מצאנו שנקראו ישראל ציון אלא זה (שנאמר) ולאמר לציון עמי אתה. וידוע הביאור בזה<sup data-n=\"1252\">10</sup>, דבפסוק זה מדבר בג' הדברים שעליהם העולם עומד, תורה עבודה וגמ\"ח<sup data-n=\"1253\">11</sup>. ואשים דברי בפיך זו תורה, ובצל ידי כסיתיך זו גמ\"ח, לנטוע שמים וליסוד ארץ אלו הקרבנות (כדאיתא בירושלמי שם). וזהו לא מצאנו שנקראו ישראל ציון אלא זה, כי זה שישראל נק' בשם ציון הוא ע\"י שעוסקים בתורה עבודה וגמ\"ח, שהם כללות כלהתומ\"צ]. ושבי' הם אלו שאינם עוסקים בתורה<sup data-n=\"1254\">12</sup>, שהם בשבי' ממש [ושבי' מלשון שבי'<sup data-n=\"1255\">13</sup>] בהגוף ונה\"ב. וזהו ציון במשפט תפדה ושבי' בצדקה, שהפדי' של העוסקים בתורה היא במשפט, ע\"פ שורת הדין, משא\"כ הפדי' של שבי' היא בתורת צדקה. והגם שגם פדייתם של אלו שהם בשבי' בהגוף ונה\"ב תהי' ע\"י התשובה, דאין ישראל נגאלין אלא בתשובה<sup data-n=\"1256\">14</sup> והבטיחה תורה שסוף ישראל לעשות תשובה בסוף גלותן ו(עי\"ז) מיד הן נגאלין<sup data-n=\"1257\">15</sup> [ויש לומר, דזהו הקשר של הפירוש ושבי' מלשון שבי' עם הפירוש דושבי' הוא עושי תשובה (ושבי' מלשון תשובה<sup data-n=\"1258\">16</sup>), כי פדיית שבי' מלשון שבי' הוא ע\"י שיעשו תשובה], הרי זה שתשובה מכפרת אינו ע\"פ משפט, אלא חסד וצדקה דהקב\"ה<sup data-n=\"1259\">17</sup>. אלא שאעפ\"כ, הפדי' דשבי' היא למעלה מהפדי' דציון, כי ענין המשפט הוא מדידה והגבלה, משא\"כ צדקה היא למעלה מהגבלה. וכמבואר בהמאמר&lt;7&gt;, שמשפט הוא האור שבגדר הכלים, וצדקה הוא האור שבהבדלה שבא רק באופן של צדקה. ולכן, האור שנמשך לצדיקים שפדייתם היא במשפט, הוא האור שבגדר הכלים. [והיינו דזה מה שפדייתם היא במשפט, יש בזה שני ענינים. א', שאין זקוקים לצדקה, כיון שמגיע להם ע\"פ דין. ב', שענין המשפט <i>שולל</i> צדקה, כמ\"ש<sup data-n=\"1260\">18</sup> לא תכירו פנים במשפט, ופירש\"י<sup data-n=\"1261\">19</sup> שלא תאמר זה עני הוא כו' ומצוה לפרנסו]. והאור שנמשך לבע\"ת שפדייתם היא בצדקה, הוא האור שבהבדלה.\nג) <b>והנה</b> יש עוד פירוש בושבי', דשבי' הוא מלשון השבה, ההשבה מן הגולה<sup data-n=\"1262\">20</sup>. דלשון השבה [ובפרט כאשר הוא בסמיכות לתיבת תפדה שלפנ\"ז] מורה שגם לפני ההשבה אינו בגלות, ורק שהוא נמצא במקום אחר (מקום הגולה) וצריך לחזור ולשוב למקומו. ועפ\"ז שבי' הם נעלים יותר מאלו שנאמר עליהם תפדה. כי לשון פדי' נופל על מי שהוא בגלות<sup data-n=\"1263\">21</sup> (משא\"כ בזה שהוא רק נמצא במקום הגולה) וצריך לפדי' מהגלות. וצריך להבין, היאך שייך שפדייתם של אלו שהם בגלות היא במשפט (ע\"פ שורת הדין), וההשבה של אלו שנמצאים רק במקום הגולה (שהם נעליםיותר) היא בצדקה. וגם צריך להבין, מי הם שני הסוגים שעליהם נאמר תפדה ושבי'. הרי תפדה נאמר בנוגע לציון שקאי (כנ\"ל) על ישראל העוסקים בתומ\"צ, ואעפ\"כ הם בגלות וצריכים לפדי', ומהי זכותם של אלו שנק' בשם שבי' שאינם בגלות.\nד) <b>ויובן</b> בהקדים המבואר בהמאמר&lt;7&gt;, דענין גלות ושבי' שייך דוקא בהכלים, להיותם בבחי' מציאות דבר, משא\"כ בהאור, שהוא בבחי' אין, אין שייך גלות. וענין זה (דבאור אין שייך גלות) מובן גם בפשטות. שהרי מעט אור דוחה הרבה מן החושך<sup data-n=\"1264\">22</sup>, והיינו דגם לאחרי ירידת והמשכת האור בבחי' מדידה והגבלה [שאז דוקא שייך לומר מעט או הרבה], גם אז הוא דוחה את החושך, ועד שאפילו <i>מעט</i> אור דוחה הרבה חושך. ויתירה מזו, שהחושך נדחה <i>ממילא</i> מפני האור<sup data-n=\"1265\">23</sup>. [דבתחלת הבריאה היו אור וחושך משתמשים בערבוביא<sup data-n=\"1266\">24</sup>, אבל לאחרי שויבדל אלקים בין האור ובין החושך<sup data-n=\"1267\">25</sup>, החושך נדחה מפני האור]. ומזה מובן גם בפשטות, דבאור אין שייך ענין הגלות, כי החושך (דהגלות) נדחה מפני האור.\n<b>והנה</b> עד\"ז הוא גם בנשמה וגוף, שהם דוגמת אור וכלי<sup data-n=\"1268\">26</sup>. וכידוע מאמר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1269\">27</sup> שרק הגוף הוא בגלות ולא הנשמה. והיינו, דהגם שהנשמה היא מלובשת בגוף והגוף הוא בגלות, מ\"מ בנוגע להנשמה אין זה ענין של גלות. ורק שמצד זה שהגוף הוא בגלות, הנשמה שמלובשת בו היא נמצאת שלא במקומה וצריכה להשבה. וכמרז\"ל<sup data-n=\"1270\">28</sup> אני ישנה בגלותא ולבי ער, דגם כשאני ישנה בגלותא, הנשמה (ולבי<sup data-n=\"1271\">29</sup>) היא ער. דמכיון שהנשמה היא חלק אלוקה ממעל ממש<sup data-n=\"1272\">30</sup>, דגם כשהיא באופן ד\"ממש\" מלשון ממשות<sup data-n=\"1273\">31</sup> היינו שהיא מלובשת בגוף גשמי, היא חלק אלוקה ממעל [ועד שהיא חלק אלוקה ממעל ממש], וידוע מאמר הבעש\"ט<sup data-n=\"1274\">32</sup> שכשאתה תופס במקצת מן העצם אתה תופס בכולו, לכן, גם לאחרי ירידתה והתלבשותה בגוףבכח המפליא לעשות<sup data-n=\"1275\">33</sup>, ואפילו בזמן הגלות, אינה בגלות וכו'. ועפ\"ז יש לומר, דהלשון ושבי' קאי לא רק על סוג מיוחד שבישראל, אלא גם על הנשמה דכאו\"א מישראל. דמכיון שהנשמה אינה בגלות, אין שייך בה הלשון פדי'. אלא שאעפ\"כ צריכה להשבה, כי מכיון שהנשמה מלובשת בהגוף, ועד שהיא מתפעלת ממאורעי הגוף<sup data-n=\"1276\">34</sup>, ע\"י הגלות דהגוף, גם הנשמה נמצאת במקום הגלות, ולכן צריכה להשבה.\nה) <b>והנה</b> ידוע שכוונת הירידה דהגלות היא לצורך עלי'. שע\"י העבודה בזמן הגלות דוקא יהי' הגילוי דלעתיד שהוא נעלה יותר מהגלוי שהי' בזמן הבית. וכיתרון האור מן החושך<sup data-n=\"1277\">35</sup>, שע\"י החושך נעשה יתרון בהאור, שהוא נעלה יותר מכמו שהי' קודם. וכל שהירידה (החושך) היא למטה יותר, העלי' (יתרון האור) שעל ידה, היא נעלית יותר. ומזה מובן, דמכיון שהירידה דהגלות היא בעיקר בהגוף (כנ\"ל סעיף ד), לכן, העלי' דלע\"ל (הנעשית ע\"י הירידה דהגלות) שתהי' בהגוף היא נעלית יותר מהעלי' שתהי' בהנשמה. ויובן זה ע\"פ המבואר במק\"א<sup data-n=\"1278\">36</sup> בענין העלי' דהנשמה שנעשית ע\"י ירידתה למטה, שיש בזה שני ענינים. א', דעי\"ז שגם בהיותה למטה ומלובשת בגוף ונה\"ב היא עובדת את ה', מתגלה תוקף ההתקשרות שלה עם הקב\"ה, שגם ההעלם וההסתר דהגוף ונה\"ב אינו יכול לבטל ח\"ו, ואפילו לא לעשות גרעון בההתקשרות שלה. ב', שע\"י עבודת הנשמה למטה נעשה הבירור והזיכוך דהגוף ונה\"ב וחלקו בעולם. והחילוק שבין שני ענינים אלו הוא<sup data-n=\"1279\">37</sup>, דבענין הא' – יתרון האור הוא <i>ע\"י</i> החושך. והיתרון הוא, שע\"י החושך מתגלה תוקף האור, שגם החושך הכי גדול אינו מעלים לגבי'. משא\"כ בענין הב' – יתרון האור הוא גם בהחושך עצמו, שהחושך (דהגוף ונה\"ב והעולם) נהפך לאור. והיתרון הוא, שבכדי להפוך את החושך לאור הוא בכח העצמות שלמעלה מהגדרים דאור וחושך, וע\"י הפיכת החושך לאור, מתגלה כח העצמות. ויתירה מזו, דעי\"ז דוקא נשלמת הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"1280\">38</sup> [דענין נתאוה הוא בעצמותו ית'<sup data-n=\"1281\">39</sup>]. וכמבואר בתניא<sup data-n=\"1282\">40</sup>, שהכוונה בירידת הנשמה למטה היא לא בשביל הנשמה אלא בכדי לתקן את הגוף ונה\"ב וחלקו בעולם, כי עי\"ז דוקא נשלמת הכוונה דדירה בתחתונים<sup data-n=\"1283\">41</sup>.<b>וכמו</b> שהוא בהעלי' שע\"י ירידת הנשמה למטה, שעיקר העלי' הוא הבירור והזיכוך דהגוף וכו', עד\"ז הוא גם בהעלי' דלע\"ל ע\"י הירידה דהגלות, שעיקר העלי' היא בהגוף. דהיתרון שנעשה בהנשמה ע\"י חושך הגלות הוא גילוי תוקף ההתקשרות שלה, שהגם שהיא מלובשת בגוף והגוף הוא בגלות מ\"מ גם אז הנשמה אינה בגלות. והיתרון שנעשה בהגוף הוא שהחושך דהגוף כמו שהוא בגלות (שהוא חושך גדול יותר מהחושך שלו<sup data-n=\"1284\">42</sup> כמו שהוא מצד עצמו) נהפך לאור, ויתירה מזו, דעי\"ז שגם החושך שלו כמו שהוא בגלות נהפך לאור, נשלמת הכוונה דדירה בתחתונים, בתחתון שאין תחתון למטה ממנו<sup data-n=\"1285\">43</sup>.\nו) <b>והנה</b> ידוע<sup data-n=\"1286\">44</sup> שלע\"ל תהי' הנשמה ניזונית מן הגוף. ועפ\"ז יש לומר, שלע\"ל יהי' להנשמה (לא רק היתרון שנעשה <i>ע\"י</i> החושך, אלא) גם היתרון הבא מן החושך עצמו. דהגם שיתרון זה יהי' (בעיקר) בהגוף, גם הנשמה תקבל מהגוף יתרון זה. וע\"ד הידוע<sup data-n=\"1287\">45</sup> בענין העלי' שנעשית בהנשמה ע\"י ירידתה למטה בגוף ונה\"ב, דנוסף לזה שע\"י ההעלם וההסתר דהגוף ונה\"ב מתעוררים ומתגלים כחות הנעלמים של הנשמה (שהיו גם קודם ירידתה), הנה ע\"י שהנשמה מבררת ומזככת את הגוף ונה\"ב, נעשה בה גם יתרון והוספה. כמ\"ש<sup data-n=\"1288\">46</sup> משכני אחריך נרוצה, דע\"י שנה\"א פועלת שגם נה\"ב יהי' לה אהבת ה', שהאהבה דנה\"ב היא בדרך מרוצה, עי\"ז נעשה נרוצה גם בנה\"א, אחריך נרוצה לשון רבים<sup data-n=\"1289\">47</sup>. אלא שעכשיו, מכיון שהנשמה היא המשפיע והגוף הוא המקבל, יתרון זה דהנשמה (שמקבל מהגוף) אינו בשלימות, והשלימות דיתרון זה יהי' לע\"ל, מכיון שאז תהי' הנשמה ניזונית מן הגוף.\nז) <b>וזהו</b> ציון במשפט תפדה ושבי' בצדקה, דזה שישראל נק' בשם ציון הוא ע\"י שעוסקים בתורה עבודה וגמ\"ח, שהם כללות כל התומ\"צ, שעי\"ז הם נעשים בבחי' ציון מלשון סימן, דגם כשנמצאים בגלות אינם נאבדים ח\"ו בין האומות (ובדוגמת דבר שיש לו סימן כפשוטו, שע\"י הסימן מחזירים אותו לבעליו). ויתירה מזו, שע\"י עבודתם בתומ\"צ בזמן הגלות נעשה בהם יתרון ועלי', למעלה יותר מכמו שהיו בזמן הבית. והיתרון הוא בשני ענינים. א', שע\"י העבודה בזמן הגלות מתגלה (כנ\"ל סעיף ה) התוקף והבל\"ג דהאור, שגם חושך הכי גדול (חושך הגלות, כולל גם החושך כפול ומכופל שבדרא דעקבתא דמשיחא) אינו מעלים לגבי'. דבכללות הוא האור שלמעלה מהכלים (האור שבהבדלה<sup data-n=\"1290\">48</sup>), שהוא בליגבול. אבל אעפ\"כ הוא מוגדר בגדר אור. וב', שע\"י הפיכת החושך לאור מתגלה העצמות שלמעלה מהגדרים דאור וחושך (כנ\"ל).\n<b>והנה</b> בפסוק זה, הסיום והחותם<sup data-n=\"1291\">49</sup> של ההפטורה חזון ישעיהו [דענינו של ישעי' הוא (כשמו) ישועה<sup data-n=\"1292\">50</sup>, ועד לישועה אמיתית שהיא הגאולה שלימה שאין אחרי' גלות<sup data-n=\"1293\">51</sup>. דזהו גם מה שממשיך בכתוב<sup data-n=\"1294\">52</sup> אשר חזה גו' בימי גו' יחזקיהו, שביקש הקב\"ה לעשות חזקיהו משיח<sup data-n=\"1295\">53</sup>], מדבר בהעילוי שיהי' בגאולה העתידה. ובזה גופא – בעילוי הב', שהוא עיקר התכלית דהגלות. וזהו אומרו תפדה ושבי', שעילוי זה הוא הן בהגוף שיפדה מהגלות (תפדה) והן בהנשמה שתשוב ממקום הגולה (ושבי'). וזהו גם תפדה במשפט ושבי' בצדקה, דהעילוי שיהי' בהגוף (תפדה) הוא במשפט, דכיון שהגוף הי' בגלות ממש והי' בו הענין דהפיכת החושך לאור, לכן, היתרון והעילוי שנעשה עי\"ז, מגיע לו ע\"פ שורת הדין, במשפט. משא\"כ זה שהנשמה שהיתה רק במקום הגולה (ושבי') תתעלה לבחינה זו, הוא (לא ע\"פ שורת הדין, אלא) בצדקה. ולכאורה יש להוסיף, שבפרט אחד יש יתרון בהעלי' דהנשמה על העלי' דהגוף. שהעלי' דהגוף, שהיא במשפט (היינו שהעלי' היא ע\"פ חשבון דטעם ודעת), יש בזה איזו מדידה והגבלה, משא\"כ העלי' דהנשמה, שהיא בצדקה, היא למעלה מכל מדידה והגבלה.\n<b>ואין</b> מקרא יוצא מידי פשוטו<sup data-n=\"1296\">54</sup>, ועד שדוקא על ידי לימוד הפשט מתגלה העצם דתורה, כי פשט הוא בעולם העשי'<sup data-n=\"1297\">55</sup>, שבו דוקא נשלמת הכוונה דדירה בתחתונים. ולכאורה י\"ל דזהו גם הטעם (בפנימיות הענינים) דזה שהלימוד עם תשב\"ר, הבל שאין בו חטא<sup data-n=\"1298\">56</sup>, הוא דוקא ע\"פ הפשט. וי\"ל שכן הוא גם בנוגע לעניננו – הפסוק ציון במשפט תפדה ושבי' בצדקה, שעיקר הענין בזה הוא פירוש הפסוק כפשוטו, הפדי' והיציאה מהגלות בפשטות בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש בעגלא דידן.\n**********",[["1242","*","יצא לאור ב<b>קונטרס שבת חזון – תשמ\"ח</b>, \"לקראת ש\"ק פ' דברים, שבת חזון, תשעה באב נדחה . . <i>ה' מנ\"א</i>,<i> שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["1243","1","ישעי' א, כז. – סיום וחותם הפטורת שבת חזון."],["1244","2","נדפס בהמשך תער\"ב ח\"א ע' תקסד ואילך."],["1245","3","באוה\"ת פרשתנו ד\"ה זה (ע' לו) (ובאוה\"ת ויצא ריג, ב), שהפירוש דקאי על העיר עצמה הוא \"דוחק קצת\"."],["1246","4","ויש לומר, שהכוונה בהמשך תער\"ב שם ב\"אין הכוונה על עיר ציון <i>בפרט</i>\" היא (לא לשלול הפירוש דקאי על העיר עצמה, כ\"א) לשלול הפירוש דקאי על <i>ישראל</i> היושבים בציון. ועפ\"ז מדוייק הלשון \"אין הכוונה על עיר ציון <i>בפרט</i> כ\"א על כללות <i>ישראל</i>\"*."],["1247","5","כלי יקר עה\"פ – הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600095\" data-slug=\"or-hatorah-hb\" data-id=\"8316600095\">אוה\"ת נ\"ך</a> עה\"פ (ח\"א ס\"ע צה)."],["1248","6","אוה\"ת נ\"ך שם."],["1249","7","דשנת עדר\"ת בסופו (המשך הנ\"ל ע' תקעא)."],["1250","8","תענית פ\"ד סוף ה\"ב. וכ\"ה בזח\"ג לה, א (הובאו באוה\"ת פרשתנו (ופ' ויצא) שם. נ\"ך שם ס\"ע צז). ירושלמי מגילה פ\"ג סוף ה\"ו."],["1251","9","ישעי' נא, טז."],["1252","10","אוה\"ת פרשתנו (ופ' ויצא) שם. נ\"ך שם ע' צח. ד\"ה זה דשנת תער\"ב ושנת עדר\"ת. ועוד (מקה\"ע לירושלמי שם)."],["1253","11","אבות פ\"א מ\"ב.\n*) <i>ראה גם רד\"ה זה דשנת תער\"ב (המשך הנ\"ל ע' ע)</i>:<i> הכוונה היא על כללות ישראל לא יושבי ציון דוקא</i>."],["1254","12","כ\"ה באוה\"ת נ\"ך שבהערה 6. ובהמאמר דשנת עדר\"ת (שם) שושבי' הם בעלי תשובה. וראה לקמן בפנים."],["1255","13","ראה גם לקו\"ת פרשתנו ד\"ה זה (א, ג)."],["1256","14","סנהדרין צז, ב. רמב\"ם הל' תשובה פ\"ז ה\"ה."],["1257","15","רמב\"ם שם."],["1258","16","פרש\"י עה\"פ. וראה גם אוה\"ת נ\"ך שם ע' צו. ובכ\"מ."],["1259","17","כמ\"ש (מיכה ז, יח) מי א-ל כמוך נושא עון וגו', ובמצודת דוד שם: \"משורת הדין אין אנו ראויים . . כי אנו מלאי עון, אבל מי הוא א-ל כמוך המוחל את העון\". וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380962\" data-slug=\"likkutei-torah\" data-id=\"4001380962\">לקו\"ת (דרושי ר\"ה ס, ד</a>): \"א-ל הוא חסד . . מי בעל חסד כמוך . . נושא עון ועובר על פשע\". ולהעיר גם ממרז\"ל (יל\"ש תהלים רמז תשב) שאלו לתורה וכו' ורק הקב\"ה אמר יעשה תשובה ויתכפר לו."],["1260","18","פרשתנו א, יז."],["1261","19","עה\"פ (מספרי עה\"פ)."],["1262","20","מצודת דוד עה\"פ."],["1263","21","והמבואר בכמה דרושים (וראה בארוכה ד\"ה זה דשנת תשל\"ה (לעיל ע' קכה ואילך). <i>וש\"נ</i>) שב\"ציון\" אין שייך גלות ממש – הכוונה בזה היא שהגלות אינו באופן של שבי' [וכמבואר שם החילוק בין ציון לשבי' מלשון שבי'] אבל מ\"מ הו\"ע של גלות שלכן צריך לפדי'. משא\"כ ושבי' מלשון השבה הוא שנמצא רק <i>במקום</i> הגולה, ואינו צריך לפדי'."],["1264","22","<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא פי\"ב (יז, א</a>). חובת הלבבות שער יחוד המעשה פ\"ה."],["1265","23","<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא</a> פי\"ב שם. פכ\"ט (לז, ב)."],["1266","24","פרש\"י עה\"פ בראשית א, ד (וראה גם פרש\"י עה\"פ שם, יד). וראה גם ירושלמי ברכות פ\"ו ה\"ח. ב\"ר פ\"ג, ו (וביפ\"ת שם). וראה ספר הערכים-חב\"ד כרך ב' ערך אור – ביחס לחושך ס\"ו. וש\"נ."],["1267","25","בראשית שם, ד."],["1268","26","ראה תקו\"ז בהקדמה (\"פתח אליהו\" – יז, ב): אשתארו כו' כגופא בלא נשמתא. וראה סידור (עם דא\"ח) קסד, רע\"ג. ד\"ה בסוכות תשבו עת\"ר (סה\"מ עת\"ר ע' כז ואילך) ותש\"י (פכ\"ה – סה\"מ ה'תש\"י ע' 59 ואילך). וראה גם שעהיוה\"א פ\"ו (פא, רע\"א). וראה ספר הערכים-חב\"ד שם ערך אורות דספירות – ביחס לכלים ס\"ח. וש\"נ."],["1269","27","סה\"מ תרפ\"ז ע' קצז. קונטרסים ח\"א קעה, ב. לקו\"ד כרך ד תרצב, א."],["1270","28","זח\"ג צה, א (עה\"פ שה\"ש ה, ב)."],["1271","29","ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381264\" data-slug=\"likkutei-torah\" data-id=\"4001381264\">לקו\"ת שה\"ש (לג, ד</a>) מובא מזהר שם – ולבי דא קוב\"ה. אבל ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381265\" data-slug=\"likkutei-torah\" data-id=\"4001381265\">לקו\"ת שם (לד, א</a>), שמקשר זה גם עם \"בחי' רצון ותשוקה שיש בכל נפש מישראל\". ולהעיר מאגה\"ק סל\"א."],["1272","30","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["1273","31","ראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ד ע' תז. מכתב כ\"ב אייר ה'תשי\"א*. וראה ג\"כ \"היום יום\" כג מנחם אב."],["1274","32","המשך תרס\"ו ע' תקכב. ובכ\"מ. וראה ספר השיחות ה'תש\"א ס\"ע 32 ובהערה 19 שם.\n*) <i>נדפס באגרות-קודש כ\"ק אדמו\"ר שליט\"א ח\"ד ע' רצא</i>. <b>המו\"ל</b>."],["1275","33","דרכי משה לטור או\"ח ס\"ו סק\"ב. רמ\"א או\"ח שם סוף ס\"א."],["1276","34","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, ב</a>)."],["1277","35","קהלת ב, יג. וראה בארוכה ספר הערכים-חב\"ד הנ\"ל ערך אור – ביחס לחושך ס\"ח (ע' תקעה). <i>וש\"נ</i>."],["1278","36","ראה ד\"ה והי' עקב תשכ\"ז (לקמן ע' קצ ואילך) סעיף ד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151259\" data-slug=\"likkutei-sichot\" data-id=\"1300151259\">לקו\"ש חט\"ו ע' 246</a> ואילך. <i>וש\"נ</i>."],["1279","37","ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח נח נט, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091066\" data-slug=\"likkutei-sichot\" data-id=\"1300091066\">לקו\"ש ח\"ט ע' 66</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071044\" data-slug=\"likkutei-sichot\" data-id=\"1300071044\">לקו\"ש ח\"ז ע' 44</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091103\" data-slug=\"likkutei-sichot\" data-id=\"1300091103\">שם ע' 103</a>. ח\"ט ע' 22."],["1280","38","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["1281","39","ואף שגם הפיכת החושך לאור הוא בכח העצמות שאינו מוגדר בהגדרים דאור וחושך (כנ\"ל בפנים) – הרי ענין זה (שאינו מוגדר) הוא <i>העילוי וההפלאה</i> שלו (ענין \"גילוי\"), משא\"כ הענין ד\"נתאוה\"."],["1282","40","פל\"ז (מח, ב), מע\"ח שער כו (שער הצלם) פ\"א."],["1283","41","דמ\"ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא שם</a> שהכוונה בירידת הנשמה למטה היא בכדי לתקן הגוף כו' – בא בהמשך להמבואר שם פל\"ו שתכלית הבריאה היא שיהי' לו ית' דירה בתחתונים."],["1284","42","ראה סה\"מ עת\"ר ע' יב ואילך. ה'תש\"י ע' 18 ואילך."],["1285","43","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["1286","44","ראה ד\"ה את הוי' האמרת תרע\"ח ספ\"ה (סה\"מ תרע\"ח ע' תיז. ומציין שם: ועמ\"ש באורך בד\"ה אלה תולדות נח, רל\"ז). וראה המשך וככה תרל\"ז פצ\"א-צב. ובכ\"מ."],["1287","45","ראה בארוכה ד\"ה והי' עקב ובלקו\"ש שבהערה 36. <i>וש\"נ</i>."],["1288","46","שה\"ש א, ד."],["1289","47","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011282\" data-slug=\"likkutei-sichot\" data-id=\"1300011282\">לקו\"ש ח\"א ע' 268</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380085\" data-slug=\"likkutei-torah\" data-id=\"4001380085\">לקו\"ת ויקרא ב, סע\"ד</a>. אוה\"ת שה\"ש עה\"פ (ע' סד. שם ע' עב. שם ע' פב-ג)."],["1290","48","ובהמאמר דשנת עדר\"ת (נעתק לעיל סעיף ב) ש\"צדקה\" קאי על אור זה. דהגם שמבאר שם במעלתהבעלי תשובה (להפירוש דשבי' הוא עושי תשובה) – יש לומר, דמעלת הבע\"ת המבואר שם היא הצמאון והחילא יתיר שבא <i>ע\"י</i> החושך (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז – יד, א</a>), וזה מגיע (רק) <i>באור</i> הבל\"ג. משא\"כ זה שבבע\"ת נהפכים הזדונות לזכיות, ועד\"ז בעבודת הצדיקים – זה שהגוף ונה\"ב (ועד\"ז הדברים הגשמיים שבהם נעשה המצוה) נהפכים לקדושה – מגיע בהעצמות."],["1291","49","דהכל הולך אחר החיתום (ברכות יב, א)."],["1292","50","ראה פרש\"י ומצו\"ד עה\"פ ישעי' מט, א. זח\"ב קעט, סע\"ב."],["1293","51","ראה תוד\"ה ה\"ג ונאמר – פסחים קטז, ב."],["1294","52","ישעי' א, א."],["1295","53","סנהדרין צד, א."],["1296","54","שבת סג, א. וש\"נ."],["1297","55","ע\"ח (הובא בנגיד ומצוה בתחלתו. נהר שלום בהקדמת רחובות הנהר בסופה) ומשנת חסידים (מס' חיוב הנשמות פ\"א מ\"ב), הובאו ונתבארו בלקו\"ד כרך ד תשעא, א."],["1298","56","שבת קיט, ב."]]],[1500390019,"<h3>בס\"ד. ש\"פ דברים, תשעה-באב נדחה, ה'תשכ\"ד<sup data-n=\"1299\">*</sup></h3>\n<b>קץ</b> שם לחושך<sup data-n=\"1300\">1</sup>, ואיתא במדרש<sup data-n=\"1301\">2</sup>, זמן נתן לעולם כמה שנים יעשה באפילה. ומבאר הצמח צדק<sup data-n=\"1302\">3</sup> שהוא ע\"ד מ\"ש בזהר<sup data-n=\"1303\">4</sup> עה\"פ<sup data-n=\"1304\">5</sup> לכל זמן ועת לכל חפץ, שיש זמן קצוב לחושך הגלות. וצריך להבין, דכיון שכל הדברים שבעולם יש להם זמן קצוב, <i>לכל</i> זמן, מהו החידוש בקץ שם לחושך. וביותר אינו מובן, דמלשון הכתוב קץ <i>שם</i> לחושך משמע, שהחושך מצד עצמו אין לו קץ, אלא <i>ששם</i> לו קץ. ויש לומר הביאור בזה, דזה שהדברים הבלתי רצויים אינם נמצאים בי\"ד העתים שנקצבו לטובה<sup data-n=\"1305\">6</sup> הוא רק שלא ישנם אז בפועל, כי ע\"י הענינים הטובים שישנם אז, הדברים שאינם רצויים הם מתבטלים. דכמו\"כ הוא באור וחושך, שהאור דוחה את החושך [ועד שאפילו מעט אור דוחה הרבה חושך<sup data-n=\"1306\">7</sup>]. וענין קץ שם לחושך הוא, שלאחרי שיהי' הקץ שלו לא יהי' <i>שייך כלל</i> ענין החושך. דזה שהגאולה העתידה תהי' גאולה נצחית שאין אחרי' גלות<sup data-n=\"1307\">8</sup>, הוא, שאז לא יהי' שייך חושך הגלות.\nב) <b>והנה</b> החילוק באופן ביטול החושך – אם הוא רק נדחה מפני האור, או שאין שייך כלל מציאותו – תלוי בדרגת האור. שבכדי לדחות את החושך (אבל גם לאחרי שנדחה שייכת מציאותו) הוא גם ע\"י אור מוגבל, ועד שאפילו <i>מעט</i> אור דוחה הרבה חושך<sup data-n=\"1306\">7</sup>. ובכדי שהחושך יתבטל לגמרי הוא ע\"י אור בלתי מוגבל. וכדאיתא במדרש<sup data-n=\"1308\">9</sup> דזה שהגאולה דיציאת מצרים (וכן הגאולה מגלות בבל ושאר הגלויות עד להגאולה דלעתיד) היתה גאולה שיש אחרי' גלות, וגאולה העתידה תהי' גאולה נצחית שאין אחרי' גלות, הוא, כי הגאולה דיציאת מצרים היא דוגמת אור הנר ששייך בו כיבוי<sup data-n=\"1309\">10</sup>, וגאולה העתידה היא דוגמת אור היום שאין שייך בו כיבוי.היינו, שהגילוי דגאולה העתידה יהי' גילוי אור בלתי מוגבל שאין שייך בו הפסק<sup data-n=\"1310\">11</sup>, ולכן תהי' גאולה נצחית שאין אחרי' גלות<sup data-n=\"1311\">12</sup>.\nג) <b>והנה</b> ידוע שכל גילוי הוא ע\"י תורה (תורה אור<sup data-n=\"1312\">13</sup>). ומזה מובן, דכיון שביטול חושך הגלות הוא ע\"י אור, לכן, בכדי לקרב ולמהר עוד יותר את הגאולה העתידה, הוא ע\"י הלימוד בתורה בענין האור<sup data-n=\"1313\">14</sup>. ולהעיר, דבהדרוש של אדמו\"ר (מהורש\"ב) נ\"ע שנאמר בשבת תשעה באב נדחה<sup data-n=\"1314\">15</sup> מדובר בענין האור. דיש לומר, שהשייכות דענין זה לתשעה באב נדחה הוא<sup data-n=\"1315\">16</sup>, כי תשעה באב שחל בשבת ונדחה הוא מסוגל לפעול שיהי' נדחה לגמרי<sup data-n=\"1316\">17</sup>, ודחיית וביטול הגלות הוא ע\"י אור<sup data-n=\"1317\">18</sup>.\n<b>ומבואר</b> בהמאמר, דאור הוא אין, ביטול. [דהחילוק בין אור וכלי, הוא, שאור הוא אין וכלי הוא יש]. ובהביטול דאור ג' מדריגות. הביטול דאור מצד עצמו, מפני שאור הוא מעין המאור, והביטול שבו ע\"י שנרגש בו מקורו, והביטול שלו מצד טבע הרצוא והעלי' שבו ליכלל במקורו. וצריך להבין, הרי גם הביטול דאור שמצד עצמו הוא (לכאורה) זה שאור אינו מציאות לעצמו וענינו הוא גילוי המאור, ומהו החילוק בין האור עצמו (שענינו הוא גילוי המאור) לזה שנרגש בו מקורו. גם צריך להבין מ\"ש בהמאמר<sup data-n=\"1318\">19</sup> שהביטול שבהאור ע\"י שנרגש בו מקורו הוא הביטול דכלא חשיב, הרי זה שהאור אינו מציאות לעצמו וענינו הוא גילוי המאור, הוא, לכאורה, ביטול גדול יותר מהביטול דכלא חשיב [כי הביטול דכלא חשיב הוא רק בנוגע לחשיבותו, שאין לו ערך וחשיבות לגבי מקורו, ואין זה נוגע לעצם מציאותו], ובהמאמר אומר, שהביטול שניתוסף בהאור ע\"י שנרגש בו מקורו, על הביטול שלו מצד עצמו (שענינו הוא גילוי המאור), הוא הביטול דכלא חשיב.\n<b>ויש</b> לומר הביאור בזה ע\"פ הידוע<sup data-n=\"1319\">20</sup>, דהגם שאור הוא מעין המאור, מ\"מ, כיון שהמאור הוא מובדל מהאור (שהמאור אינו מקור להאור ורק שהוא נמצאממנו), לכן זה שהאור מגלה את המאור הוא רק מציאות המאור ולא מהותו<sup data-n=\"1320\">21</sup>. אלא שאעפ\"כ, מצד דביקותו של האור בהמאור נרגש בו גם מהות המאור (שמובדל מהאור ואינו מתגלה בו). ועי\"ז הוא מתבטל ממציאותו. דמציאות האור הוא גילוי (המאור), וע\"י שנרגש בו שהמאור (מהות המאור) הוא למעלה מגילוי, ושהגילוי אין לו ערך (כלא חשיב) לגבי המאור, הוא מתבטל ממציאותו.\n<b>אלא</b> שמ\"מ, גם הביטול דאור ע\"י שנרגש בו מקורו אינו ביטול לגמרי. דכיון שהאור והמקור שלו הם שני ענינים, והאור הוא מחוץ למקורו, הרי זה שהאור מרגיש את מקורו הוא שנרגש בו דבר שחוץ ממנו, שאין זה נוגע לעצם מציאותו. ולכן, הביטול שע\"י הרגש זה הוא רק בההתפשטות שלו ולא בעצם מציאותו. ועיקר הביטול דאור (ביטול לגמרי) הוא הביטול שמצד הרצוא שלו ליכלל במקורו. דכיון שרצון נוגע לעצם מציאותו [כפירוש הבעש\"ט<sup data-n=\"1321\">22</sup> עה\"פ<sup data-n=\"1322\">23</sup> שרפים עומדים ממעל לו, שע\"י הרצון שלהם ליכלל באוא\"ס הם (כמו) נמצאים (עומדים) שם. וע\"ד רצון האדם, דבמקום שרצונו של אדם, שם <i>הוא</i> נמצא, ויתירה מזו, ששם הוא נמצא <i>כולו</i><sup data-n=\"1323\">24</sup>], לכן, ע\"י שרוצה ליכלל במקורו הוא (כמו) <i>כלול</i> במקורו. ולכן, הביטול שלו מצד הרצון ליכלל במקורו הוא ביטול לגמרי (ע\"ד הביטול דאור הכלול במאור).\nד) <b>וממשיך</b> בהמאמר, שג' המדריגות בהביטול דאור הם בג' מדריגות שבאור. הביטול דאור מצד עצמו הוא בהאור המתלבש בכלים. הביטול דאור מפני שנרגש בו מקורו הוא בהאור שלמעלה מהתלבשות בכלים, אבל בגדר התלבשות. והביטול דאור שמצד טבע הרצוא והעלי' שלו ליכלל במקורו הוא בהאור שלמעלה מגדר התלבשות. וג' מדריגות שבאור כמו שהם בענין הספירות הם בינה חכמה וכתר. אור המתלבש בכלים הוא בבינה, כי בבינה הוא חיבור האור עם הכלי. דזהו שבבינה הוא הוי' בניקוד אלקים<sup data-n=\"1324\">25</sup>, כי בבינה הוא חיבור האור (הוי') עם הכלים (אלקים)<sup data-n=\"1325\">26</sup>. האור שלמעלה מהתלבשות בכלים אבל בגדר התלבשות הוא בחכמה. והאור שלמעלה מגדר התלבשות הוא בכתר. וזהו שהביטול דדעת עליון, שכולא קמי' כלא חשיב, הוא דוקא בחכמה שלמעלה מהבינה<sup data-n=\"1326\">27</sup>, כי הביטול דכלא חשיב הוא מצד זה שנרגש בו מקורו, ולכן ביטול זה הוא דוקא בחכמה – אור שלמעלהמהתלבשות (אבל בגדר התלבשות). והביטול שבכתר (אור שלמעלה מגדר התלבשות) הוא ביטול נעלה יותר גם מהביטול דחכמה, שהביטול דחכמה הוא הביטול דהוא לבדו הוא ואין זולתו<sup data-n=\"1327\">28</sup>, הביטול דאין, ובכתר הוא הביטול דאפס.\n<b>ויש</b> לומר, דזה שהביטול דאור שמצד עצמו הוא באור המתלבש בכלים והביטול דאור שמצד הרגש מקורו ומצד הרצוא ליכלל במקורו הוא בהאור שלמעלה מהתלבשות, הוא, כי ענין האור הוא גילוי, וכיון שעיקר הגילוי שבאור הוא ע\"י התלבשותו בכלים, לכן, האור (כמו שהוא מצד עצמו) יורד ונמשך להתלבש בכלים. דהגם שהכלים הם היפך האור, שהאור הוא אין והכלים הם יש (כמובא לעיל סעיף ג מהמאמר), מ\"מ, כיון שהביטול (אין) דאור שמצד עצמו הוא זה שענינו הוא <i>גילוי</i> המאור, לכן, מצד זה גופא הוא יורד ונמשך להתלבש בכלים, בכדי שהגילוי שלו יהי' בשלימות<sup data-n=\"1328\">29</sup>. אבל כשנרגש בהאור המקור שלו שמובדל מגילוי, עי\"ז הוא מתבטל מענין הגילוי (כנ\"ל סעיף ג) ואינו נמשך ומתלבש בכלים. אלא שמ\"מ, כיון שהביטול שלו ע\"י שנרגש בו מקורו הוא רק בהתפשטותו ולא בעצם מציאותו (כנ\"ל שם), לכן, הביטול שלו הוא באופן שנשאר עדיין בהגדר שלו, גדר הגילוי, ולכן הוא בגדר התלבשות בכלים. וע\"י הביטול דאור שמצד הרצוא ליכלל במקורו, כיון שביטול זה הוא בעצם מציאותו, לכן, ע\"י ביטול זה אינו (גם) בגדר התלבשות בכלים.\nה) <b>והנה</b> ג' מדריגות הנ\"ל בהביטול דאור, יש (דוגמתם) גם בעבודת האדם<sup data-n=\"1329\">30</sup>. וע\"פ המובא לעיל מהמאמר שג' מדריגות הנ\"ל בהביטול דאור הם בבינה חכמה וכתר, יש לומר, שג' ביטולים הנ\"ל בעבודת האדם הם הביטול דהשגה המיוסדת על אמונה, הביטול דאמונה והביטול דמסירת נפש.\n<b>ויובן</b> זה ע\"פ המבואר במק\"א<sup data-n=\"1330\">31</sup> בענין מקיף ופנימי, שגם כשהמקיף נמשך ומתלבש בפנימי, הוא נשאר במהותו, מקיף. [וכמו\"כ הוא בנוגע להתלבשות האור בכלים (שהאור מצד עצמו הוא מקיף וע\"י התלבשותו בכלים נעשה אור פנימי), שגם לאחרי שהאור מתלבש בכלים הוא נשאר במהותו, אור<sup data-n=\"1331\">32</sup>] וע\"ד הרצון, שגם לאחרי שנמשך ומתלבש בשכל ועד שהוא מטה את השכל שיהי' כפי הרצון ונעשה טעם להרצון, מ\"מ הוא נשאר במהותו, רצון שלמעלה מטעם. וכמו\"כ הוא בהתלבשות אמונה בשכל, דכשמתבונן בשכלו בענין שהוא מאמין בו (באמונה פשוטה שלמעלה משכל) בכדי שגם בשכלו יבין את הענין, שגם לאחרי שהוא מבין את הענין בשכלו, האמונה שלו היא אמונה שלמעלה משכל. והחילוק שבין שני המשלים הוא, שבהמשל דהתלבשות הרצון בשכל, זה שהשכל מבין כפי הרצון הוא לא מצד השכל אלא מצדהרצון <i>שמטה</i> את השכל <i>ומשנה</i> אותו. וכיון שהתלבשות הרצון בשכל היא באופן שהשכל מתבטל (משתנה) מפני הרצון, לכן, זה שההתלבשות אינה פועלת שינוי בהרצון (שגם לאחרי התלבשותו בשכל הוא נשאר במציאותו), אינו חידוש כ\"כ. ובהתלבשות האמונה בשכל, זה שהשכל בא למסקנא שהענין שמאמין בו הוא אמת גם מצד השכל, הוא מצד השכל [דכשמתבונן בשכלו בכדי שגם השכל שלו יהי' כפי האמת, הוא משתדל שההתבוננות והשקו\"ט שלו יהיו ע\"פ אמיתית השכל<sup data-n=\"1332\">33</sup>], ואעפ\"כ ההתלבשות אינה פועלת שינוי בהאמונה, וגם לאחרי שמבין את הענין בשכלו (מצד השכל), האמונה שלו היא אמונה שלמעלה מהשכל. ועוד חילוק בין שני המשלים, דבהתלבשות הרצון בשכל, זה שהרצון מתלבש בשכל ופועל עליו שיהי' כפי הרצון הוא מפני שהרצון שולט על השכל (ולא שזה נוגע להרצון). וכיון דזה שהרצון שולט על השכל הוא (לא הרצון עצמו, אלא) היחס שלו לשאר הכחות, לכן ירידת הרצון והתלבשותו בשכל היא ירידה אמיתית (יציאה מרצון לשכל). ובהתלבשות האמונה בשכל, זה שמתבונן בשכלו בכדי להבין את הענין הוא בשביל <i>האמונה</i>, בכדי שהאמונה שלו תהי' גם בפנימיות. ולכן ירידת האמונה והתלבשותה בשכל אינה ירידה אמיתית.\n<b>וע\"פ</b> הידוע<sup data-n=\"1333\">34</sup> שאמונה היא ביטול ושכל הוא מציאות, מובן, דענין התלבשות האמונה בשכל הוא שהביטול נמשך במציאות. וכיון שההתבוננות (וההשגה) שלו היא בשביל האמונה [וגם זה שהשכל נשאר במציאותו ואינו מתבטל לגבי האמונה (כמו שהוא מתבטל לגבי הרצון) הוא בשביל האמונה, בכדי שגם השכל כמו שהוא <i>במציאותו</i> יהי' כפי האמונה], לכן גם לאחרי שהביטול דאמונה נמשך בהמציאות דשכל, הביטול הוא בתקפו. והחילוק שבין הביטול דאמונה שמתלבשת בשכל והביטול דאמונה שלמעלה מהשכל הוא, שהביטול דאמונה המתלבשת בשכל בא בציור דגילוי (שהביטול מתגלה בשכל), מציאות. דנוסף לזה <i>שהשכל</i> (שבו מתלבשת האמונה) הוא מציאות, גם הגילוי ד<i>האמונה</i> (זה שהאמונה היא בגילוי באופן שהיא נרגשת בהשכל) הוא מציאות<sup data-n=\"1334\">35</sup>. והביטול דאמונה שלמעלה מהשכל הוא למעלה מהמציאות דגילוי. [בדוגמת החילוק בין הביטול דאור המתלבש בכלים והביטול דאור שלמעלה מהתלבשות, שגם האור המתלבש בכלים אינו מציאות לעצמו וכל ענינו הוא גילוי המאור. אלא שהביטול דאור המתלבש הוא בציור דגילוי, מציאות. דנוסף לזה שהכלים שבהם מתלבש האור הם מציאות, גם הגילוי דהאור (שמתגלה בהכלים) הוא מציאות. והביטול דאור שלמעלה מהתלבשות הוא שאין בו גם המציאות דגילוי].ו) <b>והנה</b> גם הביטול דאמונה שלמעלה מהשכל אינו ביטול בתכלית. כי הביטול דאמונה הוא זה שהוא מאמין באלקות הגם שמצד שכלו (המציאות שלו) אין לו הוכחות על זה. וכיון שהטעם לזה שהוא מאמין באלקות (הגם שאין לו הוכחות על זה) הוא מפני שהאלקות נרגש בנפשו [אלא שהרגש זה הוא למעלה מהמציאות (השגה) שלו], לכן, הביטול דאמונה אינו ביטול בתכלית, כיון דזה שמאמין הוא מפני שנרגש <i>בו</i> אלקות. ובדוגמת הביטול דאור ע\"י שנרגש בו מקורו (מהות המאור), דהגם שזה שנרגש בו מקורו הוא למעלה ממציאותו [דמהות המאור אינו מתגלה בהאור], מ\"מ, נרגש זה בהאור כמו שהוא <i>במציאותו</i>, מציאות שמחוץ להמקור [שלכן, זה שנרגש בו מקורו אינו פועל עליו שירצה ליכלל במקורו]. והביטול דמס\"נ, שמוסר את נפשו בשביל האלקות (יציאה ממציאותו), הוא דוגמת הביטול דאור מצד הרצוא שלו ליכלל במקורו. וכמובן גם מהמשך הענינים בתניא<sup data-n=\"1335\">36</sup>, דכח המס\"נ שבישראל הוא דוגמת הרצון דהנשמה ליפרד ולצאת מן הגוף ולידבק בשרשה ומקורה, הגם שתהי' אין ואפס ותתבטל שם במציאות לגמרי<sup data-n=\"1336\">37</sup>. ולהוסיף, שבהרצון דהנשמה ליכלל באוא\"ס ישנם ב' דרגות. שהיא רוצה ליכלל, ושהיא בבחינת כליון בדרך ממילא. ויש לומר, דכיון שהביטול (דאור) שמצד הרצון ליכלל במקורו הוא ביטול לגמרי (ע\"ד הביטול דאור הכלול במאור כנ\"ל סעיף ג), לכן מתבטל גם הרצון.\nז) <b>וממשיך</b> בהמאמר<sup data-n=\"1337\">38</sup>, דכיון שהרצוא דאור ליכלל במקורו הוא מפני שדבוק במקורו, לכן, הרצוא דאור [וכן הביטול שמצד הרצוא] הוא בכל הדרגות דאור, גם בהאור המלובש בכלים (שהרי זה שהאור הוא דבוק במקורו הוא בכל הדרגות שבו), אלא שעיקר הרצוא [והביטול שמצד הרצוא] הוא בעצם האור שלמעלה מגדר התלבשות בכלים. ויש לומר, דבטבע הרצוא שבאור ליכלל במקורו, שני ענינים. הרצון להיות כלול במקורו, והרצון לא להיות חוץ למקורו. וזה שעיקר הרצוא הוא בעצם האור, הוא, שבהאור המתלבש בכלים ושבגדר התלבשות, הוא הרצון לא להיות חוץ למקורו, ובעצם האור הרצון להיות כלול במקורו.\n<b>והענין</b> הוא, דשני רצונות הנ\"ל יש בכל אחד מהם מעלה שאינה בזולתו. הרצון להיות כלול במקורו הוא <i>נעלה</i> יותר, כי רצון זה שבאור הוא מפני שנרגש בו המקור – וגילוי המקור הוא בעיקר בעצם האור. והרצון לא להיות חוץ למקורו הוא בפנימיות יותר (טיפער) בהאור, ועד שרצון זה הוא בעצם מציאותו – ולכן הוא בכל הדרגות שבו. וע\"ד החילוק שבין הרצון דנשמה ליכלל באוא\"ס וכח המס\"נ<sup data-n=\"1338\">39</sup>, שהרצון ליכלל באוא\"ס הוא בגילוי רק ביחידי סגולה, וענין המס\"נ שלא להיות נפרד ח\"ו מאלקות הוא בגילוי בכאו\"א.ח) <b>והנה</b> ע\"פ הידוע גודל הדיוק במאמרי רבותינו נשיאינו (גם בנוגע לזמן אמירתם), מסתבר לומר, שהשייכות דמאמר הנ\"ל לתשעה באב נדחה הוא הן מצד כללות התוכן דהמאמר – ענין האור, וגם מצד הפרטים דאור המבוארים בהמאמר.\n<b>והענין</b> הוא, דבכדי שהחושך יתבטל לגמרי (ולא רק שיהי' נדחה מפני האור) הוא (דוקא) ע\"י גילוי אור בלתי מוגבל (כנ\"ל סעיף ב). ובפרטיות יותר – ע\"י גילוי אור הכלול במאור. דהאור שמתפשט מחוץ להמאור, ענינו הוא להאיר את החושך. וכמו אור השמש שמתפשט בחלל העולם (מחוץ להשמש), שהמקום דחלל העולם הוא מקום חשוך, וענינו של האור המתפשט בחלל העולם הוא להאיר מקום החושך. והאור הכלול במאור הוא במקום (דרגא) שאין שייך בו ענין החושך. ועד\"ז הוא למעלה, דמהחילוקים בין אוא\"ס שקודם הצמצום (אור הכלול בעצמותו) והאור שלאחרי הצמצום (שהוא דוגמת אור המתפשט מחוץ להמאור), הוא, שהאור שנמשך לאחרי הצמצום ענינו הוא להאיר את העולמות. ולכן, הגילוי אלקות שישנו בעולם ע\"י גילוי האור שלאחרי הצמצום הוא בדרך התחדשות. מציאות בפשיטות ואלקות בהתחדשות<sup data-n=\"1339\">40</sup>. [ע\"ד אור השמש שמתפשט בחלל העולם, שהמקום דחלל העולם מצד עצמו הוא מקום חשוך, והאור שמאיר בו הוא בדרך הוספה וחידוש]. וכשמאיר בעולם גילוי אוא\"ס שקודם הצמצום, אלקות הוא בפשיטות<sup data-n=\"1339\">40</sup>, ועד שלא ישנו נתינת מקום כלל לענין שאינו אלקות. [בדוגמת שהי' קודם הצמצום, כשהי' אוא\"ס ממלא את מקום החלל, שלא הי' אז מקום לעמידת העולמות<sup data-n=\"1340\">41</sup>].\n<b>וזהו</b> שביטול החושך לגמרי הוא ע\"י גילוי אור הכלול במאור (אוא\"ס שלפני הצמצום), דהאור שלאחרי הצמצום, כיון שענינו הוא להאיר את העולמות, דמזה מובן שהעולמות תופסים מקום לגבי', לכן, גילוי אור זה הוא באופן שההעלם והסתר דעולם ביכלתו להעלים עליו. והיינו, דנוסף לההעלם דעולם שישנו גם כשמאיר הגילוי, שהגילוי אלקות בעולם שע\"י גילוי אור זה הוא בדרך התחדשות (כנ\"ל), הנה אפשר שההעלם דעולם יעלים גם על גילוי זה (שלא יהי' בעולם גילוי אלקות כלל, גם לא גילוי שבדרך התחדשות). ובכדי שיהי' <i>ביטול</i> החושך הוא ע\"י גילוי עצם האור שלמעלה מהאור שלהאיר את העולמות, דאור זה אין העולם מעלים לגבי'. וזהו מ\"ש במדרש<sup data-n=\"1341\">42</sup> שהגאולה העתידה היא דוגמת אור היום שאין שייך בו כיבוי, דיש לומר שהכוונה בזה היא להאור שלמעלה משייכות לעולמות, שאין שייך העלם לגבי'.\nט) <b>וצריך</b> להבין, דלכאורה, כיון שמצד האור דלהאיר את העולמות אי אפשר שיתבטל החושך (ורק שנדחה מפני האור), וזה שבגאולה העתידה יתבטל חושך הגלות, הוא מפני שאז יהי' גילוי אור חדש שלמעלה משייכות לעולמות, הריהעולם עצמו (כמו שהוא מצד הגדרים שלו, כולל גם הגילויים השייכים לעולם) יהי' נשאר בגלות ח\"ו. ונקודת הביאור בזה, דמהטעמים<sup data-n=\"1342\">43</sup> על זה שהבריאה היתה באופן שבתחלה נמצא האור שלמעלה משייכות לעולמות וממנו דוקא נמשך האור דלהאיר את העולמות (אף שלכאורה הי' צריך להיות מלכתחילה המשכת האור ששייך לעולמות), הוא, בכדי שהאור השייך לעולמות יהי' בו (בהעלם עכ\"פ) מהאור שלמעלה משייכות לעולמות. ועפ\"ז מובן, דהגם שביטול חושך הגלות יהי' ע\"י גילוי עצם האור שלמעלה מהאור דלהאיר את העולמות, מ\"מ תהי' הגאולה (גם) בגדרי העולם, כי גילוי עצם האור שיהי' בגאולה העתידה יאיר בגילוי גם בהאור שלהאיר את העולמות, ועי\"ז – בהעולם.\n<b>ועפ\"ז</b> יש לבאר השייכות דהענינים שבהמאמר לביטול חושך הגלות, דזה שמאריך בהמאמר בענין התכללות האור במקורו, יש לומר, שהוא מפני שביטול חושך הגלות הוא ע\"י גילוי אור הכלול (כנ\"ל סעיף ח). וזה שמבאר שטבע הרצוא וההתכללות הוא גם בהאור שבגדר התלבשות וגם בהאור המלובש בכלים, הוא, כי בכדי שביטול חושך הגלות (שמצד גילוי אור הכלול) יהי' בגדר העולם, הוא ע\"י שענין התכללות האור במקורו הוא גם בהאור המלובש בכלים.\nיו\"ד) <b>וזהו</b> קץ שם לחושך, דיש לומר, שפירוש תיבת קץ בפסוק זה הוא (גם) קץ (וגבול) לראשיתו<sup data-n=\"1343\">44</sup>. היינו, שענין החושך יש לו נתינת מקום רק בהאור שלהאיר את העולמות, ולא בעצם האור. ונאמר קץ <i>שם</i> לחושך (דזה שיש קץ לחושך הוא מפני ששם לו קץ, אבל מצד עצמו אין לו קץ), כי זה שהחושך אין לו נתינת מקום בעצם האור <i>שאינו</i> בגדר עולמות, אין זה שייך להעולם. וכיון שמצד הגדר דעולם אין לו קץ בראשו (כיון שיש לו נתינת מקום בכל הדרגות השייכים לעולמות), הרי גם הקץ שבסופו, מה שלע\"ל יתבטל החושך, לא יהי' ח\"ו בגדר העולם. ולכן קץ שם לחושך, קץ בראשו, שהאור שאינו בגדר עולמות, ששם אין נתינת מקום לחושך, יהי' שייך להעולם<sup data-n=\"1344\">45</sup>. ועי\"ז, גם הקץ שבסופו, ביטול החושך שיהי' בגאולה העתידה, יהי' בהעולם בפנימיותו. דהגם שביטול החושך שיהי' לע\"ל הוא ע\"י שיהי' אז גילוי אור חדש שלמעלה משייכות לעולמות, מ\"מ, יהי' העולם כלי גם לאור זה, ועי\"ז תושלם הכוונה דדירה לו ית' בתחתונים<sup data-n=\"1345\">46</sup>, שהתחתון (מצד הגדרים שלו) יהי' דירה לו ית', לו לעצמותו<sup data-n=\"1346\">47</sup>.\n**********",[["1299","*","יצא לאור ב<b>קונטרס חמשה עשר באב – תנש\"א</b>, \"לקראת חמשה עשר באב . . <i>ה' ואתחנן יד מנ\"א</i>,<i> ה'תנש\"א</i>\"."],["1300","1","איוב כח, ג."],["1301","2","ב\"ר פפ\"ט, א."],["1302","3","ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480287\" data-slug=\"or-hatorah-hb\" data-id=\"8316480287\">אוה\"ת מקץ שלט, ב</a>. וראה גם אוה\"ת שם (כרך ה) תתקעה, א."],["1303","4","ח\"א קצד, א."],["1304","5","קהלת ג, א."],["1305","6","ראה קהלת שם ג, א ואילך."],["1306","7","<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא פי\"ב (יז, א</a>). חובת הלבבות שער יחוד המעשה פ\"ה."],["1307","8","תוד\"ה ה\"ג ונאמר פסחים קטז, ב ממכילתא עה\"פ בשלח טו, א. יל\"ש ומדרש תהלים שבהערה הבאה. ועוד."],["1308","9","יל\"ש עה\"פ (ישעי' ס, א) קומי אורי. מדרש תהלים עה\"פ (תהלים לו, י) כי עמך מקור חיים גו' – הובא ונתבאר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480138\" data-slug=\"or-hatorah-hb\" data-id=\"8316480138\">אוה\"ת</a> (יהל אור) לתהלים שם (ס\"ע קלח). סה\"מ ה'תש\"ח ע' 153 ואילך. ועוד."],["1309","10","כ\"ה הלשון (\"<i>שייך</i> כיבוי\") בסה\"מ ה'תש\"ח שם ע' 167.\nולהעיר מזה שאילו זכו, גם הגאולות שנמשלו לאור הנר היו באופן דנצחיות (ראה פרש\"י עה\"פ בשלח טו, יז. מגלה עמוקות אופן קפה. ועוד (בנוגע להגאולה דיצי\"מ). פרש\"י עה\"פ יחזקאל מג, יא – הובא בפתיחת התויו\"ט למס' מדות (בנוגע להגאולה מגלות בבל))."],["1310","11","ראה אוה\"ת שבהערה 9, שהגילוי יהי' מבחינת \"אתר דלא אשתני'\". וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380657\" data-slug=\"likkutei-torah\" data-id=\"4001380657\">לקו\"ת מטות פג, ד</a>. ובכ\"מ."],["1311","12","ומ\"ש קץ שם לחושך, שמזה משמע, דזה שלא יהי' שייך אז גלות הוא (לא מפני <i>שהאור</i> דגאולה העתידה הוא אור בלתי מוגבל, אלא) מפני <i>שהחושך</i> יש לו קץ – ראה לקמן סעיף יו\"ד."],["1312","13","משלי ו, כג."],["1313","14","דנוסף לזה שתורה בכלל היא אור, ובפרט פנימיות התורה* – ע\"י הלימוד בענין האור נעשה ענין זה עוד יותר."],["1314","15","בשנת עדר\"ת – המשך תער\"ב ח\"א ס\"ע תקסד ואילך. ולהעיר, שלכאורה, הענינים שבמאמר זה אינם שייכים כ\"כ להענינים דהמאמרים שלפניו ושלאחריו."],["1315","16","וראה לקמן סעיף ח, שגם פרטי הענינים דאור המבוארים במאמר שייכים לדחיית וביטול הגלות."],["1316","17","ראה מגילה ה, רע\"ב. סה\"ש קיץ ה'ש\"ת ע' 157. לקו\"ש חל\"ג ע' 156 ואילך."],["1317","18","ולהעיר גם ממ\"ש בסיום המאמר (המשך הנ\"ל ע' תקעא) דבאור אין שייך ענין הגלות."],["1318","19","נעתק לקמן סעיף ד."],["1319","20","סה\"מ תרס\"ט ע' טז. וראה גם המשך תרס\"ו ע' תסד. סה\"מ ה'ש\"ת ע' 12. ובכ\"מ.\n*) <i>דבתורה עצמה</i>,<i> גליא דתורה הוא </i>\"<i>שלמה</i>\"<i> ופנימיות התורה היא </i>\"<i>אור</i>\"<i> – אוה\"ת (יהל אור) לתהלים ע' שצח</i>.<i> סה\"מ ה'ש\"ת ע' 68</i>.<i> ובכ\"מ</i>."],["1320","21","וכמו אור השמש, שמהאור יודעים רק שהשמש הוא מציאות ספירי ובהירי, אבל אין יודעים אופן הבהירות שלו (המשך תרס\"ו שם. ועוד)."],["1321","22","הובא במאמר הנ\"ל (המשך תער\"ב שם ע' תקסז) ובכ\"מ. וראה בהמצויין בכתר שם טוב (הוצאת קה\"ת) הוספות סי' לח (בהוצאת תשנ\"ט סי' מח)."],["1322","23","ישעי' ו, ב."],["1323","24","ראה כש\"ט סי' ערה (לו, א). לקו\"ד כרך א קיג, ב. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081359\" data-slug=\"likkutei-sichot\" data-id=\"1300081359\">לקו\"ש ח\"ח ע' 348</a> בהערות הראי' על זה מעירוב תחומין דבמקום שדעתו שם, שם הוא מקומו (ראה שו\"ע אדה\"ז או\"ח הל' שבת סת\"ח: לפי שדעתו של אדם כו'). ובירושלמי ברכות ספ\"ו: הסיע דעתו כמו שהוא שינוי מקום."],["1324","25","פרדס שער כ (שער השמות) רפ\"א ורפ\"ד. ובכ\"מ."],["1325","26","ראה גם המשך תרס\"ו ע' קפה."],["1326","27","ראה סידור (עם דא\"ח) ד\"ה מזמור לתודה (מד, ג) – הובא בהמשך תער\"ב שם פרע\"ט (ע' תקסו). וראה ד\"ה ברוך שעשה נסים ה'תשט\"ו סעיף ג ואילך (לעיל ח\"ב ע' קח ואילך)."],["1327","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה</a> בהגהה – הובא בהמשך תער\"ב שם. ובהמשך תער\"ב שם שהביטול דאין זולתו הוא הביטול דכולא קמי' כלא חשיב."],["1328","29","וראה לקמן סעיף ה ובהערה 35."],["1329","30","ראה ד\"ה וידבר גו' זאת חוקת ה'תשכ\"ט סעיף ט (לעיל ע' כט)."],["1330","31","סה\"מ תרס\"ט ע' קנא. וראה גם שם ע' סט."],["1331","32","סה\"מ שם ע' סט."],["1332","33","ומפני שיודע שהדבר בעצם הוא אמת ע\"פ יסוד האמונה החזקה שבו אינו ירא לנפשו להעמיק בזה ביותר ואינו מגביל את כח שכלו לעיין ולחפש ולשקול כל דבר עד שיבוא על אמיתית הדבר (סה\"מ שם ע' קנא)."],["1333","34","לקו\"ת צו יג, ריש ע\"ד. סהמ\"צ להצ\"צ כג, ב. ובכ\"מ."],["1334","35","ואולי יש לומר, דכיון שהמשכת הביטול דאמונה בהמציאות היא בשביל האמונה, היינו שגם ענינה (הפנימי) דהמציאות הוא ביטול – החילוק שבין הביטול דאמונה שמתלבשת בשכל והביטול דאמונה שלמעלה מהשכל הוא רק בחיצוניות.\nולהעיר מסה\"מ תרס\"ט שם ריש ע' קנב בענין מעלה ומטה שבעיגולים [שעל זה בא המשל דשתי הדרגות שבאמונה] \"דעם היות שהמעלה אינו בהתלבשות כלל והמטה בא בהתלבשות, שוים המה בעצם\"."],["1335","36","פי\"ט."],["1336","37","ראה לעיל סעיף ד שהרצוא ליכלל הוא בכתר. ובתניא שם, שרצון זה הוא בבחינת חכמה שבנפש. וראה המשך תער\"ב פ' רפב (ס\"ע תקע)."],["1337","38","המשך תער\"ב שם (ע' תקע)."],["1338","39","ראה סה\"מ תרע\"ט ע' שיב בענין רעותא דלבא ומס\"נ. ושם, שרעו\"ד הוא \"אור הנשמה\" וכח המס\"נ הוא \"כח הנשמה\"."],["1339","40","ראה המשך תער\"ב ח\"ב ס\"ע תתקלד ואילך."],["1340","41","ע\"ח שער יא (שער עגולים ויושר) ענף ב. אוצרות חיים ומבוא שערים בתחלתם."],["1341","42","הובא לעיל סעיף ב."],["1342","43","ראה בארוכה לעיל ח\"ג ע' של ואילך."],["1343","44","ראה פירוש הראב\"ע לתהלים קיט, צו \"קץ בלשוננו פעם ראש ופעם סוף\". וראה המשך תרס\"ו ע' כ כמה הוכחות שגם ההתחלה והראש נק' קץ."],["1344","45","ועפ\"ז יומתק לשון המדרש (הובא בתחלת המאמר), \"זמן נתן <i>לעולם</i> כמה שנים יעשה באפילה\" – ולא \"זמן נתן <i>לאפילה</i> כמה שנים תהי' בעולם\", כלשון הכתוב \"קץ שם <i>לחושך</i>\" – כי ענין קץ שם לחושך הוא שהקץ דחושך יהי' (גם) מצד העולם."],["1345","46","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["1346","47","המשך תרס\"ו ס\"ע ג. ובכ\"מ – נסמן לעיל ח\"ב ע' שח."]]],[1500390020,"<h3>בס\"ד, ש\"פ דברים (ת\"ב, נדחה) תשל\"א<sup data-n=\"1347\">*</sup>.</h3>\n<b>איכה</b> ישבה בדד העיר רבתי עם גו' ומבאר<sup data-n=\"1348\">1</sup> כ\"ק אדמו\"ר הצמח צדק (צמח שמו<sup data-n=\"1349\">2</sup>) שישבה בדד הוא כמש\"נ<sup data-n=\"1350\">3</sup> הוי' בדד ינחנו, בטח בדד עין יעקב. וזה נעשה ע\"י רבתי עם כו' כמשי\"ת לקמן. וצריך להבין והרי איכה הוא לשון תמי' ופליאה, ולפי הפירוש שישבה בדד הוא שישראל יתעלו לבחינת הוי' בדד ינחנו, בחינת בדד (מחוץ למחנה – למעליותא) למעלה מהשתלשלות, מהי התמי' והפליאה בזה. גם צריך להבין קישור פירוש זה עם פירוש הפשוט, דפירוש הפשוט באיכה ישבה בדד הוא גודל הירידה כו', שלכן קוראין איכה בת\"ב שאז הי' החורבן, ומהו הקישור של פירוש הפשוט עם פירוש הצ\"צ שישבה בדד הוא למעליותא. ויובן זה בהקדים תחלה גודל העילוי (לפי פירוש הצ\"צ עה\"פ) בישבה בדד, שהו\"ע בטח בדד עין יעקב. שהדיוק בטח בדד עין יעקב (יעקב דוקא) הוא כמרז\"ל<sup data-n=\"1351\">4</sup> לא כאברהם שכתוב בו הר כו' ולא כיצחק שכתוב בו שדה כו' אלא כיעקב שקראו בית. והיינו שהעילוי דבטח בדד עין יעקב שיהי' לע\"ל, ובפרט בביהמ\"ק השלישי, הוא ענין כיעקב שקראו בית, שנחלת יעקב היא נחלה בלי מצרים<sup data-n=\"1352\">5</sup>, בחי' רעוא דרעוין, כמרז\"ל<sup data-n=\"1353\">6</sup> כל המענג את השבת נותנין לו נחלה בלי מצרים כו' נחלת יעקב כו'. ועילוי זה שיהי' לעתיד הוא ע\"י קדימת ישבה בדד דהגלות כו'. וזהו\"ע מה שדימו רז\"ל<sup data-n=\"1354\">7</sup> את ענין הגלות לזה שאדם הראשון נידון בגרושין [דכמו שאדה\"ר הוא יציר כפיו של הקב\"ה, כן גם ישראל (שנידונו בגרושין) הם נצר מטעיו מעשה ידיו של הקב\"ה<sup data-n=\"1355\">8</sup>, חלק אלקה ממעל ממש<sup data-n=\"1356\">9</sup>], וכמו זה שאדה\"ר נידון בגרושין הוא בשביל העילוי שיהי' אח\"כ, עד העילוי דמתן תורה שזה נעלה עוד יותר מהעילוי דויניחהו בג\"ע לעבדה ולשמרה דאדה\"ר (כמשי\"ת לקמן), והיינו כמו שבמתן תורה היו ז' הדורות שסילקו השכינה ממטלמ\"ע ואח\"כ ז' הדורות שהמשיכו השכינה מלמעלמ\"ט עד שהי' מתן תורה<sup data-n=\"1357\">10</sup>, עד\"ז הואגם לאחרי מתן תורה שהי' צריכים לבוא לארץ ישראל<sup data-n=\"1358\">11</sup> ולבנות הביהמ\"ק, המקום אשר יבחר הוי'<sup data-n=\"1359\">12</sup>, שלמעלה גם מהמשכן דכתיב בי' ואתהלך באהל<sup data-n=\"1360\">13</sup>, היו אז כמה הרפתקאות וכו' עד שנבנה ביהמ\"ק, ואח\"כ הי' החורבן דבית ראשון ובאו להעילוי דבית שני, שלמעלה מבית ראשון וכמ\"ש<sup data-n=\"1361\">14</sup> גדול יהי' כבוד הבית הזה האחרון מן הראשון דקאי על בית שני שהי' גדול מבית ראשון בבנין ובשנים<sup data-n=\"1362\">15</sup>, ועד\"ז הוא גם בענין החורבן דבית שני, שיגיעו לאח\"ז להעילוי דבית השלישי שיבנה בקרוב ממש ע\"י משיח צדקנו, שהוא נעלה מבית ראשון וגם מבית שני, וכמחז\"ל (שהובא לעיל) לא כאברהם שכתוב בו הר ולא כיצחק שכתוב בו שדה אלא כיעקב שקראו בית. וזהו ג\"כ ההמשך בכתוב היתה כאלמנה ולא אלמנה ח\"ו<sup data-n=\"1363\">16</sup>, כי מכיון שהכוונה בהירידה היא בשביל העלי' שתהי' לאח\"ז, הרי אי\"ז ירידה אמיתית, ולכן היתה כאלמנה בכ\"ף הדמיון.\nב) <b>והענין</b> הוא, כמו שמבאר כ\"ק אדמו\"ר (מהורש\"ב)<sup data-n=\"1364\">17</sup> שתכלית כוונת הבריאה הוא שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים, שכוונה זו נשלמה ע\"י העבודה דנש\"י, כמאמר במי נמלך (על כל הבריאה כולה) בנשמותיהם של צדיקים<sup data-n=\"1365\">18</sup>. והנה בתחילת הבריאה עולם על מילואו נברא<sup data-n=\"1366\">19</sup>, עיקר שכינה בתחתונים היתה<sup data-n=\"1367\">20</sup>, שפירוש עיקר שכינה הוא בחי' אור הסובב. דשכינה הוא בחי' אור הממלא, שכינה ע\"ש ששוכנת ומתלבשת<sup data-n=\"1368\">21</sup>, אבל עיקר שכינה הוא בחי' אור הסובב ועד לאור הסובב שלמעלה מעולמות, וכמבואר בארוכה בהמשך מאמרי ההילולא<sup data-n=\"1369\">22</sup>. והגם שהמשכת אור הסובב נעשה ע\"י עבודת אדה\"ר ונש\"י דוקא כנ\"ל, מ\"מ הנה מיד בתחילת הבריאה עולם על מילואו נברא, פירוש (לא שהי' המשכת עיקר שכינה בפועל, שהרי זה נעשה ע\"י עבודה דוקא<sup data-n=\"1370\">23</sup>, כ\"א) שנברא באופן שיהי' מוכשר וראוי לגילוי אור דעיקר שכינה, וההמשכה בפועל היא ע\"י העבודה דוקא. וזהו\"ע ויניחהו בג\"ע לעבדה ולשמרה, שע\"י עבודת אדה\"ר נעשה תוספות אור בהג\"ע. דג\"ע מצד עצמו הוא בחי' אור הממלא (ומה שעולם על מילואו נברא הוא רק שהי' מקום מוכשר לגילוי אור הסובב, כנ\"ל), אלא שבבחי' אור הממלא גופא יש מעלה בג\"עעל כללות העולם בב' דברים, הא' שהאור המתלבש בעולמות הוא מבחי' ז\"ת ובג\"ע מאיר ג\"ר והב' דבעולמות רק ידיעת המציאות ובג\"ע גילוי המהות, אבל כ\"ז הוא רק בחי' ממכ\"ע. ויניחהו בג\"ע לעבדה ולשמרה, שעי\"ז ימשיך בחי' אור הסובב, בחי' עיקר שכינה. אמנם, גם בחי' לעבדה שהי' בג\"ע אינו בערך להעבודה דלאחרי מתן תורה, וכמרז\"ל<sup data-n=\"1371\">24</sup> בענין מצות האבות, שריחות היו. ואף שאמרו זה בנוגע להאבות, הרי כיון דעד מתן תורה הייתה הגזירה דעליונים לא ירדו למטה ותחתונים לא יעלו למעלה כו'<sup data-n=\"1372\">25</sup> – הרי גם בנוגע לאדה\"ר הי' כן. ואף שנצטווה (ולכן הי' בו המעלה דמצווה ועושה) – עכ\"פ בשש מצות – הציווי כמו שהוא למטה קודם מתן תורה אינו כמו הציווי לאחר מתן תורה כיון שהעליונים לא ירדו עדיין למטה. וגם לפי המבואר בהמאמר שם שעבודת אדה\"ר היתה נעלית יותר מעבודת האבות, כי אדה\"ר הי' יציר כפיו ובג\"ע<sup data-n=\"1373\">26</sup> כו' מ\"מ הרי (כמבואר בהמאמר שם) אי\"ז בערך לבחי' שמן תורק שמך, המשכה עצמית דמתן תורה. אמנם, גם העבודה שלאחרי מתן תורה אינה בערך להגילוי שהי' בביהמ\"ק (ובפרט ע\"י לעבדה ולשמרה שבביהמ\"ק), המקום אשר יבחר הוי', שאז דוקא נעשה דירה לו ית', דירת קבע. ובביהמ\"ק גופא גדול הענין דדירה לו ית' בבית שני, כי אף שבבית שני חסרו ה' דברים<sup data-n=\"1374\">27</sup> מ\"מ גדול כו' מבית הראשון בבנין (מקום) ובשנים (זמן) – הגדרת התחתונים – מצד העולם גופא. אמנם עיקר הדירה יהי' לע\"ל דוקא, ע\"י התומ\"צ שיקיימו אז, שאז יהי' קיום המצות בתכלית השלימות, כמאמר<sup data-n=\"1375\">28</sup> ושם נעשה לפניך כמצות רצונך, שם דוקא, וכמו שמבאר בארוכה כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"1376\">29</sup>.\nג) <b>והנה</b> גודל העילוי שיהי' לע\"ל יובן מגודל הפלאת העבודה שבזה\"ג שלפני זה – הכנה והקדמה לזה<sup data-n=\"1377\">30</sup>. דהנה ידוע<sup data-n=\"1378\">31</sup> מאמר כ\"ק אדמו\"ר הזקן בשם הבעש\"ט עה\"פ<sup data-n=\"1379\">32</sup> כן בקודש חזיתיך הלואי בזמן הבית חזיתיך, וכידוע<sup data-n=\"1380\">33</sup> בפי' והאיש משה עניו מאד מכל האדם אשר על פני האדמה<sup data-n=\"1381\">34</sup>, שביותר הוא כשראה משה את הדור דעקבתא דמשיחא, שיהיו אז ריבוי העלמות והסתרים וכו' ובכל זה ילמדו תורה ויקיימו מצות ובאופן דמוסיף והולך מוסיף ואור, הנה עבודה זו פעלה ענוה וביטולאצל משה. ומשה אמת<sup data-n=\"1382\">35</sup> וארז\"ל<sup data-n=\"1383\">36</sup> מדת אמת ראה, הרי מובן מזה, שכ\"ה באמת, שישנה מעלה בהעבודה דזה\"ג<sup data-n=\"1384\">37</sup> לגבי עבודת משה. ומזה מובן גודל העילוי שיהי' לע\"ל, מכיון שהגילוי יהי' לאחרי וע\"י עבודה נעלית כזו. ובזה יובן ג\"כ הטעם לאריכות הגלות הזה, כי מכיון שגלות זה הוא הקדמה לגילוי נעלה ביותר, שלמעלה יותר מויניחהו בג\"ע דאדה\"ר, ממתן תורה, מבית ראשון ומבית שני, לכן הגלות הוא באריכות גדולה כזו, בכדי שע\"י עבודת בנ\"י במשך זמן הגלות יגיעו בקרוב ממש לבית השלישי, שהוא גילוי נעלה ביותר, בטח בדד עין יעקב, נחלה בלי מצרים.\nד) <b>והנה</b> בכדי שבחינת בדד יומשך למטה ובאופן דישבה – התיישבות, צריכה להיות ההמשכה בהמדריגות דסדר השתלשלות. וזהו מ\"ש איכה ישבה בדד, שהמשכת בחי' בדד למטה, ובאופן דישבה (בהתיישבות), הוא ע\"י איכה. דהנה א' רומזת לכמה דרגות זעג\"ז. וכמו א' דאחד – א' שלמעלה מח' וד', ז\"ר וארץ וד' רוחות העולם – א' – אלופו של עולם, אבל א' דאיכה, א' למעלה מי' – למעלה מענין ע\"ס, (וי\"ל למעלה גם מע\"ס הגנוזות<sup data-n=\"1385\">38</sup>), והאל\"ף, נמשך בהיו\"ד (שבאיכה) הרומז לע\"ס דאצילות, ואח\"כ – ב\"כה\" (דאיכה) שקאי על בחי' המלכות ובפרט – מל' כמו ששייכת כבר או גם – כמו שירדה ומתלבשת בבי\"ע<sup data-n=\"1386\">39</sup>. וכידוע<sup data-n=\"1387\">40</sup> ההפרש שבין זה לכה, שזה הו\"ע מראה באצבעו ואומר זה, ועד\"ז הוא גם לשון זאת (שהיא ג\"כ ע\"ד בחי' זה, אלא שזאת הוא בחי' נוקבא<sup data-n=\"1388\">41</sup>), שהוא בחי' המלכות כמו שהיא באצילות<sup data-n=\"1389\">42</sup>, ובחי' כה הוא בחי' המלכות ובפרט – כמו שהיא מתלבשת בבי\"ע, בחי' כדמותנו. וזהו\"ע איכה ישבה בדד, שבדד הוא בחי' יחיד שלמעלה גם מבחי' אחד, כי האל\"ף דכאן (דאיכה) הוא – אחד ואין שני גם בן ואח אין לו<sup data-n=\"1390\">43</sup>, בחי' עתיק שאין בו התחלקות כלל, וכידוע בקבלה<sup data-n=\"1391\">44</sup> שזווג (מ\"ד ומ\"ן) שבעתיק הוא מיני' ובי', הנה לע\"ל יומשך גם בחי' בדד בגילוי למטה ובהתיישבות<sup data-n=\"1392\">45</sup>.\nה) <b>והנה</b> ידוע תורת הרב המגיד<sup data-n=\"1393\">46</sup> שבדד ב' דלתי\"ן. ד' דמשפיע וד' דמקבל. ולכאורה, הרי דל\"ת הוא ענין דלות, דלותי, ואיך שייך דל\"ת דמשפיע.ומבואר שם שהוא כמרז\"ל<sup data-n=\"1394\">47</sup> יותר משהעגל רוצה לינק הפרה רוצה להניק, והיינו שיש כוסף ותשוקה בהמשפיע להשפיע להמקבל, וזהו דל\"ת דהמשפיע. ואולי יש לקשר זה עם משנ\"ת בענין למעשה ידיך תכסוף. והנה כמו שרצון (הדל\"ת) דהמשפיע הוא שיתמלא חסרון דהמקבל, כן רצון (דל\"ת) המקבל צ\"ל שיתמלא החסרון, כביכול, דהמשפיע, וכידוע בפירוש הרב המגיד במשנה אין עומדין להתפלל אלא מתוך כובד ראש<sup data-n=\"1395\">48</sup>, שהתפלה צריכה להיות על הכובד ראש שלמעלה, ששכינה אומרת<sup data-n=\"1396\">49</sup> קלני מראשי קלני מזרועי. וכן משמע פירוש הבעש\"ט<sup data-n=\"1397\">50</sup> עה\"פ<sup data-n=\"1398\">51</sup> <i>זאת</i> אשיב אל לבי על כן אוחיל, זאת – השכינה.\nו) <b>וזהו</b> איכה ישבה בדד העיר רבתי עם גו', איכה בתמי' – דישראל שהיו בדרגת עם, גחלים עוממות כו'<sup data-n=\"1399\">52</sup>, ורבתי עם (כפשוטו) ריבוי ההתחלקות כו' ורבתי בדיעות<sup data-n=\"1400\">53</sup> ריבוי הדיעות, ד\"ע וד\"ת<sup data-n=\"1401\">54</sup>. דהנה כתיב<sup data-n=\"1402\">55</sup> כי א-ל דיעות הוי' (דיעות לשון רבים<sup data-n=\"1403\">56</sup>), וידוע תורת אדמו\"ר הזקן<sup data-n=\"1404\">57</sup> שצ\"ל מתאחדים יחד ולמעלה מזה – שמעלה ומטה שווין, א-ל דיעות הוי' – שכולל ב' הדיעות יחד, הנה היא רבתי בדיעות, ד\"ע וד\"ת ובכמה אופנים. היתה כאלמנה – שבעלה הלך למדינת הים<sup data-n=\"1405\">58</sup>, ענין בעלה – באתכסיא, רבתי בגוים הו\"ע ההתלבשות בעניני ע' אומות כו', שרתי במדינות – גם כח ההתנשאות והתוקף הוא – במדינות<sup data-n=\"1406\">59</sup> הייתה למס. אבל כ\"ז הוא לעילוי': שרתי אותיות תשרי, שאז בנין המלכות להיות שרתי במדינות<sup data-n=\"1407\">60</sup>, היתה למס הוא הביטול דקב\"ע, שדוקא בזמן ההעלם וההסתר, כשהיא רבתי עם גו' שרתי במדינות, הנה אז דוקא הוא הביטול דקב\"ע, שהיתה למס, אשר אינו מציאות לעצמו והוא רק למס. וכידוע שהעבודה בזה\"ג ובפרט בעקבתי' דמשיחא הוא לא בבחי' המוחין ולא בבחי' המדות כ\"א העבודה דקב\"ע (וכנ\"ל בפי' האיש משה עניו). ועי\"ז דוקא נעשה ישבה בדד, גילוי בחי' בדד שלמעלה מהשתלשלות, יחיד, שלמעלה גםמע\"ס הגנוזות – באופן דישבה. וכביאור כ\"ק אדמו\"ר האמצעי<sup data-n=\"1408\">61</sup> בפירוש אנת הוא חד ולא בחושבן, שהוא למעלה גם מע\"ס הגנוזות. ובזה יובן תיווך ב' הפירושים באיכה ישבה בדד, פירוש הפשוט ופירוש הצ\"צ שקאי על העילוי והגילוי דבחי' בדד, כי הגילוי דבחי' בדד שלמעלה מהשתלשלות הוא ע\"י העבודה דקב\"ע שבזמן הגלות דוקא, כנ\"ל. וזהו איכה ישבה בדד גו' איכה לשון תמי' ופליאה, שיבוא מרבתי עם, עוממות ורבתי בזה וכו' לבדד שלמעלה מהשתלשלות ובאופן דישבה הו\"ע של פליאה. (ועוד י\"ל שהגילוי והתיישבות דבחי' בדד שלמעלה מהשתלשלות, ה\"ז שלא ע\"פ השתלשלות, למעלה מטו\"ד<sup data-n=\"1409\">62</sup>. ולכן גם העבודה שעי\"ז יומשך הגילוי דבחי' בדד, הו\"ע עבודת התשובה<sup data-n=\"1410\">63</sup>, שענין התשובה הוא העבודה שלמעלה מהשתלשלות בנפש האדם).\nז) <b>והנה</b> השייכות דבחי' בדד, בחי' יחיד, ליעקב דוקא (כמ\"ש בטח בדד עין יעקב) הוא, כי הנה נת\"ל שבדד הוא בחי' עתיק, שלמעלה מב' הקוין ימין ושמאל, וכמאמר<sup data-n=\"1411\">64</sup> ולית שמאלא בהאי עתיקא, ולכן גילוי בחי' זו הוא ע\"י העבודה בקו השלישי דוקא. וכמ\"ש ציון במשפט תפדה ומפרש כ\"ק אדמו\"ר הצמח צדק<sup data-n=\"1412\">65</sup> שהמשפט הוא דוקא בשלשה<sup data-n=\"1413\">66</sup> כו' דהיינו חג\"ת. והיינו שעשיית הדירה לו ית' ובאופן של שלימות הוא ע\"י העבודה בכל ג' הקוין דוקא, וכביאור כ\"ק מו\"ח אדמו\"ר במשנה על שלשה דברים העולם עומד<sup data-n=\"1414\">67</sup>, שע\"י העבודה בג' הקוין, תורה עבודה וגמ\"ח, העולם עומד, שנשלמה הכוונה דבריאת העולם. וזהו ג\"כ ענינו של בית השלישי, קו השלישי, בחי' נחלה בלי מצרים דיעקב, שבו תהי' (גם) ההתכללות דבית ראשון ובית שני<sup data-n=\"1415\">68</sup>. וזה יהי' למעלה גם מכמו שהי' בג\"ע מקדם, היינו גם מכמו שהי' בג\"ע קודם החטא<sup data-n=\"1416\">69</sup>, וכידוע בענין אדם ומשיח, שאדם הוא ר\"ת אדם דוד משיח<sup data-n=\"1417\">70</sup>, והצירוף הוא בסדר אד\"ם – שמורה על סדר וכו' משא\"כ במשיח כתיב<sup data-n=\"1418\">71</sup> הנה ישכיל עבדי ירום ונשא וגבה מאד, מאד אותיות אדם, אבל בצירוף המורה על בל\"ג, היפך ענין הציור דאדם.\nח) <b>והנה</b> כאמור לעיל הגילוי דלעתיד ממשיכים ע\"י העבודה עכשיו דוקא. שמזה מובן שישנה מעלה בהעבודה דעכשיו גם על הגילוי דלעתיד, וכמו שמבארכ\"ק אדמו\"ר מהר\"ש בפירוש המשנה<sup data-n=\"1419\">72</sup> יפה שעה אחת בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב, דמאחר שהעבודה בתשובה ומע\"ט בעוה\"ז הוא הגורם לחיי עוה\"ב (כולל גם הגילויים דלעתיד) הרי בהכרח שיש מעלה בהעבודה דעוה\"ז על הגילויים דלעתיד, כי דבר הגורם הוא חזק יותר מהדבר שנעשה על ידו. וגם בענין התענוג, שבחי' נחלה בלי מצרים דיעקב הוא בהזמן דרעוא דרעוין (ענין התענוג), יש מעלה בהעבודה דעכשיו דוקא, וכמו שמבאר שם לפני זה<sup data-n=\"1420\">73</sup> שהתענוג דלעתיד הוא (בכללות) נח\"ר דהנברא והתענוג דתשובה ומע\"ט בעוה\"ז הוא (בכללות) נח\"ר דהבורא, נח\"ר לפני<sup data-n=\"1421\">74</sup> שאמרתי ונעשה רצוני.\n<b>וזהו</b> שע\"י מעשינו ועבודתנו דעכשיו ממשיכים שבקרוב ממש יבנה ויתגלה<sup data-n=\"1422\">75</sup> בית השלישי, בחי' בטח בדד עין יעקב, שתהי' בו גם ההתכללות דבית ראשון ובית שני ואז הוי' בדד ינחנו (לכאו\"א מבנ\"י) אע\"פ (וע\"י) שימצאהו בארץ מדבר ובתוהו גו' (עבודה בזה\"ג) ויבוא מהמדבר לבדד ינחנו באופן דכתיב לעיל מיני' כנשר יעיר קנו, ברחמים ובחמלה – שבקרוב ממש תבוא הגאולה בחסד וברחמים, ותהי' אז שלימות הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים.\n**********",[["1347","*","יצא לאור בשעתו, \"<i>ט\"ו מנחם אב</i>,<i> עש\"ק נחמו</i>,<i> ה'תשל\"א</i>\"."],["1348","1","בתוכן המאמר – ראה רשימות הצ\"צ לאיכה (ע' ה', יג (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650052\" data-slug=\"or-hatorah-hb\" data-id=\"8316650052\">אוה\"ת נ\"ך ח\"ב ע' א'לד</a>. א'מב) ועוד). ד\"ה איכה ישבה עת\"ר לכ\"ק אדמו\"ר נ\"ע (נדפס ברשימות שם ע' נב. סה\"מ עת\"ר ע' ריג ואילך)."],["1349","2","צמח (צדק) בגימטריא מנחם (מענדל) חושבני' דהדין כחושבנא דהדין הוא צמח הוא מנחם ודא מסייעא להו כו' (ירושלמי ברכות פ\"ב ה\"ד)."],["1350","3","דברים לב, יב. שם לג, כח."],["1351","4","פסחים פח, א."],["1352","5","משא\"כ ביהמ\"ק הא' והב' – ג\"כ נחלה (מכילתא בשלח טו, יז. זבחים קיב, ב. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670035\" data-slug=\"or-hatorah-hb\" data-id=\"8158670035\">אוה\"ת ויצא קפו, א</a>), אבל דת\"י ות\"ך שנים (יומא ט, א)."],["1353","6","שבת קיח, סע\"א ואילך."],["1354","7","פתיחתא דאיכ\"ר ד (עה\"פ והמה כאדם)."],["1355","8","סנה' ר\"פ חלק."],["1356","9","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. וראה הערות הצ\"צ שם (נדפסו בס' קיצורים והערות לס' לקו\"א)."],["1357","10","ב\"ר (פי\"ט, ז) כו'. שהש\"ר (רפ\"ה. נת' בד\"ה באתי לגני השי\"ת) – ובמ\"כ שם דקאי על מ\"ת."],["1358","11","וכמש\"נ בפרשתנו (א, ב): מחורב גו' (ובפרש\"י שם). הלכתם כו' למהר ביאתכם לארץ."],["1359","12","דברים יב, יא: בית הבחירה בירושלים (פרש\"י)."],["1360","13","שמואל-ב ז, ו. שהש\"ר פ\"א, טז (ג)."],["1361","14","חגי ב, ט."],["1362","15","ב\"ב ג, סע\"א ואילך."],["1363","16","סנהדרין קד, סע\"א. איכ\"ר פ\"א, ג. וראה רשימות הצ\"צ שם ע' יט (אוה\"ת שם ע' א'מד-ה)."],["1364","17","ד\"ה איכה עת\"ר הנ\"ל."],["1365","18","ראה רות רבה פ\"ב, ג. סד\"ה כי עמך מקו\"ח ש\"ת (סה\"מ ה'ש\"ת ע' 17 ואילך)."],["1366","19","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["1367","20","ב\"ר פי\"ט, ז. וש\"נ."],["1368","21","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a>). וראה שם פנ\"ב."],["1369","22","באתי לגני השי\"ת."],["1370","23","להעיר דיתירה מזו מצינו ד(בפרטיות) אמחז\"ל שהי' העולם <i>חסר</i> (ואפילו לאחרי עבודת אדה\"ר דאמר באו נשתחוה גו' ופעל זה בכל הבריאה (פרדר\"א פי\"א)) – עד שבא שבת (ב\"ר ספ\"י)."],["1371","24","שהש\"ר פ\"א, ג (א)."],["1372","25","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["1373","26","דהייתה עשיית יציר כפיו של הקב\"ה (שלימות האדם) ובג\"ע (שלימות המקום) – ראה המשך וככה תרל\"ז פ\"כ וכ\"א."],["1374","27","יומא כא, ב. וראה לקו\"ת ר\"ה נז, ג."],["1375","28","נוסח התפלה (דמוסף)."],["1376","29","המשך וככה הנ\"ל פי\"ז ואילך."],["1377","30","שהרי התכלית והשלימות דאז תלוי במעשינו ועבודתינו בגלות (<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>)."],["1378","31","ראה ד\"ה תשורי תרפ\"ט (ספר המאמרים – קונטרסים ח\"א נג, ב. סה\"מ תרפ\"ט ע' 215) פ\"ט."],["1379","32","תהלים סג, ג."],["1380","33","ד\"ה ויאמר משה תרע\"ט (סה\"מ עטר\"ת ע' תסד. נעתק בלקו\"ד ח\"א קי, א). תשורי שם. ועייג\"כ <a class=\"ft-cite\" href=\"#/read/torah-or/3901370234\" data-slug=\"torah-or\" data-id=\"3901370234\">תו\"א</a> ד\"ה מי שם פה (נב, ב)."],["1381","34","במדבר יב, ג."],["1382","35","תנחומא קורח יא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380695\" data-slug=\"likkutei-torah\" data-id=\"4001380695\">לקו\"ת מסעי (צב, ד</a> ואילך)."],["1383","36","סנהדרין קיא, סע\"א. וראה \"היום יום\" ע' ל [כ אדר א]."],["1384","37","ואף שמשה רע\"מ המשיך מס\"נ זו ויראה כו' (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310030\" data-slug=\"tanya\" data-id=\"3401310030\">תניא ספכ\"ה</a> ורפמ\"ב. לקו\"ת ר\"פ ואתחנן. ועוד) – הרי המעשה הוא עיקר. וגם צריך ליגיעה כו'."],["1385","38","עיין רשימות לאיכה ריש ע' ו' (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450564\" data-slug=\"or-hatorah-hb\" data-id=\"8316450564\">אוה\"ת שם ס\"ע א'לד</a>)."],["1386","39","להעיר ממשנ\"ת עה\"פ ומה ראו על ככה (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370530\" data-slug=\"torah-or\" data-id=\"3901370530\">תו\"א בהוספות קיח, ד</a>)."],["1387","40","ספרי ר\"פ מטות. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, סע\"א</a> ואילך."],["1388","41","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380109\" data-slug=\"likkutei-torah\" data-id=\"4001380109\">לקו\"ת צו ח, ב</a>."],["1389","42","וכידוע בפירוש ואמונה כל <i>זאת</i> וקיים עלינו (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380783\" data-slug=\"likkutei-torah\" data-id=\"4001380783\">לקו\"ת עקב יז, ב</a>)."],["1390","43","קהלת ד, ח. וראה רשימות הצ\"צ עה\"פ."],["1391","44","ראה שער הפסוקים פ' וירא עה\"פ ותהר ותלד. וראה ע\"ח שט\"ל ד\"ד (\"כדי לברר א\"א (כ\"ה ברוב הדפוסים ולא <i>או\"א</i>) כו' אחד קראתיו בלא שותפא\"). שט\"ז פ\"ד. וראה ג\"כ סהמ\"צ להצ\"צ מצות פו\"ר בסופה."],["1392","45","להעיר מהידוע דפני' עתיק יתגלה רק לע\"ל (פע\"ח שער הק\"ש פט\"ו וראה ד\"ה כי ישאלך ש\"ת בסופו ובהערות לשם), פני' התורה תורתו של משיח (ראה פרש\"י שה\"ש א, ב) ולימוד ה\"ז בהתיישבות דוקא."],["1393","46","לקו\"א ד\"ה טעם למה אין נזכר בשמו\"ע מלכות (לט, ג)."],["1394","47","פסחים קיב, סע\"א."],["1395","48","או\"ת על אגדות חז\"ל לברכות רפ\"ה (קח, ג). וראה ד\"ה אין עומדין (דרמ\"צ ח\"ב רנג, א ואילך. מאמרי אדה\"ז על מארז\"ל ע' מ)."],["1396","49","משנה סנהדרין מו, א."],["1397","50","צפע\"נ (לבעל המחבר תולדות יעקב יוסף) צב, ג."],["1398","51","איכה ג, כא."],["1399","52","ראה שעהיוה\"א רפ\"ז."],["1400","53","סנה' קד, סע\"א ואילך. איכ\"ר פ\"א, ד."],["1401","54","רשימות לאיכה ע' ה (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450564\" data-slug=\"or-hatorah-hb\" data-id=\"8316450564\">אוה\"ת שם ע' א'לד</a>)."],["1402","55","שמואל-א ב, ג."],["1403","56","בכללות דעות – תרין (ראה תקו\"ז ריש תס\"ט), ד\"ע וד\"ת. אבל בכאו\"א אפ\"ל (כמו בכל דבר שכל) באופן דהשכלה או הבנה וכו'. וכן בעבודה: ביחו\"ע תמיד, רק בשעת התפלה וכו'."],["1404","57","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381249\" data-slug=\"likkutei-torah\" data-id=\"4001381249\">לקו\"ת שה\"ש ל, א</a>. ועייג\"כ ד\"ה לך הוי' הצדקה (נדפס בסדר סליחות)."],["1405","58","סנהדרין קד, סע\"א. איכ\"ר פ\"א, ג. וראה רשימות לאיכה ע' יח (אוה\"ת שם ע' א'מז)."],["1406","59","להעיר מביאור מחז\"ל הוי זנב לאריות ואל תהי ראש לשועלים – מל' באצילות סופא דכל דרגין, מל' בבי\"ע (ראה לקוטי הש\"ס להאריז\"ל לברכות סא, א)."],["1407","60","רשימות לאיכה (מילואים) ע' עא (אוה\"ת שם ריש ע' א'נ)."],["1408","61","תו\"ח פ' נח (סו, סע\"ד ואילך)."],["1409","62","ע\"ד פי' מלמטלמ\"ע לא ידענו (לקו\"ת חוקת סד, א)."],["1410","63","כפס\"ד הרמב\"ם הל' תשובה פ\"ז ה\"ה. ובכ\"מ בס' תורת החסידות."],["1411","64","זח\"ג קכט, א."],["1412","65","בהגהות לד\"ה ציון במשפט תפדה (ע' ח'. אוה\"ת דברים ע' לב)."],["1413","66","אבל הג' צ\"ל בהתאחדות גמורה – ב\"ד <i>אחד</i>, מציאות אחת."],["1414","67","אבות פ\"א מ\"ב. ד\"ה זה דשנת ש\"ת."],["1415","68","ראה זח\"ג רכא, א."],["1416","69","ראה לקו\"ת בסופו. וש\"נ."],["1417","70","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370212\" data-slug=\"torah-or\" data-id=\"3901370212\">תו\"א מו, ד</a>. המשך וככה הנ\"ל פ\"כ."],["1418","71","ישעי' נב, יג. וראה המשך וככה שם."],["1419","72","וככה שם פי\"ב. פט\"ו. אבות פ\"ד מי\"ז."],["1420","73","וככה שם פי\"ב."],["1421","74","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>: שכך עלה ברצונו ית' להיות נח\"ר לפניו ית' כו'."],["1422","75","ראה רש\"י ותוס' (סוכה מא, סע\"א) \"יגלה ויבוא משמים\", והוא ע\"פ תנחומא נח, יא. זח\"א כח, א. ועוד. וברמב\"ם הל' מלכים רפי\"א ובסופו (ע\"פ ויק\"ר פ\"ט, ו. ועוד) דמשיח בונה ביהמ\"ק."]]],[1500390021,"<h3>בס\"ד. יום ד', חמשה עשר באב ה'תשל\"ה<sup data-n=\"1423\">*</sup></h3>\n<b>לא</b> היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים<sup data-n=\"1424\">1</sup>, ואיתא בגמרא<sup data-n=\"1425\">2</sup>, בשלמא יום הכפורים משום דאית בי' סליחה ומחילה, יום שניתנו בו לוחות האחרונות, אלא ט\"ו באב מאי היא, ומתרץ שבט\"ו באב אירעו כמה ענינים טובים (יום שהותרו שבטים לבוא זה בזה וכו'). וצריך להבין, מהו גודל העילוי דמאורעות אלו, שמפני זה, היו\"ט דט\"ו באב הוא גדול יותר משאר הימים טובים. ובפרט שמפשטות הלשון לא היו ימים טובים לישראל כחמשה עשר באב כו' משמע<sup data-n=\"1426\">3</sup> שהוא גדול יותר מכל הימים טובים, גם משלש רגלים. גם צריך להבין, דמזה שלא היו כו' כחמשה עשר באב וכיום הכפורים משמע שט\"ו באב ויוהכ\"פ שייכים זה לזה. וגם צ\"ל זה שמאמר זה הוא הסיום והחותם דמס' תענית, דלכאורה, תענית ויו\"ט [ובפרט יו\"ט גדול ביותר, שלא היו ימים טובים כמותו] הם הפכים<sup data-n=\"1427\">4</sup>.\n<b>והענין</b> הוא, דעיקר היו\"ט דט\"ו באב הוא כמובא בהמאמר שמבאר ענין חמשה עשר באב של אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"1428\">5</sup> מפע\"ח<sup data-n=\"1429\">6</sup> כי אז הוא [שלימות<sup data-n=\"1430\">7</sup>] מילוי הלבנה [והענינים שאירעו בחמשה עשר באב הם כמו תוצאות מענינו <i>העיקרי</i> של יום זה – שלימות מילוי הלבנה<sup data-n=\"1431\">8</sup>]. ומבאר בהמאמר, דהגם שבכל ט\"ו בחודש הוא מילוי הלבנה, מ\"מ, גודל המעלה דמילוי הלבנה הוא המילוי והשלימות שלה שלאחרי חסרון, דהשלימות שלאחרי חסרון היא שלימות נעלית יותר מהשלימות שמצד עצמה, כידוע<sup data-n=\"1432\">9</sup> הכלל בעליות וירידות, דהעלי' שלאחרי הירידה היא עלי' למעלה יותר מהדרגא שלפני הירידה, וכל שהירידה היא ביותר, העלי' היא ביותר. ולכן עיקר המעלה דמילוי הלבנה הוא בט\"ו באב, כי בחודש אב, הירידה דהלבנה (דישראל דומין ללבנה<sup data-n=\"1433\">10</sup>) היא ירידה גדולה ביותר, לכן, העלי' דט\"ו באב (שלאחרי הירידה דתשעה באב) היא עלי' גדולה ביותר. וזהו לא היו ימים טובים לישראל כחמשה עשר באב,שהוא יו\"ט גדול יותר גם מהימים טובים דפסח וסוכות, אף שגם ימים טובים אלה הם בט\"ו בחודש, כי העלי' דט\"ו בניסן (פסח), אף שהיא באה לאחרי הירידה דגלות מצרים, הרי<sup data-n=\"1434\">11</sup> כשיצאו ישראל ממצרים היתה התחלת עבודתם דרגת צדיקים<sup data-n=\"1435\">12</sup>, דגר שנתגייר<sup data-n=\"1436\">13</sup> כקטן שנולד דמי<sup data-n=\"1437\">14</sup>, ולכן העלי' דט\"ו בניסן אינה בהמשך כ\"כ להירידה שהיתה לפני זה. וגם העלי' דט\"ו בתשרי (סוכות), אף שהיו\"ט דסוכות בא בהמשך להתשובה וכפרה דיום הכפורים<sup data-n=\"1438\">15</sup>, הרי<sup data-n=\"1434\">11</sup> העלי' עצמה מהמצב הבלתי רצוי שהי' מקודם הוא ביום הכפורים, אלא שהגילוי דהענינים שנמשכו ביוהכ\"פ הוא בסוכות<sup data-n=\"1439\">16</sup>. משא\"כ העלי' שלאחרי הירידה דתחלת חודש אב, שהעלי' עצמה היא בט\"ו באב<sup data-n=\"1440\">17</sup>, לכן, היו\"ט דחמשה עשר באב הוא גדול יותר מהיו\"ט דפסח וסוכות.\nב) <b>אך</b> עדיין צריך להבין, הרי היו\"ט דפסח וסוכות (ודחג השבועות) הוא מן התורה, ואיך אפשר שהיו\"ט דחמשה עשר באב יהי' גדול יותר מהיו\"ט דשלש רגלים. גם צריך להבין, דמזה שאומר לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים, שמקדים חמשה עשר באב ליום הכפורים [אף שהיו\"ט דחמשה עשר באב נתחדש (לפי כל הטעמים שבגמרא) כמה שנים לאחרי היו\"ט דיוהכ\"פ], משמע, דהיו\"ט דחמשה עשר באב הוא נעלה יותר גם מהיו\"ט דיוהכ\"פ, וצריך ביאור, הרי גם ביוהכ\"פ עלי' ממצב בלתי רצוי, ומהי המעלה דחמשה עשר באב לגבי יוהכ\"פ.\nג) <b>ויובן</b> זה ע\"פ המבואר בהמאמר פירוש הכתוב<sup data-n=\"1441\">18</sup> יתרון ארץ בכל היא מלך לשדה נעבד<sup data-n=\"1442\">19</sup>, דארץ הוא כללות העולם, ושדה (המובחר שבארץ) הוא ג\"ע. וחילוק זה שבין כללות העולם לג\"ע (שכללות העולם נק' ארץ וג\"ע שדה) הוא בשרשם. דהתהוות העולם היא מבחינת הדיבור דמלכות (חיצוניות המלכות<sup data-n=\"1443\">20</sup>) שנק' ארץ, והג\"ע הוא מבחי' ג' ראשונות דמלכות (פנימיות המלכות<sup data-n=\"1443\">20</sup>) שנק' שדה,כמבואר בהמאמר. שהדיבור דמלכות (העשרה מאמרות שבהם נברא העולם<sup data-n=\"1444\">21</sup>) ענינו הוא להוות את הנבראים, בדוגמת הדיבור שבאדם שהוא בשביל הזולת, והג\"ר דמלכות הוא פנימיות המלכות שמקבלת מיסוד, שהוא<sup data-n=\"1445\">22</sup> סיום האצילות (סיומא דגופא<sup data-n=\"1446\">23</sup>), בדוגמת המדות שבאדם, דהגם שהם שייכים להזולת, הרי ענינם הוא<sup data-n=\"1447\">24</sup> <i>שהאדם</i> מתעורר ומתפעל.\n<b>ומוסיף</b> בהמאמר שיש עוד יתרון בג\"ע על כללות העולם, דההמשכה בעולם היא מהמדות, כי הדיבור דמלכות מקבל מהמדות<sup data-n=\"1448\">25</sup>, וההמשכה בג\"ע היא מהמוחין, וכמבואר שם, דזה שהיסוד נקרא בשם כל<sup data-n=\"1449\">26</sup> הוא על שם נו\"ן שערי בינה שנמשכים בו (כל בגימטריא נו\"ן<sup data-n=\"1450\">27</sup>), ולכן, כיון שהג\"ע הוא מפנימיות המלכות שמקבלת מהיסוד, הרי ע\"י היסוד נמשכים בג\"ע גם המוחין. וזהו יתרון ארץ בכל היא מלך לשדה נעבד, שהיתרון דארץ (כללות העולם, שהתהוותה היא מהדיבור דמלכות) היא בכל, המשכת היסוד, ועי\"ז – המשכת המוחין, ואז נמשך גילוי אלקות גם בכללות העולם, כמו בג\"ע. ומלך לשדה נעבד הוא כמ\"ש בזהר<sup data-n=\"1451\">28</sup> מאן מלך דא מלך עילאה דאתחבר לשדה כד איהו נעבד, שע\"י העבודה בג\"ע (שדה נעבד) נעשה המשכת הכתר (מלך עילאה) שלמעלה מהשתלשלות.\n<b>ומבאר</b> בהמאמר, דאז, כשמאיר במלכות הכתר שלמעלה מהשתלשלות, קיימא סיהרא באשלמותא, שמאיר האור גם בחיצוניות המלכות (דיבור דמלכות, עשרה מאמרות שבהם נברא העולם), ועי\"ז, גם בעולם. דבההמשכה שע\"פ סדר השתלשלות, יש חילוק בין פנימיות המלכות (שדה) וחיצוניות המלכות (ארץ), ולכן, כשההמשכה במלכות היא מבחינת המוחין, הגילוי הוא רק בהדרגא דמלכות שמקבלת מז\"א (פנימיות המלכות), ובהדרגא דמלכות שהיא שרש הנבראים (עשרה מאמרות) אין האור מאיר. בדוגמת<sup data-n=\"1452\">29</sup> הלבנה בזמן פגימתה, שאור השמש מאיר רק בחצי כדור העליון שבה. וכשההמשכה היא מהכתר שלמעלה מהשתלשלות, הגילוי הוא גם בהעשרה מאמרות (ועל ידם גם בהעולם), בדוגמת<sup data-n=\"1452\">29</sup> הלבנה בזמן המילוי (באמצע החודש), שאור השמש מאיר גם בחצי כדור התחתון שבה.ד) <b>וצריך</b> להבין, דלכאורה ענין מיעוט הירח הוא שבכדי שיהי' התהוות העולמות נעשה מיעוט וחסרון בהמלכות (את עשית את השמים גו'<sup data-n=\"1453\">30</sup>, את חסר ה'<sup data-n=\"1454\">31</sup>), שאין מאיר בה האור דאצילות שלמעלה משרש הנבראים, וכיון שבג\"ע מאיר בחי' כל, היסוד וגם המוחין, הרי אין בו חסרון. וכמבואר בהמאמר<sup data-n=\"1455\">32</sup>, דהטעם שג\"ע נקרא בשם כל, הוא, כי יש בו הכל בלי חסרון. ועפ\"ז נמצא, שגם בג\"ע הלבנה (מלכות) היא בשלימות. ובהמאמר אומר שהענין דקיימא סיהרא באשלמותא הוא דוקא כשמלך לשדה נעבד, שע\"י העבודה נמשך בו הכתר (מלך עילאה) שלמעלה מהשתלשלות.\n<b>ויש</b> לומר הביאור בזה, דאמיתית הענין דקיימא סיהרא באשלמותא הוא שהשלימות היא באופן שאין שייך שיהי' חסרון. ושלימות זו היא דוקא כשההמשכה היא מאור שלמעלה משייכות לעולמות, שאין שייך שיהי' בו צמצום. דאור השייך לעולמות, גם האור שקודם הצמצום, הוא אור כזה ששייך בו צמצום. ולכן, ההמשכה דבחי' כל שבג\"ע, אף שההמשכה היא בשלימות [וכנ\"ל מהמאמר דפירוש כל הוא הכל בלי חסרון], כיון שההמשכה היא מאור מוגבל (מוחין) ששייך שיהי' בו צמצום והפסק, אינו אמיתית השלימות<sup data-n=\"1456\">33</sup>. ואמיתית הענין דקיימא סיהרא באשלמותא הוא ע\"י העבודה דתומ\"צ, שעי\"ז נמשך אור הבל\"ג (שלמעלה מהאור ששייך לעולמות) שאין שייך בו צמצום, מלך לשדה נעבד.\nה) <b>והנה</b> מבואר בהמאמר<sup data-n=\"1455\">32</sup>, דבשדה אשר ברכו הוי'<sup data-n=\"1457\">34</sup>, שני פירושים. פירוש רש\"י שהוא ג\"ע, ופירוש הת\"י שהוא בית המקדש. וכמבואר בכ\"מ<sup data-n=\"1458\">35</sup>, דביהמ\"ק הוא כמו ג\"ע. וכמו<sup data-n=\"1459\">36</sup> שבג\"ע יש ב' מדריגות, ג\"ע מצד עצמו והתוספות אור שנמשך בו ע\"י עבודה, עד\"ז הוא בביהמ\"ק, דנוסף על הגילוי שהי' בביהמ\"ק מצד עצמו, הרי ע\"י העבודה בביהמ\"ק (עבודת הקרבנות) האיר בו גילוי נעלה יותר. וע\"פ מ\"ש בהמאמר שהענין דקיימא סיהרא באשלמותא הוא (בעיקר) ע\"י העבודה בשדה (מלך לשדה נעבד), מובן, דכמו\"כ הוא גם בנוגע לביהמ\"ק, שהענין דקיימא סיהרא באשלמותא שהי' בביהמ\"ק מצד עצמו, הן המקום דביהמ\"ק שלית דין אתר הדיוט<sup data-n=\"1460\">37</sup>, וכן הזמן דבנין ביהמ\"ק שנבנה ע\"י שלמה דור הט\"ו לאברהם שאז קיימא סיהראבאשלמותא<sup data-n=\"1461\">38</sup>, הוא דוגמת הגילוי שבג\"ע מצד עצמו<sup data-n=\"1462\">39</sup>, שדה, ועיקר קיימא סיהרא באשלמותא שהי' בביהמ\"ק הוא שע\"י העבודה בביהמ\"ק נמשך בו תוספות אור שלמעלה מהשתלשלות, מלך לשדה נעבד.\n<b>ועפ\"ז</b> יש לומר, דהגילוי שהי' בביהמ\"ק מצד עצמו, היתה המשכתו רק בזמן הבית. וכמבואר בהמאמר<sup data-n=\"1463\">40</sup>, שהחילוק בין זמן הבית לזמן הגלות הוא בדוגמת החילוק שבין חצי כדור העליון דהלבנה לחצי כדור התחתון שבה. ולכן, כיון שהגילוי שהי' בביהמ\"ק מצד עצמו הוא אור מוגבל שמאיר רק<sup data-n=\"1464\">41</sup> בהדרגא דמלכות שמקבלת מז\"א (חצי כדור העליון דהלבנה), היתה המשכתו רק בזמן הבית. והאור שניתוסף בביהמ\"ק ע\"י העבודה [עבודת הקרבנות, ועד\"ז העבודה דועשו לי מקדש<sup data-n=\"1465\">42</sup>], כיון שאור זה הוא בל\"ג שאין שייך בו הפסק, המשכתו הוא גם בזמן הגלות. אלא שמצד הירידה שבזמן הגלות, אין האור נרגש בהעולם (כדלקמן סעיף ו).\nו) <b>וממשיך</b> בהמאמר, שיש עוד פירוש בזהר<sup data-n=\"1466\">43</sup> במלך לשדה נעבד, שהוא לגריעותא. דשדה הוא שדה דלעו\"ז [בשדה מצאה<sup data-n=\"1467\">44</sup>], ומלך לשדה נעבד הוא שהמלכות דקדושה נעבדת לשדה דלעו\"ז. ויש לומר, דזה שפירוש זה במלך לשדה נעבד בא לאחרי ובהמשך להפירוש דמלך לשדה נעבד הוא למעליותא, הוא, כי זה שישנו הענין דמלך לשדה נעבד לגריעותא הוא בכדי שהענין דמלך לשדה נעבד למעליותא, המשכת מלך עילאה (כתר), תהי' באופן נעלה יותר. ויש לומר דהעילוי שניתוסף בהמשכת הכתר ע\"י הירידה (דמלך לשדה נעבד לגריעותא) לגבי ההמשכה שקודם הירידה, הוא הוספה שבאין ערוך. ועד שלגבי ההמשכה שלאחר הירידה,ההמשכה שהיתה מקודם היא בכלל הסדר השתלשלות. וזהו שארז\"ל<sup data-n=\"1468\">45</sup> דזה שעלה ארי' במזל ארי' והחריב את אריאל כו' הוא על מנת שיבוא ארי' במזל ארי' ויבנה אריאל, וידוע<sup data-n=\"1469\">46</sup> דיבוא ארי' [זה הקב\"ה, דכתיב בי'<sup data-n=\"1470\">47</sup> ארי' שאג מי לא יירא] הוא התגלות הכתר שלמעלה מהשתלשלות. ומזה שבכדי שיהי' יבוא ארי' (התגלות הכתר שלמעלה מהשתלשלות) הי' צריך להיות עלה ארי' כו' והחריב אריאל, אף שהענין דמלך לשדה נעבד (למעליותא) הי' גם קודם, מובן, שהמשכת הכתר (מלך עילאה) שהיתה מקודם, לגבי ההמשכה שלאחרי הירידה, היא בכלל סדר ההשתלשלות.\n<b>ויש</b> לומר הביאור בזה ע\"פ הידוע<sup data-n=\"1471\">48</sup> דעבודת הצדיקים (כולל גם ההמשכה שע\"י העבודה) היא בבחינת אור ישר, מלמעלה למטה, היינו שהגילוי שמאיר בעולם ע\"י עבודת הצדיקים הוא (בעיקר) מצד למעלה, ובכדי שיהי' זיכוך ועלי' גם בהמטה עצמו, זה נעשה (בעיקר) ע\"י עבודת התשובה. ועפ\"ז יובן זה שהמשכת הכתר (מלך עילאה) שהיתה לפני הירידה דגלות, לגבי ההמשכה שלאחרי הירידה היא בכלל סדר ההשתלשלות, כי אמיתית הענין דלמעלה מהשתלשלות הוא שאין בו ההגבלה והחילוק דמעלה ומטה, וכיון שהעבודה שבזמן הבית היא (בדרך כלל) עבודת הצדיקים, דההמשכה שע\"י עבודה זו היא (בעיקר) מצד למעלה, היינו דגם לאחרי ההמשכה יש חילוק בין המעלה להמטה, נמצא שהמשכה זו היא בכלל השתלשלות. [אלא שבהבחינות דהשתלשלות גופא, ההמשכה שע\"י העבודה דתומ\"צ היא מאור הבל\"ג, שהוא בכל מקום בשוה. ולכן, האור שנמשך בביהמ\"ק ע\"י העבודה, ישנו גם בזמן הגלות (כנ\"ל סעיף ה). אבל אעפ\"כ, כיון<sup data-n=\"1472\">49</sup> דזה שהאור הוא בכל מקום הוא מפני <i>שהאור</i> הוא א\"ס, לכן, בכדי <i>שבהעולם</i> יהי' נרגש האור, הוא דוקא כשהעולם הוא באופן שיש לו שייכות להאור<sup data-n=\"1473\">50</sup>. וכיון שבזמן הגלות נעשה ירידה בהעולם, לכן, בזמן הגלות אינו מאיר הגילוי בהעולם]. וע\"י העבודה שבזמן הגלות, שהיא (בדרך כלל) עבודת התשובה, ההמשכה היא ממקום שאין בו חילוק דמעלה ומטה, אמיתית הענין דלמעלה מסדר השתלשלות, שע\"י המשכה זו, נעשה זיכוך ועלי' גם בהמטה עצמו<sup data-n=\"1474\">51</sup>.\nז) <b>ויש</b> לבאר זה בעומק יותר ע\"פ המבואר במק\"א<sup data-n=\"1475\">52</sup> דהגילוי שנמשך בעולם ע\"י עבודת הצדיקים, כיון שכוונת הבריאה לכתחילה היתה בכדי שהצדיקים (ועמך כולם צדיקים<sup data-n=\"1476\">53</sup>) ע\"י עבודתם יוסיפו גילוי אלקות בעולם, במי נמלך בנשמותיהןשל צדיקים<sup data-n=\"1477\">54</sup>, לכן, הגילוי שנמשך בעולם ע\"י עבודת הצדיקים, גם הגילוי שלמעלה מהשתלשלות, כולל גם זה שע\"י העבודה דתומ\"צ נמשך אור חדש שלא האיר אפילו קודם הצמצום, אין זה חידוש אמיתי. משא\"כ ע\"י עבודת התשובה, כשהאדם חטא ופגם והעביר את הדרך (היפך הכוונה דבריאת האדם שהי' באופן דעשה האלקים את האדם ישר<sup data-n=\"1478\">55</sup>) ואח\"כ מתקן זה ע\"י התשובה, עי\"ז נעשה חידוש גם לגבי כוונת הבריאה כמו שהיא בהדרגא דבמי נמלך. וזה שבכח האדם לפעול חידוש זה הוא לפי ששרש הנשמות הוא בהעצמות, שהוא למעלה משרשם בהענין דבמי נמלך. דהגם שההמלכה היא למעלה מכל הגילויים, גם מהגילוי דחפץ חסד<sup data-n=\"1479\">56</sup>, שהרי ההמלכה היא אם להיות חפץ חסד או לאו, מ\"מ, ההמלכה היא בנוגע לגילויים (אם יהיו גילויים אם לאו), ושרש הנשמות הוא בהעצמות.\n<b>וזהו</b> שהשלימות דעולם שתהי' לע\"ל, אלה תולדות פרץ<sup data-n=\"1480\">57</sup> תולדות מלא<sup data-n=\"1481\">58</sup>, תהי' נעלית יותר מהשלימות שהיתה בתחילת הבריאה, אלה תולדות השמים והארץ בהבראם<sup data-n=\"1482\">59</sup> תולדות מלא<sup data-n=\"1481\">58</sup>, עולם על מילואו נברא<sup data-n=\"1483\">60</sup>, שהשלימות דעולם כמו שהוא מצד הבריאה, כולל גם השלימות שמצד כוונת הבריאה<sup data-n=\"1484\">61</sup> (הענין דבמי נמלך), היא במדידה והגבלה, והשלימות דעולם שתהי' לע\"ל ע\"י עבודת התשובה [שהגילוי דלע\"ל יהי' בעיקר ע\"י עבודת התשובה] תהי' למעלה ממדידה והגבלה, אלה תולדות פרץ, דענין פרץ [שנקרא כן על שם פרצת עליך פרץ<sup data-n=\"1485\">62</sup>] הוא שפורץ כל המדידות והגבלות, כולל גם המדידה וההגבלה שמצד כוונת הבריאה כמו שהיא בבחינת ההמלכה, היינו שמים חדשים וארץ חדשה<sup data-n=\"1486\">63</sup>.\nח) <b>ועפ\"ז</b> יש לבאר חילוקי הדרגות שבמילוי ושלימות הלבנה (דלעיל סעיף א), דמילוי ושלימות הלבנה שבט\"ו דכל חודש, כיון שהיא מצד הטבע שהטביע הקב\"ה בהבריאה ואינה קשורה עם עבודתם של ישראל, הוא (בכללות) המשכה שע\"פ סדר השתלשלות. וזה שבט\"ו לחודש מאיר האור גם בחצי חלק התחתון דהלבנה הוא מצד מעלת יום הט\"ו, שבו, גם חצי חלק התחתון הוא דוגמת חצי חלק העליון. ושלימות הלבנה שבט\"ו בניסן וט\"ו בתשרי, כיון שזה קשור (גם) עם עבודת האדם, היא (בכללות) המשכה שלמעלה מהשתלשלות. שלכן ט\"ו בניסן וט\"ו בתשרי הם ימים טובים, דענין יו\"ט הוא המשכת אור שלמעלה מהשתלשלות. ושלימות הלבנהבט\"ו באב שקשורה עם עבודת התשובה (העלי' שלאחרי הירידה דתשעה באב), הוא, דזה שמאיר גם חצי חלק התחתון דהלבנה הוא (לא רק מצד זה שהאור הוא א\"ס ולכן מאיר גם למטה, אלא גם) מצד העלי' שבהמלכות עצמה. וכמבואר בהמאמר, דבט\"ו באב מאיר במלכות בחינת עתיק, די\"ל שהוא הגילוי דמעלת ושרש המלכות עצמה. וזוהי גם השייכות דחמשה עשר באב ליום הכפורים, כי גם ביוהכ\"פ הוא עליית המלכות בפנימיות עתיק, כמבואר בהמאמר.\nט) <b>ויש</b> לומר, דזה שהיו\"ט דחמשה עשר באב הוא נעלה יותר גם מיוהכ\"פ, אף שגם ביוהכ\"פ הוא עבודת התשובה, הוא, כי מזה גופא שהתורה קבעה יום סליחה וכפרה בכל שנה ושנה, מובן, שהירידה לדברים הבלתי רצויים שלאחרי' באה העלי' דיוהכ\"פ היא באופן שיש לה מקום מצד הבריאה, דזה שנקבע בתורה (אסתכל באורייתא וברא עלמא<sup data-n=\"1487\">64</sup>) יום סליחה וכפרה על ענינים בלתי רצויים הוא, כי מצד גודל העילוי שבתשובה, דבמקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו<sup data-n=\"1488\">65</sup>, יש מקום לזה (גם) מצד כוונת הבריאה כמו שנמשכה בגילוי, בהדרגא דבמי נמלך, אף <i>שעיקר</i> הכוונה בדרגא זו היא עבודת הצדיקים, במי נמלך בנשמותיהן של צדיקים. משא\"כ הירידה דתשעה באב, חורבן ביהמ\"ק והגלות, היא ירידה כזו שאין לזה נתינת מקום [כמובן גם ממגילת איכה, דזה שאומר איכה בלשון תמי' הוא לפי שגם מצד העילוי שבתשובה, אין מקום לירידה כזו]. וזה שבפועל היתה ירידה זו בכדי שתהי' עלי' נעלית יותר, עלה ארי' כו' על מנת שיבוא ארי', הוא רק מצד הכוונה האמיתית (כמו שהיא בהעצמות), שע\"י העבודה דישראל יהי' חידוש בהבריאה, שמים חדשים וארץ חדשה. ולכן, היו\"ט דחמשה עשר באב הוא נעלה יותר גם מיוהכ\"פ.\n<b>וזהו</b> גם מה שהסיום והחותם דמס' תענית הוא לא היו ימים טובים לישראל כחמשה עשר באב כו', כי זהו הביאור דכל התעניות. דזה שישנם דברים בלתי רצויים שצריך להתענות עליהם, ועד להדברים שאירעו בשבעה עשר בתמוז ובתשעה באב<sup data-n=\"1489\">66</sup>, הוא בשביל העלי' שלאחרי הירידה – היו\"ט דחמשה עשר באב, שהוא יום שמחת לבו<sup data-n=\"1490\">67</sup> (דהקב\"ה) זה בנין בית המקדש שיבנה במהרה בימינו<sup data-n=\"1491\">68</sup>.\n<b>ויהי</b> רצון, שע\"י מעשינו ועבודתינו<sup data-n=\"1492\">69</sup> שלא להתפעל מכל הנסיונות, כולל גם נסיונות כאלו שמצד כל החשבונות (גם מצד העילוי שבעבודת הנסיונות<sup data-n=\"1493\">70</sup>) אין הסברה על זה, יקרבו ויזרזו עוד יותר הגאולה העתידה ע\"י משיח צדקנו, שילחם<sup data-n=\"1494\">71</sup> מלחמותה' וינצח [דרובם של מלחמות אלו אין להם מקום בשכל, גם לא בהשכל של הלוחמים, שלכן, המלחמות הם בתוקף גדול, ואעפ\"כ ינצח], ויבנה בית המקדש במקומו, ויקבץ נדחי ישראל, כולל שיקבץ כל ניצוצות הקדושה<sup data-n=\"1495\">72</sup> וגם נדחי ישראל כפשוטם – קיבוץ גלויות, בקרוב ממש, בגאולה האמיתית והשלימה ע\"י משיח צדקנו.\n**********",[["1423","*","יצא לאור ב<b>קונטרס ט\"ו באב – תשמ\"ט</b>, \"לקראת חמשה עשר באב . . <i>מוצש\"ק נחמו ה'תשמ\"ט</i>\"."],["1424","1","תענית כו, ב (במשנה)."],["1425","2","שם ל, ב. וראה גם ב\"ב קכא, א."],["1426","3","וכמפורש באוה\"ת ובד\"ה נחמו עת\"ר (שבהערה 5) – נעתק לקמן בפנים."],["1427","4","להעיר מתענית יב, א \"ולא השלמנוהו מפני שיו\"ט שלנו הוא\". ולהעיר גם מזה שאין מתענין בכל חודש ניסן לפי שהוא \"כעין יו\"ט\" (שו\"ע אדה\"ז או\"ח הל' פסח סתכ\"ט ס\"ט. וש\"נ)."],["1428","5","ד\"ה נחמו עת\"ר [רישומי דברים דהמאמר – נדפסו בסה\"מ עת\"ר ע' ריח ואילך. והנחה – שם ע' רכא ואילך]. וכ\"ה גם באוה\"ת ואתחנן כרך ו ע' ב'קצז."],["1429","6","סוף שער חג השבועות – \"דרוש על סוד ט\"ו באב\"."],["1430","7","בפע\"ח שם \"<i>מילוי</i> הלבנה\". ובאוה\"ת שם ובד\"ה נחמו הנ\"ל (סה\"מ שם ע' ריח) מוסיף \"<i>שלימות</i> מילוי הלבנה\". [וב\"הנחה\" הנ\"ל (סה\"מ שם ע' רכא) \"מילוי הלבנה בשלימות\"]. וראה לקמן הערה 33."],["1431","8","ראה פע\"ח שם."],["1432","9","ב\"רישומי דברים\" שם (ע' ריט) מציין לד\"ה \"לסוסתי תקס\"ב תקס\"ד ו<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381175\" data-slug=\"likkutei-torah\" data-id=\"4001381175\">לקו\"ת</a>\" – והוא בסה\"מ תקס\"ד ע' כה ואילך. לקו\"ת שה\"ש יא, ג."],["1433","10","ראה ב\"ר פ\"ו, ג. שמו\"ר פט\"ו, כו."],["1434","11","ביאור באו\"א ראה ד\"ה זה ה'תשד\"מ (התוועדויות תשד\"מ ח\"ד ע' 2332 ואילך)."],["1435","12","וע\"ד המבואר החילוק בין פסח (ניסן) לעצרת של חג (שמע\"צ, תשרי), דפסח הו\"ע בנות \"נשואות למקום קרוב הן צדיקים כו'\", ועצרת של חג הו\"ע בנות \"נשואות למקום רחוק, הן בע\"ת כו'\" – ד\"ה ביום השמע\"צ (הא') עזר\"ת (סה\"מ עזר\"ת ס\"ע לז). סד\"ה להבין ענין שמח\"ת ה'תש\"ו (סה\"מ ה'תש\"ו ע' 47). ועוד. וראה ג\"כ אוה\"ת בא ד\"ה החודש (ע' רנז ואילך) בענין החילוק בין ניסן לתשרי."],["1436","13","שענין הגירות דבני ישראל הי' בפסח – ראה יבמות מו, א ואילך. כריתות ט, א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181128\" data-slug=\"likkutei-sichot\" data-id=\"1300181128\">לקו\"ש חי\"ח ע' 119</a> הערה 26."],["1437","14","יבמות כב, א. וש\"נ."],["1438","15","ראה בארוכה המשך וככה תרל\"ז פצ\"ז, דזה שבחג הסוכות דוקא אומרים זמן שמחתינו הוא לפי שבא לאחרי יוהכ\"פ. ושם בסוף הפרק \"וזהו כל היו\"ט דסוכות\"."],["1439","16","כידוע בענין בכסה ליום חגינו – ראה לעיל ח\"א ע' רכד. הנסמן לעיל שם ע' קסג הערה 7. ובכ\"מ."],["1440","17","ואף שהתחלת העלי' היא מיד לאחרי תשעה באב (ראה בהמאמר שם ע' רכ ובשוה\"ג שם. וראה שם ע' רכט) – הרי השלימות דהעלי' (עצמה) היא בט\"ו באב (משא\"כ חגה\"ס, שהכפרה היא ביוהכ\"פ, ורק שהגילוי הוא בחגה\"ס)."],["1441","18","קהלת ה, ח."],["1442","19","ב\"רישומי דברים\" שם מציין אדמו\"ר (מהורש\"ב) נ\"ע למאמר דפ' חיי שרה, תר\"ל – נדפס בסה\"מ תר\"ל ס\"ע יט ואילך. וראה בארוכה ד\"ה ויהיו חיי שרה בסה\"מ פר\"ת ע' קמ ואילך. וראה גם ביאורי הזהר (בהוספות) חיי שרה קכט, ד."],["1443","20","סה\"מ פר\"ת שם ע' קמד."],["1444","21","אבות פ\"ה מ\"א."],["1445","22","ראה תו\"א ס\"פ תרומה (פא, ב). המשך תרס\"ו ע' רפד ואילך. ובכ\"מ."],["1446","23","תקו\"ז בהקדמה (\"פתח אליהו\") יז, א."],["1447","24","סה\"מ פר\"ת שם ע' קמא. וראה גם סה\"מ ה'ש\"ת ע' 24 (דזהו החילוק בין מדות למלכות). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061125\" data-slug=\"likkutei-sichot\" data-id=\"1300061125\">לקו\"ש ח\"ו ע' 114</a> ואילך."],["1448","25","ראה סה\"מ ה'תש\"ב ע' 103, דהשכל שהוא לעצמו, עיקר התגלותו הוא ע\"י המחשבה, והמדות שהם שייכים לזולת, עיקר התגלותם הוא ע\"י הדיבור."],["1449","26","ראה זח\"ג רנז, סע\"א (ברע\"מ). פרדס שער יג (שער השערים) ספ\"ו. שער כג (שער ערכי הכינויים) מערכת כל כלה. ל\"ת להאריז\"ל עה\"פ וישב מ, א. וראה מאמרי אדהאמ\"צ דברים ח\"ב ע' תרפז. וש\"נ."],["1450","27","ראה פרדס שם. מאמרי אדהאמ\"צ שם. וש\"נ."],["1451","28","ח\"א פ' חיי שרה קכב, א. וראה ביאוה\"ז שבהערה 19."],["1452","29","ראה בארוכה סידור (עם דא\"ח) קפב, ד ואילך. פירוש המלות לאדהאמ\"צ פמ\"ח ופמ\"ט."],["1453","30","נחמי' ט, ו."],["1454","31","ראה בארוכה ד\"ה וחזקת והיית לאיש ה'תשכ\"ח ס\"ב (לעיל ע' קד). וש\"נ. וראה גם בד\"ה נחמו עת\"ר (סה\"מ שם ע' ריח. שם ע' רכג). ברוב המקומות שנסמנו בד\"ה וחזקת הנ\"ל, מבואר ענין זה בנוגע למל' דא\"ס שלפני הצמצום (אצילות דכללות). ובהמשך תער\"ב ח\"א פקמ\"ג (ועוד), שכ\"ה גם במלכות דאצילות. עיי\"ש."],["1455","32","ע' ריח. שם ע' רכג."],["1456","33","דהמשכה זו (שנמשך האור שנסתלק) היא רק מילוי החסרון, ולא \"שלימות\". וע\"ד החילוק בין \"די מחסורו\" ו\"לעשרו\" (כתובות סז, ב) – ראה המשך תער\"ב ח\"ב פ' שעג ופ' שעד. וראה לקמן הערה 39."],["1457","34","ל' הכתוב – תולדות כז, כז. ובזהר שבהערה 28 עה\"פ מלך לשדה נעבד \"מאן שדה דא שדה אשר ברכו ה' דכתיב כריח שדה אשר ברכו ה'\"."],["1458","35","סה\"מ תר\"ס ע' קלד. ובכ\"מ. וראה בארוכה סה\"מ עת\"ר ע' ריד ואילך."],["1459","36","סה\"מ עת\"ר שם ע' רטז."],["1460","37","תרגום אונקלוס עה\"פ (ויצא כח, יז) אין זה כי אם בית אלקים."],["1461","38","זהר ח\"א קנ, רע\"א. רכה, סע\"ב. רמג, סע\"א. ח\"ב פה, א. ח\"ג מ, ב. מו, א. ובשמו\"ר פט\"ו, כו: כיון שבא שלמה <i>נתמלא</i> דיסקוס של לבנה. וראה הערה הבאה."],["1462","39","בהמשך תער\"ב פשע\"ד, דזה שבימי שלמה הוה קיימא סיהרא באשלמותא הוא לא רק מילוי החסרון אלא בחינת עשירות [וראה לקו\"ש ח\"ה ע' 420 (וראה בשיחת י\"ד כסלו ה'תשל\"א), דבמדרש (שמו\"ר שם) מדובר (רק) הענין דמילוי החסרון, ובזהר (פנימיות התורה) – ענין השלימות, עשירות]. ואין סתירה מזה למ\"ש בפנים, כי גם באור השייך לעולמות, כמה דרגות. ולהעיר מסה\"מ פר\"ת שם ע' קמה, שגם הענין ד\"יתרון ארץ בכל היא\" הוא האור שקודם הצמצום, שלגבי העולמות הוא אור חדש*, אלא שאינו אור חדש ממש, כי כבר האיר קודם הצמצום."],["1463","40","סוף ס\"ב (ע' רכב)."],["1464","41","וזה שבזמן הבית הי' הגילוי גם בכללות העולם (כמ\"ש בהמאמר שם), הרי (א) הגילוי שהי' בכללות העולם לא הי' כהגילוי שבביהמ\"ק עצמו, והוא לפי שהגילוי הי' אור מוגבל, דאור הבל\"ג הוא בכל מקום בשוה. (ב) בזמן הבית, כללות העולם לא הי' במצב ירוד כבזמן הגלות, כי הי' מושפע מהגילוי דביהמ\"ק**. ועצ\"ע."],["1465","42","תרומה כה, ח."],["1466","43","שבהערה 28."],["1467","44","לשון הכתוב תצא כב, כז. וראה זהר שם.\n*) <i><a class=\"ft-cite\" href=\"#/read/torah-or/3901370031\" data-slug=\"torah-or\" data-id=\"3901370031\">תו\"א בראשית ח</i>,<i> ב</a></i>.<i> וראה המשך תרס\"ו ע' ד</i>.<i> סה\"מ ה'תש\"י ע' 12 ואילך</i>.<i> וראה גם סה\"מ פר\"ת שם שההמשכה ד</i>\"<i>יתרון ארץ בכל היא</i>\"<i> היא דוגמת ההמשכה שע\"י תפלה</i>, \"<i>יהי רצון שנמשך רצון חדש</i>\",<i> אלא שאין זה חידוש ממש</i>. <b>עיי\"ש</b>.\n**) <i>ועד\"ז הוא בנוגע למעלת הזמן דבנין ביהמ\"ק</i>,<i> דור ט\"ו לאברהם</i>,<i> שהי' לו השפעה גם על הדורות שלאח\"ז</i>,<i> שלכן גם אז הי' הענין דקיימא סיהרא באשלמותא</i>,<i> אלא שלא הי' כמו בימי שלמה</i>."],["1468","45","יל\"ש ירמי' רמז רנט."],["1469","46","אוה\"ת נ\"ך כרך ב ע' א'נו ואילך."],["1470","47","עמוס ג, ח."],["1471","48","סה\"מ תרס\"א ע' קסג ואילך. ובכ\"מ. וראה לעיל ח\"א ע' ריח."],["1472","49","ראה עד\"ז ד\"ה ציון במשפט ה'תשל\"ו ס\"ג (לעיל ע' קמ). וש\"נ."],["1473","50","להעיר מהמשך תרס\"ו ע' נה, \"דעם היות דסוכ\"ע הוא למעלה כמו למטה מ\"מ למטה הוא נמצא בהעלם ולמעלה מאיר בגילוי יותר\"."],["1474","51","להעיר מהמבואר בהמאמר (ע' רכ. שם ע' רכח), דבזמן בית ראשון, אף שקיימא סיהרא באשלמותא, מ\"מ היתה המלכות רק \"בחי' מקבל\", ולכן הי' שייך שינויים, והעלי' שתהי' לע\"ל (ע\"י הירידה דהגלות) היא \"שהמלכות תהי' בבחי' י\"ה ולא בחי' מקבל\"."],["1475","52","ראה לעיל ח\"א ע' ריח ואילך."],["1476","53","ישעי' ס, כא."],["1477","54","ב\"ר פ\"ח, ז. רות רבה פ\"ב, ג."],["1478","55","קהלת ז, כט."],["1479","56","ראה בארוכה ד\"ה זה היום דליל ער\"ה ה'תשמ\"ב ס\"ה (לעיל ח\"א ע' מד ואילך). <i>וש\"נ</i>."],["1480","57","רות ד, יח."],["1481","58","ב\"ר פי\"ב, ו. שמו\"ר פ\"ל, ג."],["1482","59","בראשית ב, ד."],["1483","60","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["1484","61","להעיר מסה\"מ עת\"ר ע' רטו (בהחצע\"ג), דלפי פירוש אחד – הכוונה ב\"עולם על מילואו נברא\" הוא שהי' ראוי להגילוי שנמשך בו ע\"י העבודה דתומ\"צ."],["1485","62","וישב לח, כט."],["1486","63","ישעי' סו, כב."],["1487","64","זח\"ב קסא, א-ב."],["1488","65","רמב\"ם הל' תשובה פ\"ז ה\"ד, מברכות לד, ב."],["1489","66","תענית כו, סע\"א (במשנה)."],["1490","67","שה\"ש ג, יא."],["1491","68","סיום וחותם המסכת (במשנה). וראה חדא\"ג מהרש\"א שם, שקאי על חמשה עשר באב."],["1492","69","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1493","70","ראה ד\"ה נתת ליראיך ה'תשל\"ו (לעיל ע' מח ואילך)."],["1494","71","רמב\"ם הל' מלכים ומלחמותיהן והלכות מלך המשיח ספי\"א."],["1495","72","ראה סידור (עם דא\"ח) סח, א. אגרות-קודש כ\"ק אדמו\"ר מהורש\"ב ח\"א ע' שט."]]],[1500390022,"<h3>בס\"ד. יום ב' פ' עקב, חמשה עשר באב ה'תשמ\"ז<sup data-n=\"1496\">*</sup></h3>\n<b>לא</b> היו ימים טובים לישראל כחמשה עשר באב וכיום הכפורים<sup data-n=\"1497\">1</sup>, ומביא אדמו\"ר (מהורש\"ב) נ\"ע במאמרו המבאר ענין חמשה עשר באב<sup data-n=\"1498\">2</sup>, דאיתא בפע\"ח<sup data-n=\"1499\">3</sup> שהיו\"ט דט\"ו באב הוא שאז הוא שלימות<sup data-n=\"1500\">4</sup> מילוי הלבנה [והענינים שאירעו בחמשה עשר באב (המנוים בגמרא<sup data-n=\"1501\">5</sup>) הם כמו תוצאות מענינו <i>העיקרי</i> של יום זה – שלימות מילוי הלבנה]. ומדייק בהמאמר, הרי זה שביום הט\"ו קיימא סיהרא באשלמותא<sup data-n=\"1502\">6</sup> הוא בכל חודש, ואעפ\"כ לא נקבעו ליו\"ט מלבד פסח (ט\"ו בניסן) וסוכות (ט\"ו בתשרי). וביותר אינו מובן, שמפשטות הלשון לא היו ימים טובים לישראל כחמשה עשר באב כו' משמע שהוא יו\"ט גדול יותר מכל הימים טובים, גם מהימים טובים דפסח וסוכות, אף שגם ימים טובים אלה הם בט\"ו בחודש<sup data-n=\"1503\">7</sup>. ונקודת הביאור בזה (בהמאמר), שעיקר המעלה דמילוי ושלימות הלבנה ביום הט\"ו הזה הוא שהמילוי והשלימות הוא לאחרי חסרון, שלאחרי חסרון היא שלימות נעלית יותר מהשלימות שמצד עצמה, כידוע<sup data-n=\"1504\">8</sup> הכלל בעליות וירידות, דהעלי' שלאחרי ירידה היא עלי' למעלה יותר מהדרגא שלפני הירידה, וכל שהירידה היא ביותר, העלי' היא ביותר. ולכן עיקר המעלה דמילוי הלבנה הוא בט\"ו באב, כי בחודש אב, הירידה דהלבנה (וישראל דדומין ללבנה<sup data-n=\"1505\">9</sup>) היא ירידה גדולה ביותר, ולכן העלי' דט\"ו באב (שלאחרי הירידה דתשעה באב) היא עלי' גדולה ביותר.\nב) <b>ויש</b> לומר, דענין הנ\"ל שהיו\"ט דט\"ו באב הוא לפי שאז היא העלי' שלאחרי הירידה דתשעה באב מרומז גם בזה שהענין הראשון שאירע בט\"ו באב הוא שכלו בו מתי מדבר<sup data-n=\"1506\">10</sup>. דענין מתי מדבר קשור עם תשעה באב, שבת\"ב נגזר על דור המדבר שימותו במדבר ולא יכנסו לארץ<sup data-n=\"1497\">1</sup>, וגם קיום הגזירה היתה בתשעה באב,שבכל ת\"ב (דל\"ט שנים האחרונות שהיו במדבר) היו עושין קבריהן<sup data-n=\"1507\">11</sup>. והיו\"ט דט\"ו באב שבו כלו מתי מדבר הוא העלי' שלאחרי הירידה דתשעה באב<sup data-n=\"1508\">12</sup>. ומזה מובן גם בנוגע ל(עיקר) הירידה דתשעה באב שבו חרב הבית בראשונה ובשני'&lt;1&gt; [ובפרט שגם גזירת החורבן היתה באותו היום<sup data-n=\"1509\">13</sup> (תשעה באב דשנה ראשונה שהיו במדבר) שבו נגזר על דור המדבר שלא יכנסו לארץ, ושתי הגזירות היו בשביל אותו החטא (חטא המרגלים)<sup data-n=\"1509\">13</sup>], שבט\"ו באב מאיר מעין הגילוי דלעתיד<sup data-n=\"1510\">14</sup>, שעיקרו<sup data-n=\"1511\">15</sup> הוא בנין ביהמ\"ק השלישי<sup data-n=\"1512\">16</sup> – העלי' שלאחרי הירידה דחורבן בית ראשון ושני.\nג) <b>וממשיך</b> בהמאמר<sup data-n=\"1513\">17</sup> ביאור השייכות דט\"ו [באב] לביהמ\"ק השלישי, שלע\"ל יהיו גם ו\"ה בבחינת י\"ה, כמ\"ש<sup data-n=\"1514\">18</sup> ביום ההוא יהי' (יהי' הוא ב' פעמים י\"ה)<sup data-n=\"1515\">19</sup>. וכיון שיניקת החיצונים היא מבחינת ו\"ה (זו\"ן), משא\"כ מבחינת י\"ה (או\"א) א\"א להיות יניקה, לכן, לע\"ל שגם ו\"ה יהיו כמו י\"ה, לא יהי' שייך אז חורבן וגלות. ומוסיף בהמאמר, שמהחילוקים בין י\"ה (או\"א) לו\"ה (זו\"ן) הוא, דאו\"א הן תרין רעין דלא מתפרשין וזו\"ן זיווגם הוא רק לפרקים<sup data-n=\"1516\">20</sup>. ולע\"ל שאז יהיו ו\"ה כמו י\"ה, גם ו\"ה יהי' זיווגם בתמידות. ולכן, ביהמ\"ק דלעתיד יהי' נצחי<sup data-n=\"1517\">21</sup>. [דנוסף לזה שבביהמ\"ק דלעתיד לא יהי' שייך חורבן לפי שלא יהי' שייך אז יניקת החיצונים, הנה גם הביהמ\"ק עצמו יהי' באופן שאין שייך בו הפסק, אהל<sup data-n=\"1518\">22</sup> בל יצען בל יסע יתדותיו לנצח]. וזוהי השייכות די\"ה [באב] לביהמ\"ק השלישי, כי המעלה דביהמ\"ק השלישי שאין שייך בו הפסק הוא לפי שיהי' בבחינת י\"ה.\n<b>וממשיך</b> בהמאמר<sup data-n=\"1519\">23</sup> בביאור הענין דב' פעמים י\"ה בהקדים הידוע<sup data-n=\"1520\">24</sup> בענין ואתחנן בגימטריא תקט\"ו<sup data-n=\"1521\">25</sup>, ת\"ק עם ט\"ו, דת\"ק הוא ה' חסדים דאריך [שכל אחד מהם כלול ממאה] ולמעלה יותר ה' חסדים דעתיק, וענין תקט\"ו הוא שה\"חדאריך ודעתיק מאירים בי\"ה. וזהו גם חמש עשרה אמה קלעים לכתף<sup data-n=\"1522\">26</sup>, חמש עשרה (אמה) הוא י\"ה וכתף בגימטריא ת\"ק<sup data-n=\"1523\">27</sup>, וענין חמש עשרה אמה קלעים לכתף הוא המשכת עתיק בי\"ה. וזהו גם ענין ב' פעמים י\"ה, כי בחצר המשכן היו שני כתפים ובכל אחד מהם חמש עשרה קלעים<sup data-n=\"1524\">28</sup>, ושני פעמים חמש עשרה הוא ב' פעמים י\"ה. ויש לומר, שהשייכות דחמש עשרה קלעים לכתף (המשכת עתיק בי\"ה) עם ב' פעמים י\"ה (שזו\"ן הם כמו או\"א) היא, כי מצד סדר ההשתלשלות, זו\"ן הם למטה מאו\"א, ובכדי שזו\"ן יהיו כמו או\"א הוא ע\"י המשכת הכתר שלמעלה מהשתלשלות, ובכתר עצמו – עתיק. והחילוק דשני הביאורים (בהמאמר) הוא, שבביאור הראשון מדבר בענין העלי' דזו\"ן, ובביאור השני מדבר בענין המשכת עתיק (השורש והסיבה להעלי' דזו\"ן). וממשיך בהמאמר דט\"ו באב שייך גם לביאור השני דשני פעמים י\"ה, כי בט\"ו באב הוא גילוי ה\"ח דעתיק באו\"א<sup data-n=\"1525\">29</sup>, ועי\"ז נמשך גילוי עתיק גם במלכות<sup data-n=\"1526\">30</sup>. ועיקר גילוי זה יהי' לע\"ל, אלא שמעין זה מאיר גם עכשיו בט\"ו באב, כנ\"ל (סעיף ב) שבט\"ו באב הוא מעין הגילוי דלעתיד.\nד) <b>והנה</b> הטעם לזה שבט\"ו באב מאיר גילוי זה הוא לפי שבט\"ו באב הוא השלימות דהלבנה שלאחרי הירידה דתשעה באב (כנ\"ל סעיף א). וצריך להבין, דעיקר קיימא סיהרא באשלמותא (בחמשה עשר בחודש) הוא רק בנוגע להגילוי שלה. דהלבנה עצמה היא בשלימות בכל ימי החודש, והמעלה דחמשה עשר היא שהשלימות דהלבנה היא בגילוי. וכיון שכל הענינים שבתורה הם בתכלית הדיוק, צריך לומר, שהמעלה דחמשה עשר באב היא בענין הגילוי. וצריך ביאור, הרי בט\"ו באב הוא מעין הגילוי דביהמ\"ק דלעתיד, שיהי' (נוסף על הגילוי דבית ראשון ובית שני<sup data-n=\"1527\">31</sup>) גדול מבית ראשון ושני<sup data-n=\"1528\">32</sup>, והגדלות דבית השלישי על בית ראשון ושני היא גדלות באין ערוך, וכמובן גם מהמבואר לעיל (סעיף ג) שביהמ\"ק השלישי קשור עם ענין ב' פעמים י\"ה שזו\"ן יהי' כמו או\"א ושבאו\"א יהי' גילוי עתיק, ואעפ\"כ, מקשרים המעלה דחמשה עשר באב עם זה שבחמשה עשר הוא שלימות הלבנה, שלימות בענין הגילוי<sup data-n=\"1529\">33</sup>.<b>גם</b> צריך להבין, דכיון שהענין דחמשה עשר באב הוא ע\"ד הענין דחמש עשרה אמה קלעים לכתף שהיו בחצר המשכן, שהי' עוד לפני הענין דחמשה עשר באב, גם לפני ענין הראשון שאירע בחמשה עשר באב, יום שכלו בו מתי מדבר [ויתירה מזו – גם לפני שילוח המרגלים שבשביל זה נגזר הענין דמתי מדבר], מהו גודל העילוי והחידוש דחמשה עשר באב, ועד שלא היו ימים טובים לישראל כחמשה עשר באב.\n<b>והנה</b> ענין זה (שהיו\"ט דט\"ו באב קשור עם ענין הגילוי) מובן גם מזה שמהטעמים על קביעת היו\"ט דחמשה עשר באב הוא לפי שהוא יום שכלו בו מתי מדבר (כנ\"ל סעיף ב), דתוכן יום שכלו בו מתי מדבר הוא, שאז נתברר ונתגלה, איגלאי מילתא למפרע<sup data-n=\"1530\">34</sup>, <i>שתשעה באב</i> הוא יום שכלו בו מתי מדבר&lt;11&gt;. ואעפ\"כ קבעו היו\"ט בחמשה עשר באב, שבו נתברר ונתגלה שכלו מתי מדבר, כי יו\"ט זה קשור עם ענין הגילוי.\nה) <b>ויובן</b> זה בהקדים, דכמו שהגזירה דמתי מדבר כלתה בת\"ב, אלא שלא ידעו ברור עד שנתמלאה הלבנה ביום הט\"ו&lt;11&gt;, עד\"ז הוא בהגזירה דחורבן ביהמ\"ק והגלות, שביטול גזירה זו הוא בתשעה באב, דבתשעה באב נולד משיח<sup data-n=\"1531\">35</sup>, ובמוצאי תשעה באב מקדשין הלבנה שענינה (דקידוש לבנה) הוא שהם<sup data-n=\"1532\">36</sup> עתידים להתחדש כמותה<sup data-n=\"1533\">37</sup>, אלא שגילוי ענין זה (ובשלימות) הוא בט\"ו באב, שבו הוא מילוי ושלימות הלבנה.\n<b>ובעומק</b> יותר יש לומר, דזה שבתשעה באב היתה התחלת הענין דגאולה העתידה הוא לא רק ברגע שלאחרי החורבן שאז נולד מושיען של ישראל, אלא גם לפנ\"ז. שהרי זה שעלה ארי' והחריב את אריאל הוא <i>על מנת</i> שיבוא ארי' ויבנה אריאל<sup data-n=\"1534\">38</sup>, דמזה מובן, שהכוונה דיבנה אריאל היתה לפני שהחריב את אריאל<sup data-n=\"1535\">39</sup>, אלא שאז, היתה כוונה ומחשבה זו בהעלם (בדרגא דמחשבה) ולא נמשכה בגילוי, בכדי שיוכל להיות חורבן ביהמ\"ק, שעי\"ז דוקא יהי' בנין ביהמ\"ק השלישי שגדול יותר מבית ראשון ושני, וברגע שלאחרי החורבן, הותחל הגילוי דגאולה העתידה, <i>נולד</i> מושיען של ישראל. אלא שהלידה שבת\"ב הוא רק התחלת הגילוי [כמובן גםמהענינים דת\"ב שישנם גם לאחרי מנחת ת\"ב וגם לאחרי קידוש לבנה במוצאי ת\"ב<sup data-n=\"1536\">40</sup>], ועיקר הגילוי הוא בט\"ו באב. ועפ\"ז יובן הקשר דמעלת חמשה עשר באב עם זה שבחמשה עשר הוא שלימות הלבנה, שהיא שלימות בענין הגילוי, כי ענין חמשה עשר באב הוא שבו הוא גילוי הגאולה שהיתה (בהעלם, במחשבה וכוונה) בת\"ב.\nו) <b>ויש</b> לומר, דהטעם על זה שהציווי<sup data-n=\"1537\">41</sup> ועשו לי מקדש, שהוא ציווי לדורות לעשות בית לה'<sup data-n=\"1538\">42</sup> [ציווי על כל בתי מקדשות, כולל גם ביהמ\"ק דלעתיד], נאמר (בגילוי) בנוגע לעשיית המשכן, הוא, לפי שבהמשכן הי' כלול בהעלם גם ביהמ\"ק שהוא דירת קבע<sup data-n=\"1539\">43</sup>, וגם ביהמ\"ק דלעתיד שהוא אהל בל יצען גו', עיקר ענין הקביעות (כנ\"ל סעיף ג). וע\"ד הידוע<sup data-n=\"1540\">44</sup> בענין הגאולות, שבהגאולה דיציאת מצרים נפתח הצינור והיו כלולים בה כל הגאולות, כולל גם הגאולה העתידה. אלא שהגילוי דביהמ\"ק השלישי ודגאולה השלישית הוא ע\"י העבודה שבזמן הגלות, שהיא ע\"ד עבודת התשובה. וכיון שביציאת מצרים היו ישראל במדריגת צדיקים<sup data-n=\"1541\">45</sup>, לכן, הענין דגאולה העתידה שכלול בהגאולה דיציאת מצרים, הי' אז בהעלם.\n<b>ועפ\"ז</b> יש לבאר זה שבחצר המשכן היו חמש עשרה אמה קלעים לכתף, אף שענין זה שייך לביהמ\"ק השלישי, כי במשכן הי' כלול גם ביהמ\"ק וגם ביהמ\"ק השלישי. ואעפ\"כ לא היו ימים טובים לישראל כחמשה עשר באב, כי לפני חטא המרגלים, כאשר מצד סדר ההשתלשלות לא הי' נתינת מקום לחורבן ביהמ\"ק ובמילא גם לא לבנין ביהמ\"ק השלישי, הי' זה בתכלית ההעלם. ולאחרי חטא המרגלים, כשנגזר על דור המדבר שלא יכנסו לארץ וגם התחלת הענין דחורבן ביהמ\"ק [כי אז היתה התחלת ההמשכה דביהמ\"ק השלישי בהדרגא דמחשבה], הנה בחמשה עשר באב בכל שנה (מתחיל מחמשה עשר באב בו כלו מתי מדבר, ועאכו\"כ לאחרי חורבן ביהמ\"ק) הוא גילוי הפנימיות דחמש עשרה אמה קלעים לכתף שבחצר המשכן, שענינם הוא המשכת עתיק בי\"ה ועי\"ז גם במלכות, ענין אהל בל יצען, ביהמ\"ק השלישי שאין (שייך) בו הפסק. ואז מתגלה גם הכוונה הפנימית של הבכי' דתשעה באב הראשון, ויבכו העם בלילה ההוא<sup data-n=\"1542\">46</sup> שעי\"ז נקבע בכי' לדורות&lt;13&gt;, שהיא בכדי שתהי' הבכי' למעליותא דלע\"ל, בבכי יבואו<sup data-n=\"1543\">47</sup>, בכי' של שמחה<sup data-n=\"1544\">48</sup> מצד התגלות מדרגותהגבוהות<sup data-n=\"1545\">49</sup>, וע\"ד שאמרו רז\"ל<sup data-n=\"1546\">50</sup> גבי ר\"ע שכשהשיג סודות התורה בשיר השירים זלגו עיניו דמעות, דמעות של שמחה מצד ריבוי האור<sup data-n=\"1547\">51</sup>.\nז) <b>וזהו</b> שבחמשה עשר באב היו&lt;1&gt; בנות ירושלים [ויש גורסין<sup data-n=\"1548\">52</sup> – בנות ישראל] יוצאות וחולות בכרמים, שהמחול דחמשה עשר באב הוא בדוגמת ומעין המחול דלע\"ל<sup data-n=\"1549\">53</sup> שעתיד<sup data-n=\"1550\">54</sup> הקב\"ה לעשות מחול לצדיקים וכאו\"א מראה באצבעו ואומר<sup data-n=\"1551\">55</sup> הנה<sup data-n=\"1552\">56</sup> אלקינו זה קוינו לו ויושיענו זה ה' קוינו לו נגילה ונשמחה בישועתו, דביציאת מצרים אמרו \"זה\" פעם אחת (זה א-לי ואנוהו<sup data-n=\"1553\">57</sup>) ולע\"ל יאמרו שני פעמים זה<sup data-n=\"1554\">58</sup> (הנה אלקינו זה גו' זה הוי' גו'). דביציאת מצרים שהיו אז במדריגת צדיקים אמרו זה רק פעם אחת – גילוי הוי' דז\"א, ולע\"ל, שיהיו במדריגת בעלי תשובה [דתשובה היא כפלים לתושי'<sup data-n=\"1555\">59</sup>] יאמרו שני פעמים זה – גילוי הוי' דז\"א וגילוי הוי' דעתיק<sup data-n=\"1556\">60</sup>. וממשיך בכתוב נגילה ונשמחה בישועת<i>ו</i>, דיש לומר, שישועתו (דהקב\"ה) שלאחרי \"זה\" השני, הוא פנימיות עתיק. וכידוע<sup data-n=\"1557\">61</sup> שלע\"ל יהי' (גם) הגילוי דפנימיות עתיק.\n<b>ויהי</b> רצון, שכל ענינים אלו יהיו בקרוב ממש, ובפרט לאחרי שאמרו בההפטורה דמנחת ת\"ב קרובה ישועתי לבוא<sup data-n=\"1558\">62</sup>, שישועת<i>י</i> (דהקב\"ה), הישועה שעלי' נאמר נגילה ונשמחה בישועת<i>ו</i>, היא קרובה לבוא בקרוב ממש ובעגלא דידן, אמן<sup data-n=\"1559\">63</sup> כן יהי רצון.\n**********",[["1496","*","יצא לאור ב<b>קונטרס ט\"ו באב – תש\"נ</b>, \"לקראת חמשה עשר באב . . <i>א' עקב</i>,<i> יד מנ\"א</i>,<i> שנת ה'תש\"נ</i>\"."],["1497","1","תענית כו, ב (במשנה)."],["1498","2","ד\"ה נחמו עת\"ר [רישומי דברים דהמאמר נדפסו בסה\"מ עת\"ר ע' ריח ואילך. והנחה – שם ע' רכא ואילך]. וראה גם אוה\"ת ואתחנן כרך ו ע' ב'קצז. נ\"ך כרך ב ע' א'צו. וראה בארוכה ד\"ה זה ה'תשל\"ה (לעיל ע' קסז ואילך)."],["1499","3","סוף שער חג השבועות – \"דרוש על סוד ט\"ו באב\"."],["1500","4","ראה לעיל שם הערה 7."],["1501","5","תענית ל, ב ואילך. ב\"ב קכא, א. ולהעיר שבגמרא מנוים ו' ענינים, ובפע\"ח שם ז'."],["1502","6","זהר ח\"ב רטו, א. וראה גם שם ח\"א קנ, רע\"א. רכה, סע\"ב. רמט, ב. ח\"ב פה, רע\"א. ובשמו\"ר פט\"ו, כו: כיון שבא שלמה <i>נתמלא</i> דיסקוס של לבנה. וראה הנסמן לעיל ע' קעא הערה 39."],["1503","7","ראה זהר ח\"ב קצד, א (הובא באוה\"ת ואתחנן שם ע' ב'קצד) \"מועד כו' יום חדוה דסיהרא לא שלטא בה פגימותא\". ויש לומר, שגם חג השבועות, כיון שאינו ביום קבוע בחודש סיון וקביעותו היא יום הנ\"א מט\"ו בניסן (ר\"ה ו, ב. שו\"ע אדה\"ז או\"ח ר\"ס תצד), שייך ל\"חדוה דסיהרא\"."],["1504","8","ראה בהנסמן לעיל ע' קסז הערה 9."],["1505","9","ראה ב\"ר פ\"ו, ג. שמו\"ר שם."],["1506","10","תענית וב\"ב שם."],["1507","11","פרש\"י ותוספות תענית ל, ב; רשב\"ם ב\"ב קכא, סע\"א – מאיכ\"ר פתיחתא לג."],["1508","12","להעיר שט\"ו באב הוא בסמיכות להשבת שלאחרי ת\"ב [שבת נחמו], שבו קוראין פרשת ואתחנן, שבה נאמר (ד, ד) ואתם הדבקים גו' חיים כולכם היום, שכבר כלו מתי מדבר (פרש\"י חוקת כ, כב). וראה לקמן ס\"ג, שט\"ו באב שייך גם לענין תקט\"ו, הגימטריא ד\"ואתחנן\"."],["1509","13","ראה תענית כט, א. וש\"נ."],["1510","14","ד\"ה נחמו עת\"ר (סה\"מ עת\"ר ע' רכ. שם ע' רל). ובאוה\"ת ואתחנן שם (ע' ב'קצח) \"יתראה בהנחמה בט\"ו באב\"."],["1511","15","ראה ד\"ה גדול יהי' כבוד הבית הזה גו' ה'תשכ\"ב ס\"ב וסי\"ב (לעיל ע' קיא ואילך)."],["1512","16","ראה גם תענית כו, ב (במשנה) \"וביום שמחת לבו זה בנין בית המקדש שיבנה במהרה בימינו\", ובחדא\"ג מהרש\"א שם \"דאחמשה עשר באב קאי, שטעמי שמחתו . . תלויים בבנין המקדש\"."],["1513","17","ד\"ה נחמו עת\"ר – סה\"מ שם ע' רכ. שם ע' רכח ואילך. אוה\"ת ואתחנן שם ע' ב'קצא."],["1514","18","זכרי' יד, ט."],["1515","19","ל\"ת להאריז\"ל עה\"פ. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380339\" data-slug=\"likkutei-torah\" data-id=\"4001380339\">לקו\"ת במדבר ז, ד</a>."],["1516","20","זח\"ג ד, א. ועוד. וראה לקמן ע' רמ ואילך. וש\"נ."],["1517","21","זהר ח\"א כח, א. ח\"ג רכא, א."],["1518","22","ישעי' לג, כ."],["1519","23","סה\"מ עת\"ר ע' רכ. שם ע' רל. וראה גם אוה\"ת ואתחנן שם ע' ב'קצט (ושם ע' ב'קצו)."],["1520","24","אוה\"ת ואתחנן ס\"ע קיד ואילך."],["1521","25","דב\"ר פי\"א, יו\"ד. דעת זקנים מבעה\"ת ר\"פ ואתחנן."],["1522","26","תרומה כז, יד."],["1523","27","באוה\"ת שם ע' קטז מציין ל\"מאו\"א אות ק' סל\"ב, עמה\"מ שער או\"א פ\"ל. ועיין בזה ג\"כ בהרמ\"ז ר\"פ תרומה קכו, סע\"א\"."],["1524","28","תרומה שם, יד-טו."],["1525","29","הרמז דענין זה ב\"ט\"ו באב\": אב תוכנו הוא (גם) רצון (כתר), וט\"ו הוא י\"ה (חו\"ב). וענין ט\"ו באב הוא המשכת הכתר בחו\"ב (אוה\"ת ואתחנן כרך ו ע' ב'קצט)."],["1526","30","כ\"מ בסה\"מ עת\"ר שם ע' רלא."],["1527","31","ראה זח\"ג רכא, א שבביהמ\"ק השלישי יהיו כלולים (גם) בית הראשון והשני."],["1528","32","כמ\"ש (חגי ב, ט) גדול יהי' כבוד הבית הזה האחרון מן הראשון, ומפרש בזהר (ח\"א כח, א. תקו\"ז תיקון ח) שהבית הזה האחרון קאי על ביהמ\"ק השלישי. וראה בארוכה ד\"ה גדול יהי' כבוד הבית הזה גו' הנ\"ל."],["1529","33","בהשיחות דהתוועדות זו (ט\"ו באב ה'תשמ\"ז, התוועדויות תשמ\"ז ח\"ד ע' 195, ובהערה 10 שם) לפני המאמר, שתכלית בריאת הלבנה הוא להאיר על הארץ, ולכן, החסרון ד\"להאיר על הארץ\" (לפני מילוי הלבנה) הוא כמו חסרון בהלבנה עצמה, וע\"י השלימות ב\"להאיר על הארץ\" (בט\"ו בחודש) נעשה שלימות דהלבנה, שהיא משלמת כוונת בריאתה. אבל ענין זה הוא ביאור במעלת יום הט\"ו בכלל, והדיוק בהמאמר הוא – הקשר דענין זה עם <i>ט\"ו באב</i>."],["1530","34","ל' הש\"ס – פסחים לא, רע\"א. ועוד."],["1531","35","ראה ירושלמי ברכות פ\"ב ה\"ד; איכ\"ר פ\"א, נא, שברגע שלאחרי החורבן, כשגעתה פרתו פעם שני', נולד מושיען של ישראל. ובפע\"ח שער חג השבועות ספ\"א מפורש <i>שבט' באב</i> נולד משיח, ולכן אומרים ברכת הלבנה במוצאי ת\"ב לבשר כו' שהם עתידים להתחדש כמותה. ובשער הכוונות ענין ט\"ב בסופו, דהטעם שאומרים נחם במנחת ת\"ב הוא כי במנחת ט\"ב נולד המשיח הנקרא מנחם."],["1532","36","סדר קידוש לבנה (סנהדרין מב, א)."],["1533","37","פע\"ח שבהערה 35."],["1534","38","יל\"ש ירמי' רמז רנט. וראה ד\"ה גדול יהי' גו' הנ\"ל ס\"ג (לעיל ע' קיב)."],["1535","39","להעיר ממאמר רז\"ל (יבמות סב, ב) חייב אדם לפקוד את אשתו בשעה שהוא יוצא לדרך, דמזה מובן, שהפקידה היתה <i>לפני</i> יציאתו של הבעל (הקב\"ה) לדרך.\nועפ\"ז יש לומר <i>שיצירת</i> הולד נעשה מהפקידה שלפני החורבן, וברגע שלאחרי החורבן <i>נולד</i> מושיען של ישראל. וראה בארוכה לעיל ח\"ג ע' פד."],["1536","40","שו\"ע או\"ח סתקנ\"ח."],["1537","41","תרומה כה, ח."],["1538","42","רמב\"ם הל' בית הבחירה פ\"א ה\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211149\" data-slug=\"likkutei-sichot\" data-id=\"1300211149\">לקו\"ש חכ\"א ע' 149</a> ואילך. וראה גם שם ע' 264 ואילך."],["1539","43","ראה שמואל-ב ז, ו. פרש\"י עה\"פ. שהש\"ר פ\"א, טז (ג). זח\"ב רמא, א. תו\"א ר\"פ ויגש."],["1540","44","סה\"מ ה'תש\"ח ע' 164. וראה ד\"ה כימי צאתך גו' ה'תשי\"ב סעיף יו\"ד (לעיל ח\"ג ריש ע' קסט)."],["1541","45","סה\"מ תרל\"ו ח\"ב ע' שמ. תרנ\"ב ע' ג ואילך. ועוד. וראה לעיל ע' קסח, ובהערה 12 שם."],["1542","46","שלח יד, א."],["1543","47","ירמי' לא, ח."],["1544","48","ראה גם אוה\"ת נ\"ך עה\"פ (ע' שעא) \"בבכי יבואו כמו הבוכה מרוב שמחה שלא יוכל הכלי להכיל\". ובהמשך הענין שם \"כי יהי' הגילוי בזו\"ן כמו באו\"א ע\"ד ביום ההוא יהי'\"."],["1545","49","כ\"ה הלשון בתו\"א שבהערה 51."],["1546","50","ראה זח\"א צח, ב (במהנ\"ע). ט\"ז לשו\"ע או\"ח סרפ\"ח סק\"ב (בשם זהר חדש). וראה גם זהר חדש בראשית ז, א."],["1547","51","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח כו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380868\" data-slug=\"likkutei-torah\" data-id=\"4001380868\">לקו\"ת תצא לז, ד</a>. ועוד."],["1548","52","ראה שינויי נוסחאות למשניות תענית שם. וש\"נ. וראה שיחת ט\"ו מנ\"א ה'תשמ\"ו (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291270\" data-slug=\"likkutei-sichot\" data-id=\"1300291270\">לקו\"ש חכ\"ט ע' 255</a>) הערה 45."],["1549","53","שלכן המימרא שבגמרא (סוף מס' תענית) עתיד הקב\"ה לעשות מחול לצדיקים כו' (דלקמן בפנים) היא על מאמר המשנה יוצאות וחולות בכרמים."],["1550","54","סוף מס' תענית."],["1551","55","פרש\"י שם."],["1552","56","ישעי' כה, ט."],["1553","57","בשלח טו, ב."],["1554","58","שמו\"ר ספכ\"ג."],["1555","59","ראה שמו\"ר רפמ\"ו."],["1556","60","אוה\"ת נ\"ך לישעי' שם ע' רד. וראה גם סה\"מ תרנ\"ד ע' קנד."],["1557","61","פע\"ח שער הק\"ש רפט\"ו. לקו\"ת שה\"ש בסופו (נ, ריש ע\"ג. נא, ג ואילך). ובכ\"מ."],["1558","62","ישעי' נו, א."],["1559","63","ראה משנה סוף מס' תענית ובשינויי נוסחאות שם."]]]]});
